Object.keys(PROPAGATION_TRANSLATION_OVERRIDES).forEach(code => {
  TRANSLATIONS[code] = Object.assign({}, TRANSLATIONS[code] || TRANSLATIONS.en, PROPAGATION_TRANSLATION_OVERRIDES[code]);
});

