    dmarcTagDescRua: '\u041F\u043E\u043B\u0443\u0447\u0430\u0442\u0435\u043B\u0438 \u0430\u0433\u0440\u0435\u0433\u0438\u0440\u043E\u0432\u0430\u043D\u043D\u044B\u0445 \u043E\u0442\u0447\u0451\u0442\u043E\u0432. URI mailto: \u0438\u043B\u0438 https:, \u0440\u0430\u0437\u0434\u0435\u043B\u0451\u043D\u043D\u044B\u0435 \u0437\u0430\u043F\u044F\u0442\u044B\u043C\u0438, \u043A\u043E\u0442\u043E\u0440\u044B\u0435 \u043F\u043E\u043B\u0443\u0447\u0430\u044E\u0442 \u0435\u0436\u0435\u0434\u043D\u0435\u0432\u043D\u044B\u0435 XML-\u043E\u0442\u0447\u0451\u0442\u044B.',
    dmarcTagDescRuf: '\u041F\u043E\u043B\u0443\u0447\u0430\u0442\u0435\u043B\u0438 forensic-/\u043E\u0442\u0447\u0451\u0442\u043E\u0432 \u043E\u0431 \u043E\u0448\u0438\u0431\u043A\u0430\u0445. URI, \u0440\u0430\u0437\u0434\u0435\u043B\u0451\u043D\u043D\u044B\u0435 \u0437\u0430\u043F\u044F\u0442\u044B\u043C\u0438, \u043A\u043E\u0442\u043E\u0440\u044B\u0435 \u043F\u043E\u043B\u0443\u0447\u0430\u044E\u0442 \u043E\u0442\u0447\u0451\u0442\u044B \u043F\u043E \u043E\u0442\u0434\u0435\u043B\u044C\u043D\u044B\u043C \u0441\u0431\u043E\u0439\u043D\u044B\u043C \u0441\u043E\u043E\u0431\u0449\u0435\u043D\u0438\u044F\u043C.',
    dmarcTagDescFo: '\u041F\u0430\u0440\u0430\u043C\u0435\u0442\u0440\u044B forensic-\u043E\u0442\u0447\u0451\u0442\u043E\u0432. \u041E\u043F\u0440\u0435\u0434\u0435\u043B\u044F\u0435\u0442, \u043A\u0430\u043A\u0438\u0435 \u0441\u0431\u043E\u0438 \u0432\u044B\u0437\u044B\u0432\u0430\u044E\u0442 \u043E\u0442\u0447\u0451\u0442 ruf=.',
    dmarcTagDescAdkim: '\u0420\u0435\u0436\u0438\u043C \u0432\u044B\u0440\u0430\u0432\u043D\u0438\u0432\u0430\u043D\u0438\u044F \u0438\u0434\u0435\u043D\u0442\u0438\u0444\u0438\u043A\u0430\u0442\u043E\u0440\u0430 DKIM. s = \u0441\u0442\u0440\u043E\u0433\u0438\u0439 (\u0442\u043E\u0447\u043D\u043E\u0435 \u0441\u043E\u0432\u043F\u0430\u0434\u0435\u043D\u0438\u0435), r = \u043E\u0441\u043B\u0430\u0431\u043B\u0435\u043D\u043D\u044B\u0439 (\u0441\u043E\u0432\u043F\u0430\u0434\u0435\u043D\u0438\u0435 \u043E\u0440\u0433\u0430\u043D\u0438\u0437\u0430\u0446\u0438\u043E\u043D\u043D\u043E\u0433\u043E \u0434\u043E\u043C\u0435\u043D\u0430).',
    dmarcTagDescAspf: '\u0420\u0435\u0436\u0438\u043C \u0432\u044B\u0440\u0430\u0432\u043D\u0438\u0432\u0430\u043D\u0438\u044F \u0438\u0434\u0435\u043D\u0442\u0438\u0444\u0438\u043A\u0430\u0442\u043E\u0440\u0430 SPF. s = \u0441\u0442\u0440\u043E\u0433\u0438\u0439 (\u0442\u043E\u0447\u043D\u043E\u0435 \u0441\u043E\u0432\u043F\u0430\u0434\u0435\u043D\u0438\u0435), r = \u043E\u0441\u043B\u0430\u0431\u043B\u0435\u043D\u043D\u044B\u0439 (\u0441\u043E\u0432\u043F\u0430\u0434\u0435\u043D\u0438\u0435 \u043E\u0440\u0433\u0430\u043D\u0438\u0437\u0430\u0446\u0438\u043E\u043D\u043D\u043E\u0433\u043E \u0434\u043E\u043C\u0435\u043D\u0430).',
    dmarcTagDescRi: '\u0417\u0430\u043F\u0440\u043E\u0448\u0435\u043D\u043D\u044B\u0439 \u0438\u043D\u0442\u0435\u0440\u0432\u0430\u043B \u043C\u0435\u0436\u0434\u0443 \u0430\u0433\u0440\u0435\u0433\u0438\u0440\u043E\u0432\u0430\u043D\u043D\u044B\u043C\u0438 \u043E\u0442\u0447\u0451\u0442\u0430\u043C\u0438, \u0432 \u0441\u0435\u043A\u0443\u043D\u0434\u0430\u0445. \u041F\u043E \u0443\u043C\u043E\u043B\u0447\u0430\u043D\u0438\u044E 86400 (\u043E\u0434\u0438\u043D \u0434\u0435\u043D\u044C).',
    dmarcTagDescRf: '\u0424\u043E\u0440\u043C\u0430\u0442 forensic-\u043E\u0442\u0447\u0451\u0442\u043E\u0432. \u041F\u043E \u0443\u043C\u043E\u043B\u0447\u0430\u043D\u0438\u044E afrf (Authentication Failure Reporting Format).',
    dmarcTagDescUnknown: '\u041D\u0435\u0440\u0430\u0441\u043F\u043E\u0437\u043D\u0430\u043D\u043D\u044B\u0439 \u0442\u0435\u0433 DMARC. \u041F\u0440\u043E\u0432\u0435\u0440\u044C\u0442\u0435 \u043E\u043F\u0435\u0447\u0430\u0442\u043A\u0438 \u0438\u043B\u0438 \u043D\u0435\u043F\u043E\u0434\u0434\u0435\u0440\u0436\u0438\u0432\u0430\u0435\u043C\u044B\u0439 \u0441\u0438\u043D\u0442\u0430\u043A\u0441\u0438\u0441.',
    dmarcValueDescPolicyNone: '\u0422\u043E\u043B\u044C\u043A\u043E \u043C\u043E\u043D\u0438\u0442\u043E\u0440\u0438\u043D\u0433. \u041F\u043E\u043B\u0443\u0447\u0430\u0442\u0435\u043B\u0438 \u043D\u0435 \u043F\u0440\u0438\u043C\u0435\u043D\u044F\u044E\u0442 \u0434\u0435\u0439\u0441\u0442\u0432\u0438\u044F \u043A \u0441\u0431\u043E\u044F\u043C, \u043D\u043E \u0432\u0441\u0451 \u0440\u0430\u0432\u043D\u043E \u043E\u0442\u043F\u0440\u0430\u0432\u043B\u044F\u044E\u0442 \u043E\u0442\u0447\u0451\u0442\u044B.',
    dmarcValueDescPolicyQuarantine: '\u041F\u043E\u043C\u0435\u0449\u0430\u0442\u044C \u043D\u0435 \u043F\u0440\u043E\u0448\u0435\u0434\u0448\u0438\u0435 \u043F\u0440\u043E\u0432\u0435\u0440\u043A\u0443 \u0441\u043E\u043E\u0431\u0449\u0435\u043D\u0438\u044F \u0432 \u043A\u0430\u0440\u0430\u043D\u0442\u0438\u043D (\u043E\u0431\u044B\u0447\u043D\u043E \u0434\u043E\u0441\u0442\u0430\u0432\u043A\u0430 \u0432 \u041D\u0435\u0436\u0435\u043B\u0430\u0442\u0435\u043B\u044C\u043D\u0443\u044E \u043F\u043E\u0447\u0442\u0443 / \u0421\u043F\u0430\u043C).',
    dmarcValueDescPolicyReject: '\u041E\u0442\u043A\u043B\u043E\u043D\u044F\u0442\u044C \u043D\u0435 \u043F\u0440\u043E\u0448\u0435\u0434\u0448\u0438\u0435 \u043F\u0440\u043E\u0432\u0435\u0440\u043A\u0443 \u0441\u043E\u043E\u0431\u0449\u0435\u043D\u0438\u044F \u043D\u0435\u043F\u043E\u0441\u0440\u0435\u0434\u0441\u0442\u0432\u0435\u043D\u043D\u043E \u043D\u0430 \u0443\u0440\u043E\u0432\u043D\u0435 SMTP.',
    dmarcValueDescAlignRelaxed: '\u041E\u0441\u043B\u0430\u0431\u043B\u0435\u043D\u043D\u044B\u0439: \u0434\u043E\u043C\u0435\u043D From: \u0438 \u0430\u0443\u0442\u0435\u043D\u0442\u0438\u0444\u0438\u0446\u0438\u0440\u043E\u0432\u0430\u043D\u043D\u044B\u0439 \u0434\u043E\u043C\u0435\u043D \u0434\u043E\u043B\u0436\u043D\u044B \u0438\u043C\u0435\u0442\u044C \u043E\u0434\u0438\u043D \u043E\u0440\u0433\u0430\u043D\u0438\u0437\u0430\u0446\u0438\u043E\u043D\u043D\u044B\u0439 \u0434\u043E\u043C\u0435\u043D.',
    dmarcValueDescAlignStrict: '\u0421\u0442\u0440\u043E\u0433\u0438\u0439: \u0434\u043E\u043C\u0435\u043D From: \u0438 \u0430\u0443\u0442\u0435\u043D\u0442\u0438\u0444\u0438\u0446\u0438\u0440\u043E\u0432\u0430\u043D\u043D\u044B\u0439 \u0434\u043E\u043C\u0435\u043D \u0434\u043E\u043B\u0436\u043D\u044B \u0442\u043E\u0447\u043D\u043E \u0441\u043E\u0432\u043F\u0430\u0434\u0430\u0442\u044C.',
    dmarcValueDescFoZero: '0: \u0441\u043E\u0437\u0434\u0430\u0432\u0430\u0442\u044C \u043E\u0442\u0447\u0451\u0442 \u0442\u043E\u043B\u044C\u043A\u043E \u043A\u043E\u0433\u0434\u0430 \u0412\u0421\u0415 \u0431\u0430\u0437\u043E\u0432\u044B\u0435 \u043C\u0435\u0445\u0430\u043D\u0438\u0437\u043C\u044B (SPF \u0438 DKIM) \u043D\u0435 \u043F\u0440\u043E\u0445\u043E\u0434\u044F\u0442 \u043F\u0440\u043E\u0432\u0435\u0440\u043A\u0443.',
    dmarcValueDescFoOne: '1: \u0441\u043E\u0437\u0434\u0430\u0432\u0430\u0442\u044C \u043E\u0442\u0447\u0451\u0442, \u043A\u043E\u0433\u0434\u0430 \u041B\u042E\u0411\u041E\u0419 \u0431\u0430\u0437\u043E\u0432\u044B\u0439 \u043C\u0435\u0445\u0430\u043D\u0438\u0437\u043C \u043D\u0435 \u043F\u0440\u043E\u0445\u043E\u0434\u0438\u0442 \u043F\u0440\u043E\u0432\u0435\u0440\u043A\u0443 (\u0440\u0435\u043A\u043E\u043C\u0435\u043D\u0434\u0443\u0435\u0442\u0441\u044F).',
    dmarcValueDescFoD: 'd: \u0441\u043E\u0437\u0434\u0430\u0432\u0430\u0442\u044C \u043E\u0442\u0447\u0451\u0442 \u043E \u0441\u0431\u043E\u0435 DKIM, \u043A\u043E\u0433\u0434\u0430 \u043F\u043E\u0434\u043F\u0438\u0441\u044C DKIM \u043D\u0435 \u043F\u0440\u043E\u0445\u043E\u0434\u0438\u0442 \u043F\u0440\u043E\u0432\u0435\u0440\u043A\u0443, \u043D\u0435\u0437\u0430\u0432\u0438\u0441\u0438\u043C\u043E \u043E\u0442 \u0432\u044B\u0440\u0430\u0432\u043D\u0438\u0432\u0430\u043D\u0438\u044F.',
    dmarcValueDescFoS: 's: \u0441\u043E\u0437\u0434\u0430\u0432\u0430\u0442\u044C \u043E\u0442\u0447\u0451\u0442 \u043E \u0441\u0431\u043E\u0435 SPF, \u043A\u043E\u0433\u0434\u0430 \u043E\u0446\u0435\u043D\u043A\u0430 SPF \u043D\u0435 \u043F\u0440\u043E\u0445\u043E\u0434\u0438\u0442 \u043F\u0440\u043E\u0432\u0435\u0440\u043A\u0443, \u043D\u0435\u0437\u0430\u0432\u0438\u0441\u0438\u043C\u043E \u043E\u0442 \u0432\u044B\u0440\u0430\u0432\u043D\u0438\u0432\u0430\u043D\u0438\u044F.',
    dmarcValueDescRfAfrf: 'Authentication Failure Reporting Format (RFC 6591). \u0415\u0434\u0438\u043D\u0441\u0442\u0432\u0435\u043D\u043D\u043E\u0435 \u0448\u0438\u0440\u043E\u043A\u043E \u043F\u043E\u0434\u0434\u0435\u0440\u0436\u0438\u0432\u0430\u0435\u043C\u043E\u0435 \u0437\u043D\u0430\u0447\u0435\u043D\u0438\u0435.',
    dmarcValueDescPercentFull: '\u041F\u0440\u0438\u043C\u0435\u043D\u044F\u0435\u0442\u0441\u044F \u043A 100% \u043D\u0435 \u043F\u0440\u043E\u0448\u0435\u0434\u0448\u0438\u0445 \u043F\u0440\u043E\u0432\u0435\u0440\u043A\u0443 \u0441\u043E\u043E\u0431\u0449\u0435\u043D\u0438\u0439 (\u043F\u043E\u043B\u043D\u043E\u0435 \u043F\u0440\u0438\u043C\u0435\u043D\u0435\u043D\u0438\u0435).',
    dmarcValueDescPercentPartial: '\u0427\u0430\u0441\u0442\u0438\u0447\u043D\u043E\u0435 \u0440\u0430\u0437\u0432\u0451\u0440\u0442\u044B\u0432\u0430\u043D\u0438\u0435. \u041F\u043E\u043B\u0438\u0442\u0438\u043A\u0430 \u043F\u0440\u0438\u043C\u0435\u043D\u044F\u0435\u0442\u0441\u044F \u0442\u043E\u043B\u044C\u043A\u043E \u043A {percent}% \u043D\u0435 \u043F\u0440\u043E\u0448\u0435\u0434\u0448\u0438\u0445 \u043F\u0440\u043E\u0432\u0435\u0440\u043A\u0443 \u0441\u043E\u043E\u0431\u0449\u0435\u043D\u0438\u0439.'
  }
};

