    spfDescUnknown: '\u0645\u0635\u0637\u0644\u062d SPF \u063a\u064a\u0631 \u0645\u0639\u0631\u0648\u0641. \u062a\u062d\u0642\u0642 \u0645\u0646 \u0627\u0644\u0623\u062e\u0637\u0627\u0621 \u0627\u0644\u0645\u0637\u0628\u0639\u064a\u0629 \u0623\u0648 \u0628\u0646\u0627\u0621 \u0627\u0644\u062c\u0645\u0644\u0629 \u063a\u064a\u0631 \u0627\u0644\u0645\u062f\u0639\u0648\u0645.',
    dmarcExplainedTooltip: '\u062a\u062d\u0644\u064a\u0644 \u0633\u062c\u0644 DMARC \u0647\u0630\u0627 \u0625\u0644\u0649 \u0648\u0633\u0645 \u0648\u0642\u064a\u0645\u0629 \u0648\u0648\u0635\u0641 \u0645\u062e\u062a\u0635\u0631 \u0644\u0643\u0644 \u0648\u0633\u0645 \u0648\u0642\u064a\u0645\u062a\u0647.',
    dmarcExplainedLegend: '\u0648\u0633\u0648\u0645 DMARC \u0647\u064a \u0623\u0632\u0648\u0627\u062c \u0645\u0641\u062a\u0627\u062d=\u0642\u064a\u0645\u0629 \u0645\u0641\u0635\u0648\u0644\u0629 \u0628\u0641\u0648\u0627\u0635\u0644 \u0645\u0646\u0642\u0648\u0637\u0629. v= \u0648 p= \u0645\u0637\u0644\u0648\u0628\u0627\u0646\u061b \u0648\u0627\u0644\u0628\u0627\u0642\u064a \u0627\u062e\u062a\u064a\u0627\u0631\u064a \u0644\u0643\u0646\u0647 \u0645\u0648\u0635\u0649 \u0628\u0647 \u0644\u0644\u062a\u0642\u0627\u0631\u064a\u0631 \u0648\u0627\u0644\u0645\u062d\u0627\u0630\u0627\u0629.',
    dmarcTagDescVersion: '\u0625\u0635\u062f\u0627\u0631 DMARC. \u064a\u062c\u0628 \u0623\u0646 \u064a\u0643\u0648\u0646 DMARC1 \u0648\u0623\u0646 \u064a\u0638\u0647\u0631 \u0623\u0648\u0644\u064b\u0627.',
    dmarcTagDescPolicy: '\u0633\u064a\u0627\u0633\u0629 \u0627\u0644\u0645\u062c\u0627\u0644 \u0646\u0641\u0633\u0647. \u062a\u062e\u0628\u0631 \u0627\u0644\u0645\u0633\u062a\u0644\u0645\u064a\u0646 \u0628\u0645\u0627 \u064a\u062c\u0628 \u0641\u0639\u0644\u0647 \u0645\u0639 \u0627\u0644\u0631\u0633\u0627\u0626\u0644 \u0627\u0644\u062a\u064a \u062a\u0641\u0634\u0644 \u0641\u064a DMARC.',
    dmarcTagDescSubdomainPolicy: '\u0633\u064a\u0627\u0633\u0629 \u0627\u0644\u0645\u062c\u0627\u0644\u0627\u062a \u0627\u0644\u0641\u0631\u0639\u064a\u0629. \u062a\u062a\u062c\u0627\u0648\u0632 p= \u0644\u0644\u0645\u062c\u0627\u0644\u0627\u062a \u0627\u0644\u0641\u0631\u0639\u064a\u0629 \u0639\u0646\u062f \u0648\u062c\u0648\u062f\u0647\u0627.',
    dmarcTagDescPercent: '\u0627\u0644\u0646\u0633\u0628\u0629 \u0627\u0644\u0645\u0626\u0648\u064a\u0629 \u0644\u0644\u0631\u0633\u0627\u0626\u0644 \u0627\u0644\u0641\u0627\u0634\u0644\u0629 \u0627\u0644\u062a\u064a \u062a\u064f\u0637\u0628\u0642 \u0639\u0644\u064a\u0647\u0627 \u0627\u0644\u0633\u064a\u0627\u0633\u0629 \u0623\u062b\u0646\u0627\u0621 \u0627\u0644\u0637\u0631\u062d. \u0627\u0644\u0627\u0641\u062a\u0631\u0627\u0636\u064a 100.',
    dmarcTagDescRua: '\u0648\u062c\u0647\u0627\u062a \u0627\u0644\u062a\u0642\u0627\u0631\u064a\u0631 \u0627\u0644\u0645\u062c\u0645\u0639\u0629. \u0639\u0646\u0627\u0648\u064a\u0646 URI \u0645\u0646 \u0646\u0648\u0639 mailto: \u0623\u0648 https: \u0645\u0641\u0635\u0648\u0644\u0629 \u0628\u0641\u0648\u0627\u0635\u0644 \u062a\u0633\u062a\u0642\u0628\u0644 \u062a\u0642\u0627\u0631\u064a\u0631 XML \u064a\u0648\u0645\u064a\u0629.',
    dmarcTagDescRuf: '\u0648\u062c\u0647\u0627\u062a \u062a\u0642\u0627\u0631\u064a\u0631 \u0627\u0644\u0641\u0634\u0644/\u0627\u0644\u0637\u0628 \u0627\u0644\u0634\u0631\u0639\u064a. \u0639\u0646\u0627\u0648\u064a\u0646 URI \u0645\u0641\u0635\u0648\u0644\u0629 \u0628\u0641\u0648\u0627\u0635\u0644 \u062a\u0633\u062a\u0642\u0628\u0644 \u062a\u0642\u0627\u0631\u064a\u0631 \u0641\u0634\u0644 \u0644\u0643\u0644 \u0631\u0633\u0627\u0644\u0629.',
    dmarcTagDescFo: '\u062e\u064a\u0627\u0631\u0627\u062a \u0627\u0644\u062a\u0642\u0627\u0631\u064a\u0631 \u0627\u0644\u0637\u0628 \u0627\u0644\u0634\u0631\u0639\u064a\u0629. \u062a\u062a\u062d\u0643\u0645 \u0641\u064a \u062d\u0627\u0644\u0627\u062a \u0627\u0644\u0641\u0634\u0644 \u0627\u0644\u062a\u064a \u062a\u0624\u062f\u064a \u0625\u0644\u0649 \u062a\u0642\u0631\u064a\u0631 ruf=.',
    dmarcTagDescAdkim: '\u0648\u0636\u0639 \u0645\u062d\u0627\u0630\u0627\u0629 \u0645\u0639\u0631\u0641 DKIM. s = \u0635\u0627\u0631\u0645 (\u062a\u0637\u0627\u0628\u0642 \u062a\u0627\u0645)\u060c r = \u0645\u0631\u0646 (\u0646\u0641\u0633 \u0627\u0644\u0645\u062c\u0627\u0644 \u0627\u0644\u062a\u0646\u0638\u064a\u0645\u064a).',
    dmarcTagDescAspf: '\u0648\u0636\u0639 \u0645\u062d\u0627\u0630\u0627\u0629 \u0645\u0639\u0631\u0641 SPF. s = \u0635\u0627\u0631\u0645 (\u062a\u0637\u0627\u0628\u0642 \u062a\u0627\u0645)\u060c r = \u0645\u0631\u0646 (\u0646\u0641\u0633 \u0627\u0644\u0645\u062c\u0627\u0644 \u0627\u0644\u062a\u0646\u0638\u064a\u0645\u064a).',
    dmarcTagDescRi: '\u0627\u0644\u0641\u0627\u0635\u0644 \u0627\u0644\u0645\u0637\u0644\u0648\u0628 \u0628\u064a\u0646 \u0627\u0644\u062a\u0642\u0627\u0631\u064a\u0631 \u0627\u0644\u0645\u062c\u0645\u0639\u0629 \u0628\u0627\u0644\u062b\u0648\u0627\u0646\u064a. \u0627\u0644\u0627\u0641\u062a\u0631\u0627\u0636\u064a 86400 (\u064a\u0648\u0645 \u0648\u0627\u062d\u062f).',
    dmarcTagDescRf: '\u062a\u0646\u0633\u064a\u0642 \u0627\u0644\u062a\u0642\u0627\u0631\u064a\u0631 \u0627\u0644\u0637\u0628 \u0627\u0644\u0634\u0631\u0639\u064a\u0629. \u0627\u0644\u0627\u0641\u062a\u0631\u0627\u0636\u064a afrf (Authentication Failure Reporting Format).',
    dmarcTagDescUnknown: '\u0648\u0633\u0645 DMARC \u063a\u064a\u0631 \u0645\u0639\u0631\u0648\u0641. \u062a\u062d\u0642\u0642 \u0645\u0646 \u0627\u0644\u0623\u062e\u0637\u0627\u0621 \u0627\u0644\u0645\u0637\u0628\u0639\u064a\u0629 \u0623\u0648 \u0628\u0646\u0627\u0621 \u0627\u0644\u062c\u0645\u0644\u0629 \u063a\u064a\u0631 \u0627\u0644\u0645\u062f\u0639\u0648\u0645.',
    dmarcValueDescPolicyNone: '\u0645\u0631\u0627\u0642\u0628\u0629 \u0641\u0642\u0637. \u0644\u0627 \u064a\u062a\u062e\u0630 \u0627\u0644\u0645\u0633\u062a\u0644\u0645\u0648\u0646 \u0625\u062c\u0631\u0627\u0621\u064b \u0639\u0646\u062f \u0627\u0644\u0641\u0634\u0644\u060c \u0644\u0643\u0646\u0647\u0645 \u064a\u0631\u0633\u0644\u0648\u0646 \u0627\u0644\u062a\u0642\u0627\u0631\u064a\u0631.',
    dmarcValueDescPolicyQuarantine: '\u0639\u0632\u0644 \u0627\u0644\u0631\u0633\u0627\u0626\u0644 \u0627\u0644\u0641\u0627\u0634\u0644\u0629 (\u0639\u0627\u062f\u0629\u064b \u062a\u0633\u0644\u064a\u0645\u0647\u0627 \u0625\u0644\u0649 \u0627\u0644\u0628\u0631\u064a\u062f \u063a\u064a\u0631 \u0627\u0644\u0647\u0627\u0645 / \u0627\u0644\u0628\u0631\u064a\u062f \u0627\u0644\u0639\u0634\u0648\u0627\u0626\u064a).',
    dmarcValueDescPolicyReject: '\u0631\u0641\u0636 \u0627\u0644\u0631\u0633\u0627\u0626\u0644 \u0627\u0644\u0641\u0627\u0634\u0644\u0629 \u0645\u0628\u0627\u0634\u0631\u0629 \u0639\u0644\u0649 \u0637\u0628\u0642\u0629 SMTP.',
