    dmarcValueDescAlignStrict: '\u0635\u0627\u0631\u0645: \u064a\u062c\u0628 \u0623\u0646 \u064a\u062a\u0637\u0627\u0628\u0642 \u0645\u062c\u0627\u0644 From: \u0648\u0627\u0644\u0645\u062c\u0627\u0644 \u0627\u0644\u0645\u0635\u0627\u062f\u0642 \u0639\u0644\u064a\u0647 \u062a\u0645\u0627\u0645\u064b\u0627.',
    dmarcValueDescFoZero: '0: \u0625\u0646\u0634\u0627\u0621 \u062a\u0642\u0631\u064a\u0631 \u0641\u0642\u0637 \u0639\u0646\u062f\u0645\u0627 \u062a\u0641\u0634\u0644 \u062c\u0645\u064a\u0639 \u0627\u0644\u0622\u0644\u064a\u0627\u062a \u0627\u0644\u0623\u0633\u0627\u0633\u064a\u0629 (SPF \u0648DKIM).',
