    smtpResultsCopied: '\u062a\u0645 \u0646\u0633\u062e \u0627\u0644\u062c\u062f\u0648\u0644.', smtpCopyUnavailable: '\u0627\u0644\u062d\u0627\u0641\u0638\u0629 \u063a\u064a\u0631 \u0645\u062a\u0627\u062d\u0629. \u0644\u0627 \u064a\u0632\u0627\u0644 \u0628\u0625\u0645\u0643\u0627\u0646\u0643 \u062a\u062d\u062f\u064a\u062f \u0646\u0635 \u0627\u0644\u062c\u062f\u0648\u0644.',
    smtpStatusMismatch: '\u062a\u0639\u0627\u0631\u0636 \u0641\u0626\u0627\u062a \u0627\u0644\u062d\u0627\u0644\u0629', smtpNotProvided: '\u063a\u064a\u0631 \u0645\u062d\u062f\u062f', smtpGenericDetail: '\u062a\u0641\u0633\u064a\u0631 \u0639\u0627\u0645', smtpProviderSpecific: '\u0627\u0633\u062a\u062e\u062f\u0627\u0645 \u062e\u0627\u0635 \u0628\u0627\u0644\u0645\u0632\u0648\u062f',
    smtpAdviceSuccess: '\u062a\u0635\u0641 \u0627\u0644\u0627\u0633\u062a\u062c\u0627\u0628\u0629 \u0627\u0644\u0625\u064a\u062c\u0627\u0628\u064a\u0629 \u0645\u0631\u062d\u0644\u0629 SMTP \u0627\u0644\u062d\u0627\u0644\u064a\u0629\u060c \u0648\u0644\u0627 \u062a\u0636\u0645\u0646 \u0627\u0644\u062a\u0633\u0644\u064a\u0645 \u0627\u0644\u0646\u0647\u0627\u0626\u064a \u0623\u0648 \u0627\u0644\u0648\u0635\u0648\u0644 \u0625\u0644\u0649 \u0639\u0644\u0628\u0629 \u0627\u0644\u0648\u0627\u0631\u062f.',
    smtpAdviceContinue: '\u0627\u0644\u0645\u062d\u0627\u062f\u062b\u0629 \u063a\u064a\u0631 \u0645\u0643\u062a\u0645\u0644\u0629. \u0627\u0646\u062a\u0638\u0631 \u0627\u0644\u0627\u0633\u062a\u062c\u0627\u0628\u0629 \u0627\u0644\u0646\u0647\u0627\u0626\u064a\u0629 \u0645\u0646 \u0627\u0644\u062e\u0627\u062f\u0645 \u0642\u0628\u0644 \u0627\u0639\u062a\u0628\u0627\u0631 \u0627\u0644\u0631\u0633\u0627\u0644\u0629 \u0645\u0642\u0628\u0648\u0644\u0629.',
    smtpAdviceTemporary: '\u062a\u0633\u0645\u062d \u0627\u0633\u062a\u062c\u0627\u0628\u0629 4xx \u0623\u062b\u0646\u0627\u0621 \u0627\u0644\u0625\u0631\u0633\u0627\u0644 \u0639\u0627\u062f\u0629 \u0628\u0645\u062d\u0627\u0648\u0644\u0627\u062a \u0644\u0627\u062d\u0642\u0629 \u0628\u0641\u0648\u0627\u0635\u0644 \u0645\u062a\u0632\u0627\u064a\u062f\u0629. \u0642\u062f \u064a\u062a\u0637\u0644\u0628 \u062a\u0642\u0631\u064a\u0631 \u0639\u062f\u0645 \u062a\u0633\u0644\u064a\u0645 \u0646\u0647\u0627\u0626\u064a \u0623\u0648 \u0627\u0646\u062a\u0647\u0627\u0621 \u0645\u062f\u0629 \u0627\u0644\u0627\u0646\u062a\u0638\u0627\u0631 \u0625\u0631\u0633\u0627\u0644\u0627 \u062c\u062f\u064a\u062f\u0627 \u0628\u0639\u062f \u0627\u0644\u0625\u0635\u0644\u0627\u062d.',
    smtpAdvicePermanent: '\u0623\u0635\u0644\u062d \u0627\u0644\u0633\u0628\u0628 \u0627\u0644\u0645\u0628\u0644\u063a \u0639\u0646\u0647 \u0642\u0628\u0644 \u0627\u0644\u0625\u0631\u0633\u0627\u0644 \u0645\u062c\u062f\u062f\u0627. \u062a\u0643\u0631\u0627\u0631 \u0627\u0644\u0637\u0644\u0628 \u062f\u0648\u0646 \u062a\u063a\u064a\u064a\u0631 \u0644\u0627 \u064a\u0641\u064a\u062f \u0639\u0627\u062f\u0629.',
    smtpAdviceMismatch: '\u0641\u0626\u062a\u0627 \u0627\u0644\u062d\u0627\u0644\u0629 \u0627\u0644\u0623\u0633\u0627\u0633\u064a\u0629 \u0648\u0627\u0644\u0645\u062d\u0633\u0646\u0629 \u063a\u064a\u0631 \u0645\u062a\u0648\u0627\u0641\u0642\u062a\u064a\u0646. \u062a\u062d\u0642\u0642 \u0645\u0646 \u0627\u0644\u0627\u0633\u062a\u062c\u0627\u0628\u0629 \u0627\u0644\u0623\u0635\u0644\u064a\u0629 \u0645\u0639 \u0645\u0632\u0648\u062f \u0627\u0644\u0627\u0633\u062a\u0642\u0628\u0627\u0644 \u0642\u0628\u0644 \u0627\u062a\u062e\u0627\u0630 \u0642\u0631\u0627\u0631 \u0625\u0639\u0627\u062f\u0629 \u0627\u0644\u0645\u062d\u0627\u0648\u0644\u0629.',
    smtpReferenceNotice: '\u0642\u062f \u062a\u062e\u062a\u0644\u0641 \u0645\u0639\u0627\u0646\u064a \u0627\u0644\u0631\u0645\u0648\u0632 \u062d\u0633\u0628 \u0645\u0632\u0648\u062f \u0627\u0644\u0627\u0633\u062a\u0642\u0628\u0627\u0644. \u0647\u0630\u0647 \u0623\u0633\u0628\u0627\u0628 \u0645\u062d\u062a\u0645\u0644\u0629 \u0648\u0644\u064a\u0633\u062a \u062a\u0634\u062e\u064a\u0635\u0627 \u0645\u0624\u0643\u062f\u0627.',
    smtpIanaReference: '\u0633\u062c\u0644 \u062d\u0627\u0644\u0627\u062a IANA', smtpExchangeReference: '\u0645\u0631\u062c\u0639 \u0639\u062f\u0645 \u0627\u0644\u062a\u0633\u0644\u064a\u0645 \u0641\u064a Exchange Online',
