    smtpUnknownCauses: '\u0647\u0630\u0627 \u0627\u0644\u0631\u0645\u0632 \u063a\u064a\u0631 \u0645\u0648\u062c\u0648\u062f \u0641\u064a \u0627\u0644\u0645\u0631\u062c\u0639 \u0627\u0644\u0645\u062d\u0644\u064a. \u0642\u062f \u064a\u0643\u0648\u0646 \u063a\u064a\u0631 \u0645\u062e\u0635\u0635 \u0623\u0648 \u063a\u064a\u0631 \u0645\u0639\u062a\u0627\u062f \u0644\u0647\u0630\u0647 \u0627\u0644\u0641\u0626\u0629 \u0623\u0648 \u062e\u0627\u0635\u0627 \u0628\u0627\u0644\u0645\u0632\u0648\u062f\u061b \u0644\u0627 \u064a\u0645\u0643\u0646 \u0627\u0633\u062a\u0646\u062a\u0627\u062c \u0633\u0628\u0628 \u062f\u0642\u064a\u0642.',
    smtpUnknownFix: '\u0631\u0627\u062c\u0639 \u0627\u0644\u0627\u0633\u062a\u062c\u0627\u0628\u0629 \u0627\u0644\u0643\u0627\u0645\u0644\u0629 \u0648\u0648\u062b\u0627\u0626\u0642 \u0627\u0644\u0645\u0632\u0648\u062f \u0627\u0644\u0630\u064a \u0631\u0641\u0636 \u0627\u0644\u0631\u0633\u0627\u0644\u0629. \u0641\u0626\u0629 \u0627\u0644\u062d\u0627\u0644\u0629 \u0645\u062c\u0631\u062f \u062f\u0644\u064a\u0644 \u0639\u0627\u0645.',
