    smtpAdvicePermanent: '\u0423\u0441\u0442\u0440\u0430\u043d\u0438\u0442\u0435 \u0443\u043a\u0430\u0437\u0430\u043d\u043d\u0443\u044e \u043f\u0440\u0438\u0447\u0438\u043d\u0443 \u043f\u0435\u0440\u0435\u0434 \u043f\u043e\u0432\u0442\u043e\u0440\u043d\u043e\u0439 \u043e\u0442\u043f\u0440\u0430\u0432\u043a\u043e\u0439. \u041f\u043e\u0432\u0442\u043e\u0440\u0435\u043d\u0438\u0435 \u043d\u0435\u0438\u0437\u043c\u0435\u043d\u0451\u043d\u043d\u043e\u0433\u043e \u0437\u0430\u043f\u0440\u043e\u0441\u0430 \u043e\u0431\u044b\u0447\u043d\u043e \u043d\u0435 \u043f\u043e\u043c\u043e\u0433\u0430\u0435\u0442.',
    smtpAdviceMismatch: '\u041a\u043b\u0430\u0441\u0441\u044b \u043e\u0441\u043d\u043e\u0432\u043d\u043e\u0433\u043e \u0438 \u0440\u0430\u0441\u0448\u0438\u0440\u0435\u043d\u043d\u043e\u0433\u043e \u043a\u043e\u0434\u043e\u0432 \u043d\u0435 \u0441\u043e\u0432\u043f\u0430\u0434\u0430\u044e\u0442. \u041f\u0435\u0440\u0435\u0434 \u043f\u043e\u0432\u0442\u043e\u0440\u043d\u043e\u0439 \u043f\u043e\u043f\u044b\u0442\u043a\u043e\u0439 \u0443\u0442\u043e\u0447\u043d\u0438\u0442\u0435 \u0438\u0441\u0445\u043e\u0434\u043d\u044b\u0439 \u043e\u0442\u0432\u0435\u0442 \u0443 \u043f\u0440\u0438\u043d\u0438\u043c\u0430\u044e\u0449\u0435\u0433\u043e \u043f\u043e\u0441\u0442\u0430\u0432\u0449\u0438\u043a\u0430.',
    smtpReferenceNotice: '\u0417\u043d\u0430\u0447\u0435\u043d\u0438\u0435 \u043a\u043e\u0434\u0430 \u043c\u043e\u0436\u0435\u0442 \u0437\u0430\u0432\u0438\u0441\u0435\u0442\u044c \u043e\u0442 \u043f\u0440\u0438\u043d\u0438\u043c\u0430\u044e\u0449\u0435\u0433\u043e \u043f\u043e\u0441\u0442\u0430\u0432\u0449\u0438\u043a\u0430. \u0417\u0434\u0435\u0441\u044c \u043f\u0440\u0438\u0432\u0435\u0434\u0435\u043d\u044b \u0432\u043e\u0437\u043c\u043e\u0436\u043d\u044b\u0435 \u043f\u0440\u0438\u0447\u0438\u043d\u044b, \u0430 \u043d\u0435 \u043f\u043e\u0434\u0442\u0432\u0435\u0440\u0436\u0434\u0451\u043d\u043d\u044b\u0439 \u0434\u0438\u0430\u0433\u043d\u043e\u0437.',
    smtpIanaReference: '\u0420\u0435\u0435\u0441\u0442\u0440 \u0441\u043e\u0441\u0442\u043e\u044f\u043d\u0438\u0439 IANA', smtpExchangeReference: '\u0421\u043f\u0440\u0430\u0432\u043e\u0447\u043d\u0438\u043a NDR Exchange Online',
    smtpUnknownMeaning: '{subject}: \u043d\u0435\u0438\u0437\u0432\u0435\u0441\u0442\u043d\u044b\u0435 \u043f\u043e\u0434\u0440\u043e\u0431\u043d\u043e\u0441\u0442\u0438',
    smtpUnknownCauses: '\u042d\u0442\u043e\u0433\u043e \u043a\u043e\u0434\u0430 \u043d\u0435\u0442 \u0432 \u043b\u043e\u043a\u0430\u043b\u044c\u043d\u043e\u043c \u0441\u043f\u0440\u0430\u0432\u043e\u0447\u043d\u0438\u043a\u0435. \u041e\u043d \u043c\u043e\u0436\u0435\u0442 \u0431\u044b\u0442\u044c \u043d\u0435 \u043d\u0430\u0437\u043d\u0430\u0447\u0435\u043d, \u043d\u0435\u043e\u0431\u044b\u0447\u0435\u043d \u0434\u043b\u044f \u044d\u0442\u043e\u0433\u043e \u043a\u043b\u0430\u0441\u0441\u0430 \u0438\u043b\u0438 \u043f\u0440\u0438\u043d\u0430\u0434\u043b\u0435\u0436\u0430\u0442\u044c \u043f\u043e\u0441\u0442\u0430\u0432\u0449\u0438\u043a\u0443. \u0422\u043e\u0447\u043d\u0443\u044e \u043f\u0440\u0438\u0447\u0438\u043d\u0443 \u043e\u043f\u0440\u0435\u0434\u0435\u043b\u0438\u0442\u044c \u043d\u0435\u043b\u044c\u0437\u044f.',
    smtpUnknownFix: '\u041f\u0440\u043e\u0432\u0435\u0440\u044c\u0442\u0435 \u043f\u043e\u043b\u043d\u044b\u0439 \u043e\u0442\u0432\u0435\u0442 \u0438 \u0434\u043e\u043a\u0443\u043c\u0435\u043d\u0442\u0430\u0446\u0438\u044e \u043e\u0442\u043a\u0430\u0437\u0430\u0432\u0448\u0435\u0433\u043e \u043f\u043e\u0441\u0442\u0430\u0432\u0449\u0438\u043a\u0430. \u041a\u043b\u0430\u0441\u0441 \u0441\u043e\u0441\u0442\u043e\u044f\u043d\u0438\u044f \u0441\u043b\u0443\u0436\u0438\u0442 \u0442\u043e\u043b\u044c\u043a\u043e \u043e\u0431\u0449\u0438\u043c \u043e\u0440\u0438\u0435\u043d\u0442\u0438\u0440\u043e\u043c.',
    smtpGenericSubject: '\u041e\u0442\u0432\u0435\u0442 SMTP', smtpSubjectStatus: '\u041d\u0435\u0443\u0442\u043e\u0447\u043d\u0451\u043d\u043d\u043e\u0435 \u0441\u043e\u0441\u0442\u043e\u044f\u043d\u0438\u0435', smtpSubjectAddress: '\u0410\u0434\u0440\u0435\u0441\u0430\u0446\u0438\u044f', smtpSubjectMailbox: '\u041f\u043e\u0447\u0442\u043e\u0432\u044b\u0439 \u044f\u0449\u0438\u043a',
    smtpSubjectSystem: '\u041f\u043e\u0447\u0442\u043e\u0432\u0430\u044f \u0441\u0438\u0441\u0442\u0435\u043c\u0430', smtpSubjectNetwork: '\u0421\u0435\u0442\u044c \u0438\u043b\u0438 \u043c\u0430\u0440\u0448\u0440\u0443\u0442\u0438\u0437\u0430\u0446\u0438\u044f', smtpSubjectProtocol: '\u041f\u043e\u0447\u0442\u043e\u0432\u044b\u0439 \u043f\u0440\u043e\u0442\u043e\u043a\u043e\u043b', smtpSubjectContent: '\u0421\u043e\u0434\u0435\u0440\u0436\u0438\u043c\u043e\u0435 \u0441\u043e\u043e\u0431\u0449\u0435\u043d\u0438\u044f', smtpSubjectSecurity: '\u0411\u0435\u0437\u043e\u043f\u0430\u0441\u043d\u043e\u0441\u0442\u044c \u0438\u043b\u0438 \u043f\u043e\u043b\u0438\u0442\u0438\u043a\u0430'
  }
};
// Catalog tuples are meaning, causes, fix. Enhanced keys share text across only
// the classes allowed by the protocol catalog; translations never change verdicts.
const SMTP_RESPONSE_CATALOG_TRANSLATIONS = {
  es: {
    smtpBasic211: ['Estado del sistema', 'El servidor devuelve informaci\u00f3n de estado o ayuda.', 'No indica un error. Contin\u00fae la conversaci\u00f3n SMTP.'],
    smtpBasic214: ['Respuesta de ayuda', 'El servidor muestra la ayuda de un comando.', 'Use la sintaxis de comandos indicada por el servidor.'],
    smtpBasic220: ['Servicio preparado', 'El servicio SMTP est\u00e1 preparado o puede iniciar STARTTLS.', 'Contin\u00fae con EHLO o complete TLS despu\u00e9s de STARTTLS. No es un recibo de entrega.'],
    smtpBasic221: ['Cierre de conexi\u00f3n', 'El servidor cierra la sesi\u00f3n, normalmente despu\u00e9s de QUIT.', 'Un cierre normal no requiere correcci\u00f3n. Consulte la respuesta anterior para conocer el resultado del mensaje.'],
    smtpBasic235: ['Autenticaci\u00f3n correcta', 'El servidor acept\u00f3 la autenticaci\u00f3n SMTP.', 'Contin\u00fae con el env\u00edo. La autenticaci\u00f3n por s\u00ed sola no demuestra la entrega.'],
    smtpBasic250: ['Acci\u00f3n solicitada aceptada', 'El comando termin\u00f3 correctamente. Despu\u00e9s de DATA, el servidor asume la responsabilidad del mensaje.', 'Confirme el resultado mediante el seguimiento del mensaje. La aceptaci\u00f3n no garantiza la llegada a la bandeja de entrada.'],
    smtpBasic251: ['Se reenviar\u00e1 al destinatario', 'El destinatario no es local; el servidor reenviar\u00e1 el mensaje.', 'Confirme la direcci\u00f3n de reenv\u00edo con el destinatario antes de actualizar sus contactos.'],
    smtpBasic252: ['No se puede verificar al destinatario', 'El servidor no verifica la direcci\u00f3n, pero intentar\u00e1 entregar el mensaje.', 'No demuestra que exista el buz\u00f3n. Compruebe el resultado final de la entrega.'],
    smtpBasic334: ['Desaf\u00edo de autenticaci\u00f3n', 'El servidor necesita el siguiente paso del intercambio AUTH.', 'Deje que el cliente complete el m\u00e9todo admitido mediante una conexi\u00f3n segura.'],
    smtpBasic354: ['Preparado para recibir el mensaje', 'El servidor acept\u00f3 DATA y espera el contenido.', 'Env\u00ede el contenido y espere la respuesta final. El mensaje a\u00fan no est\u00e1 aceptado.'],
    smtpBasic421: ['Servicio temporalmente no disponible', 'Mantenimiento, sobrecarga, limitaci\u00f3n de tr\u00e1fico o una directiva provocaron el cierre.', 'Compruebe el servicio y sus l\u00edmites. Permita reintentos con espera progresiva, sin reconexiones continuas.'],
    smtpBasic432: ['Se requiere transici\u00f3n de autenticaci\u00f3n', 'SMTP AUTH requiere migrar la cuenta al mecanismo elegido. Algunos proveedores usan este c\u00f3digo de otra forma.', 'Siga el procedimiento de migraci\u00f3n del proveedor. Consulte el c\u00f3digo mejorado para detectar l\u00edmites de env\u00edo espec\u00edficos.'],
    smtpBasic450: ['Buz\u00f3n temporalmente no disponible', 'El buz\u00f3n puede estar ocupado, deshabilitado temporalmente o restringido por una directiva o lista gris.', 'Permita los reintentos programados. Si persiste, pida al administrador receptor que revise el buz\u00f3n y sus directivas.'],
    smtpBasic451: ['Error temporal de procesamiento', 'Fall\u00f3 el procesamiento local, el directorio, DNS o la evaluaci\u00f3n de directivas.', 'Consulte el c\u00f3digo mejorado y el estado del servicio. El administrador responsable debe resolver los fallos persistentes.'],
    smtpBasic452: ['Recursos insuficientes', 'Falta almacenamiento o se alcanz\u00f3 el l\u00edmite de destinatarios de la transacci\u00f3n.', 'Seg\u00fan la respuesta, libere almacenamiento o divida los destinatarios en lotes m\u00e1s peque\u00f1os.'],
    smtpBasic454: ['Error temporal de autenticaci\u00f3n o TLS', 'El servicio de autenticaci\u00f3n o TLS no est\u00e1 disponible temporalmente.', 'Compruebe el c\u00f3digo mejorado, el servicio y TLS. Mantenga activado el cifrado.'],
    smtpBasic455: ['Par\u00e1metros temporalmente no admitidos', 'El servidor no puede aceptar ahora un par\u00e1metro de MAIL FROM o RCPT TO.', 'Use los par\u00e1metros anunciados en EHLO y la pol\u00edtica de reintentos del servicio de env\u00edo.'],
    smtpBasic500: ['Comando no reconocido', 'El comando no se admite, tiene formato incorrecto o es demasiado largo.', 'Revise la configuraci\u00f3n del cliente, la longitud de las l\u00edneas y las capacidades EHLO.'],
    smtpBasic501: ['Argumentos de comando no v\u00e1lidos', 'Una direcci\u00f3n, par\u00e1metro o argumento tiene sintaxis incorrecta.', 'Corrija las direcciones del sobre y los par\u00e1metros. Use una biblioteca SMTP mantenida.'],
    smtpBasic502: ['Comando no implementado', 'El servidor reconoce el comando, pero no lo implementa.', 'Use comandos admitidos y compruebe que el punto de conexi\u00f3n sea el servicio SMTP correcto.'],
    smtpBasic503: ['Secuencia de comandos incorrecta', 'Falta un comando anterior o ya hay una transacci\u00f3n abierta.', 'Revise la secuencia EHLO, autenticaci\u00f3n, MAIL FROM, RCPT TO y DATA del cliente.'],
    smtpBasic504: ['Par\u00e1metro no admitido', 'El servidor no admite un par\u00e1metro o mecanismo de autenticaci\u00f3n solicitado.', 'Use los mecanismos y extensiones anunciados despu\u00e9s de EHLO y STARTTLS.'],
    smtpBasic521: ['El host no acepta correo', 'El host de destino indica que no ofrece servicio SMTP.', 'Confirme el dominio del destinatario y los registros MX con su administrador.'],
    smtpBasic530: ['Se requiere autenticaci\u00f3n o STARTTLS', 'El servidor exige autenticaci\u00f3n o una conexi\u00f3n segura antes del comando.', 'Consulte la respuesta y configure STARTTLS y el m\u00e9todo admitido. No desactive TLS.'],
    smtpBasic534: ['Autenticaci\u00f3n demasiado d\u00e9bil', 'El m\u00e9todo seleccionado no cumple la directiva del servidor.', 'Use un m\u00e9todo m\u00e1s seguro que est\u00e9 admitido y una conexi\u00f3n cifrada.'],
    smtpBasic535: ['Autenticaci\u00f3n rechazada', 'Se rechazaron las credenciales, la autorizaci\u00f3n o el flujo de autenticaci\u00f3n.', 'Revise la cuenta, los permisos de la aplicaci\u00f3n y el m\u00e9todo admitido. No pegue contrase\u00f1as ni tokens aqu\u00ed.'],
    smtpBasic538: ['La autenticaci\u00f3n requiere cifrado', 'El mecanismo exige una conexi\u00f3n cifrada.', 'Configure STARTTLS o el punto de env\u00edo TLS documentado antes de autenticarse.'],
    smtpBasic550: ['Buz\u00f3n no disponible o acci\u00f3n rechazada', 'La direcci\u00f3n puede no existir, el acceso puede estar denegado o una directiva del destinatario o de retransmisi\u00f3n puede rechazar la solicitud.', 'Use el c\u00f3digo mejorado y la respuesta original para distinguir un problema de direcci\u00f3n de un fallo de directiva o autenticaci\u00f3n.'],
    smtpBasic551: ['El destinatario no es local', 'El servidor rechaz\u00f3 la entrega y puede haber indicado una direcci\u00f3n de reenv\u00edo.', 'Confirme la nueva direcci\u00f3n con el destinatario y corrija los contactos o el enrutamiento.'],
    smtpBasic552: ['L\u00edmite de almacenamiento o tama\u00f1o superado', 'Se super\u00f3 la cuota del buz\u00f3n o el tama\u00f1o del mensaje. Servidores antiguos tambi\u00e9n lo usan para demasiados destinatarios.', 'Libere espacio o reduzca el mensaje. Solo si se indican demasiados destinatarios, divida el lote y reintente esos destinatarios.'],
    smtpBasic553: ['Nombre de buz\u00f3n no permitido', 'Una direcci\u00f3n del sobre es incorrecta o no est\u00e1 permitida.', 'Revise remitente, destinatario, identidades autorizadas y c\u00f3digo mejorado.'],
    smtpBasic554: ['Transacci\u00f3n rechazada', 'Se rechaz\u00f3 el mensaje o la conexi\u00f3n; este c\u00f3digo general no determina la causa.', 'Consulte el c\u00f3digo mejorado y la explicaci\u00f3n sobre contenido, directivas, autenticaci\u00f3n o enrutamiento.'],
    smtpBasic555: ['Par\u00e1metros del sobre no admitidos', 'Un par\u00e1metro de MAIL FROM o RCPT TO no se reconoce o no est\u00e1 implementado.', 'Quite par\u00e1metros no admitidos y use solo extensiones anunciadas en EHLO.'],
    smtpBasic556: ['El dominio destinatario no acepta correo', 'El dominio rechaza expresamente el correo, normalmente mediante un registro MX nulo.', 'Use otra direcci\u00f3n confirmada. No sustituya un MX nulo intencionado sin autorizaci\u00f3n del propietario.'],
    'smtpEnhanced0.0': ['Sin detalles adicionales del estado', 'El servidor solo indic\u00f3 un resultado general.', 'Consulte la respuesta completa y el seguimiento del mensaje.'],
    'smtpEnhanced1.0': ['Error relacionado con direcciones', 'No se pudo utilizar la direcci\u00f3n del remitente o destinatario; faltan detalles.', 'Verifique ambas direcciones del sobre y el directorio receptor.'],
    'smtpEnhanced1.1': ['No se encuentra el buz\u00f3n del destinatario', 'El buz\u00f3n o alias no existe, se elimin\u00f3 o se escribi\u00f3 incorrectamente.', 'Confirme la direcci\u00f3n con el destinatario, corrija la escritura y elimine entradas antiguas de autocompletado. Pida al administrador del destinatario que compruebe los alias.'],
    'smtpEnhanced1.2': ['Dominio destinatario no v\u00e1lido para correo', 'El dominio de destino no existe o no puede aceptar correo.', 'Corrija el nombre y pida al propietario que revise el registro del dominio, MX y servicio de correo.'],
    'smtpEnhanced1.3': ['Sintaxis del destinatario incorrecta', 'La direcci\u00f3n del destinatario tiene un formato incorrecto.', 'Corrija la parte local, el separador @ y el dominio de la direcci\u00f3n del sobre.'],
    'smtpEnhanced1.4': ['Direcci\u00f3n del destinatario ambigua', 'El directorio asocia la direcci\u00f3n con varios destinatarios.', 'Pida al administrador receptor que corrija los alias o entradas duplicados.'],
    'smtpEnhanced1.5': ['Direcci\u00f3n del destinatario aceptada', 'El sistema receptor acept\u00f3 la direcci\u00f3n indicada.', 'No se indica un error de direcci\u00f3n. Esta aceptaci\u00f3n no demuestra la entrega final en la bandeja de entrada.'],
    'smtpEnhanced1.6': ['Destinatario trasladado sin reenv\u00edo', 'El buz\u00f3n anterior no acepta correo y no tiene destino de reenv\u00edo.', 'Obtenga la direcci\u00f3n actual del destinatario y actualice los contactos.'],
    'smtpEnhanced1.7': ['Sintaxis del remitente incorrecta', 'La direcci\u00f3n del remitente del sobre est\u00e1 mal formada.', 'Corrija MAIL FROM y la configuraci\u00f3n del remitente en la aplicaci\u00f3n.'],
    'smtpEnhanced1.8': ['El dominio remitente no recibe devoluciones', 'El dominio no es v\u00e1lido para devolver correo. Exchange Online tambi\u00e9n usa 5.1.8 para un remitente de salida bloqueado.', 'Revise el dominio del sobre y DNS. Si Exchange bloque\u00f3 al remitente, investigue la seguridad de la cuenta y recup\u00e9rela mediante el proceso de entidades restringidas.'],
    'smtpEnhanced1.10': ['El dominio destinatario publica MX nulo', 'El est\u00e1ndar indica que el dominio no acepta correo. Exchange Online tambi\u00e9n usa 5.1.10 para un destinatario ausente de su directorio.', 'Compruebe el proveedor y la respuesta completa. Para MX nulo use otro destinatario; en Exchange revise el buz\u00f3n y sus alias.'],
    'smtpEnhanced2.0': ['Error relacionado con el buz\u00f3n', 'Una condici\u00f3n del buz\u00f3n impidi\u00f3 la entrega sin m\u00e1s detalle.', 'Pida al administrador que revise el estado, la cuota y las restricciones de entrega.'],
    'smtpEnhanced2.1': ['Buz\u00f3n deshabilitado', 'El buz\u00f3n existe, pero no acepta mensajes.', 'Revise el estado de la cuenta, la licencia y la disponibilidad del buz\u00f3n con su administrador.'],
    'smtpEnhanced2.2': ['Buz\u00f3n lleno o cuota superada', 'El buz\u00f3n alcanz\u00f3 su cuota. En Exchange Online, la respuesta puede indicar en cambio una cuota de env\u00edo del remitente.', 'Si el buz\u00f3n est\u00e1 lleno, libere espacio o ajuste la cuota. Para cuota de env\u00edo, reduzca el tr\u00e1fico y revise l\u00edmites y seguridad de la cuenta.'],
    'smtpEnhanced2.3': ['Tama\u00f1o m\u00e1ximo del buz\u00f3n superado', 'El mensaje supera el l\u00edmite de tama\u00f1o por buz\u00f3n.', 'Reduzca mensaje y adjuntos, incluyendo la sobrecarga MIME, o use un enlace de archivos autorizado.'],
    'smtpEnhanced2.4': ['Error al expandir la lista de correo', 'No se pudo convertir el grupo o lista en destinatarios.', 'Pida al propietario que revise miembros, directorio y servicio de grupos.'],
    'smtpEnhanced3.0': ['Error del sistema de correo', 'El destino notific\u00f3 un problema general del sistema.', 'Pida al administrador receptor que revise el servicio, las colas y los diagn\u00f3sticos.'],
    'smtpEnhanced3.1': ['Almacenamiento del sistema agotado', 'Se agot\u00f3 el almacenamiento compartido del servidor, no solo la cuota de un buz\u00f3n.', 'El administrador receptor debe recuperar capacidad. Permita reintentos con espera progresiva.'],
    'smtpEnhanced3.2': ['El sistema no acepta mensajes', 'El sistema est\u00e1 en mantenimiento, apag\u00e1ndose, sobrecargado o rechazando correo.', 'Revise el servicio y los l\u00edmites de conexi\u00f3n. Una respuesta permanente exige corregir la causa antes de reenviar.'],
    'smtpEnhanced3.3': ['Funci\u00f3n de correo requerida no disponible', 'El destino o una puerta de enlace no admite una funci\u00f3n solicitada.', 'Use funciones admitidas o solicite corregir la configuraci\u00f3n de la puerta de enlace.'],
    'smtpEnhanced3.4': ['Tama\u00f1o m\u00e1ximo del servidor superado', 'El mensaje supera el tama\u00f1o permitido por el servidor receptor.', 'Reduzca el tama\u00f1o codificado o use un enlace autorizado. Revise los l\u00edmites de toda la ruta.'],
    'smtpEnhanced3.5': ['Sistema de correo mal configurado', 'Un sistema receptor o intermedio tiene una configuraci\u00f3n incorrecta.', 'Pida revisar dominios aceptados, conectores, enrutamiento y configuraci\u00f3n del servicio.'],
    'smtpEnhanced4.0': ['Error de red o enrutamiento', 'Se notific\u00f3 un problema de conexi\u00f3n o ruta sin detalles.', 'Compruebe MX, direcciones de destino, conectividad y rutas de correo.'],
    'smtpEnhanced4.1': ['El host de destino no responde', 'El destino puede estar desconectado, sobrecargado o bloqueado por un firewall.', 'Revise el servicio SMTP receptor, destinos MX y reglas de firewall con su administrador.'],
    'smtpEnhanced4.2': ['Conexi\u00f3n interrumpida durante la entrega', 'La conexi\u00f3n se estableci\u00f3, pero termin\u00f3 o caduc\u00f3 antes de completar la transacci\u00f3n.', 'Compruebe estabilidad de red, tiempos de espera SMTP, fallos TLS y estado del receptor.'],
    'smtpEnhanced4.3': ['Directorio o DNS no disponible', 'Fall\u00f3 una consulta de directorio o DNS necesaria para la ruta.', 'Compruebe DNS autoritativo, resolutores, DNSSEC y disponibilidad del directorio.'],
    'smtpEnhanced4.4': ['No hay una ruta de correo v\u00e1lida', 'No se pudo determinar el siguiente servidor o la ruta configurada no es v\u00e1lida.', 'Revise MX, A/AAAA, dominios aceptados y rutas de conectores o hosts inteligentes.'],
    'smtpEnhanced4.5': ['Sistema de correo congestionado', 'Las colas o la capacidad de entrega est\u00e1n sobrecargadas.', 'Reduzca concurrencia y frecuencia de env\u00edo y permita que se vac\u00eden las colas.'],
    'smtpEnhanced4.6': ['Bucle de enrutamiento de correo', 'Reglas de reenv\u00edo o conectores repiten la ruta por los mismos sistemas.', 'Trace los saltos y elimine el reenv\u00edo circular o la ruta de conector incorrecta.'],
    'smtpEnhanced4.7': ['Tiempo de entrega agotado', 'El mensaje sigui\u00f3 sin entregarse hasta que caduc\u00f3 su permanencia en cola.', 'Revise los errores anteriores y corrija la causa. Un mensaje caducado ya no se reintenta autom\u00e1ticamente y puede requerir un nuevo env\u00edo.'],
    'smtpEnhanced5.0': ['Error de protocolo de correo', 'El intercambio SMTP fall\u00f3 sin un detalle m\u00e1s espec\u00edfico.', 'Revise la secuencia SMTP del cliente y la explicaci\u00f3n del receptor.'],
    'smtpEnhanced5.1': ['Comando no v\u00e1lido o fuera de secuencia', 'Un comando no se admite o se envi\u00f3 en un estado SMTP incorrecto.', 'Compruebe la secuencia y las capacidades anunciadas por el servidor.'],
    'smtpEnhanced5.2': ['Error de sintaxis SMTP', 'El receptor no pudo interpretar un comando.', 'Corrija el formato y actualice la biblioteca del cliente SMTP.'],
    'smtpEnhanced5.3': ['Demasiados destinatarios', 'La transacci\u00f3n supera el l\u00edmite de destinatarios del receptor.', 'Divida la lista seg\u00fan los l\u00edmites publicados. No reenv\u00ede a destinatarios ya aceptados.'],
    'smtpEnhanced5.4': ['Argumentos SMTP no v\u00e1lidos', 'Un comando reconocido contiene argumentos incorrectos o no admitidos.', 'Corrija las direcciones del sobre y use solo extensiones negociadas.'],
    'smtpEnhanced5.5': ['Versiones de protocolo incompatibles', 'Los sistemas no coinciden en las funciones de protocolo requeridas.', 'Actualice el cliente o la puerta de enlace y compruebe la compatibilidad.'],
    'smtpEnhanced6.0': ['Problema de contenido o codificaci\u00f3n', 'El mensaje no puede procesarse por la representaci\u00f3n del contenido.', 'Valide encabezados MIME, codificaciones y adjuntos seg\u00fan el diagn\u00f3stico original.'],
    'smtpEnhanced6.1': ['Tipo de contenido no admitido', 'El receptor no admite un tipo de contenido o codificaci\u00f3n.', 'Use tipos MIME y codificaciones admitidos o un enlace de archivos autorizado.'],
    'smtpEnhanced6.2': ['Conversi\u00f3n requerida prohibida', 'La entrega requiere una conversi\u00f3n que la directiva no permite.', 'Env\u00ede un formato admitido o pida al administrador que revise la directiva aplicable.'],
    'smtpEnhanced6.3': ['Conversi\u00f3n requerida no disponible', 'Una puerta de enlace no puede convertir el mensaje para el siguiente salto.', 'Genere MIME compatible y revise las capacidades de codificaci\u00f3n de la puerta de enlace.'],
    'smtpEnhanced6.5': ['Conversi\u00f3n del mensaje fallida', 'No se pudo completar una conversi\u00f3n de contenido necesaria.', 'Revise la codificaci\u00f3n y los errores de la puerta de enlace que convierte el mensaje.'],
    'smtpEnhanced6.7': ['Direcci\u00f3n internacionalizada no admitida', 'La ruta no permite direcciones del sobre con caracteres no ASCII.', 'Use una ruta SMTPUTF8 o un alias ASCII real proporcionado por el destinatario. No elimine caracteres de la direcci\u00f3n.'],
    'smtpEnhanced6.8': ['Respuesta UTF-8 no disponible para el cliente', 'El servidor necesita una respuesta UTF-8 que el cliente no negoci\u00f3.', 'Use un cliente SMTPUTF8 y una ruta compatible.'],
    'smtpEnhanced6.9': ['El mensaje UTF-8 no llega a todos los destinatarios', 'Alg\u00fan destinatario no tiene una ruta compatible con SMTPUTF8.', 'Verifique SMTPUTF8 en toda la ruta y use alias compatibles confirmados cuando existan.'],
    'smtpEnhanced7.0': ['Error de seguridad o directiva no especificado', 'Una restricci\u00f3n, autenticaci\u00f3n o filtro impidi\u00f3 la acci\u00f3n.', 'Lea la respuesta completa y pida revisar las decisiones de autenticaci\u00f3n y directivas.'],
    'smtpEnhanced7.1': ['Entrega restringida por directiva', 'Puede deberse a retransmisi\u00f3n denegada, restricciones, filtros o falta de autenticaci\u00f3n. Una respuesta temporal tambi\u00e9n puede indicar lista gris.', 'Revise el punto SMTP, autenticaci\u00f3n, permisos y reputaci\u00f3n. Consulte la directiva concreta; no desactive las protecciones de forma general.'],
    'smtpEnhanced7.2': ['Env\u00edo a la lista no permitido', 'El remitente no est\u00e1 autorizado para enviar a la lista.', 'Solicite aprobaci\u00f3n al propietario o use una direcci\u00f3n autorizada.'],
    'smtpEnhanced7.3': ['Conversi\u00f3n de mensaje seguro no disponible', 'La puerta de enlace no puede realizar una conversi\u00f3n segura requerida.', 'Use un formato seguro compatible con ambos sistemas y consulte al administrador.'],
    'smtpEnhanced7.4': ['Funci\u00f3n de seguridad no admitida', 'El receptor no admite una funci\u00f3n de seguridad solicitada.', 'Use un m\u00e9todo admitido sin debilitar la seguridad del transporte.'],
    'smtpEnhanced7.5': ['Validaci\u00f3n criptogr\u00e1fica fallida', 'Falta una clave o certificado, o no es v\u00e1lido. Algunos proveedores lo usan para validar certificados TLS o MTA-STS.', 'Revise validez, nombres de host, cadena de confianza y directiva de seguridad del mensaje o transporte.'],
    'smtpEnhanced7.6': ['Algoritmo criptogr\u00e1fico no admitido', 'Remitente y receptor no comparten un algoritmo requerido.', 'Actualice los sistemas y seleccione un algoritmo seguro compatible con ambos.'],
    'smtpEnhanced7.7': ['Comprobaci\u00f3n de integridad fallida', 'El contenido cambi\u00f3 o fall\u00f3 una comprobaci\u00f3n criptogr\u00e1fica.', 'Identifique modificaciones en puertas de enlace o reenv\u00edos y revise la firma.'],
    'smtpEnhanced7.8': ['Credenciales de autenticaci\u00f3n rechazadas', 'AUTH utiliz\u00f3 credenciales incorrectas o insuficientes.', 'Revise cuenta, OAuth o m\u00e9todo admitido, permisos de aplicaci\u00f3n y configuraci\u00f3n del servicio.'],
    'smtpEnhanced7.9': ['M\u00e9todo de autenticaci\u00f3n demasiado d\u00e9bil', 'El mecanismo elegido no cumple la directiva del receptor.', 'Use un m\u00e9todo m\u00e1s seguro anunciado por el servidor y mantenga TLS.'],
    'smtpEnhanced7.10': ['Se necesita una conexi\u00f3n cifrada', 'El mecanismo de autenticaci\u00f3n exige una capa de privacidad m\u00e1s fuerte.', 'Establezca TLS antes de autenticar o use un mecanismo m\u00e1s seguro admitido.'],
    'smtpEnhanced7.11': ['La autenticaci\u00f3n exige cifrado', 'El m\u00e9todo elegido no funciona mediante una conexi\u00f3n sin cifrar.', 'Configure STARTTLS o el punto TLS documentado antes de autenticar.'],
    'smtpEnhanced7.12': ['Se requiere transici\u00f3n de autenticaci\u00f3n', 'La cuenta necesita una transici\u00f3n antes de usar el mecanismo seleccionado.', 'Siga el procedimiento de transici\u00f3n documentado del proveedor mediante una conexi\u00f3n segura.'],
    'smtpEnhanced7.13': ['Cuenta deshabilitada o destinatario restringido', 'El est\u00e1ndar indica una cuenta deshabilitada. Exchange Online tambi\u00e9n lo usa para carpetas p\u00fablicas limitadas a remitentes internos autenticados.', 'Revise proveedor y respuesta completa. Consulte la restricci\u00f3n con el administrador de la cuenta o propietario de la carpeta.'],
    'smtpEnhanced7.20': ['Ninguna firma DKIM v\u00e1lida', 'El receptor no puede validar ninguna firma DKIM del mensaje.', 'Active DKIM en el servicio emisor real, publique los selectores correctos y compruebe modificaciones posteriores a la firma.'],
    'smtpEnhanced7.21': ['Ninguna firma DKIM aceptable', 'Una firma DKIM es v\u00e1lida, pero no cumple la directiva receptora.', 'Revise dominio firmante, algoritmo, longitud de clave y requisitos del receptor.'],
    'smtpEnhanced7.22': ['El dominio DKIM no coincide con el autor', 'La firma v\u00e1lida no coincide con el dominio From seg\u00fan lo requerido.', 'Configure una firma de dominio alineada con la direcci\u00f3n From visible.'],
    'smtpEnhanced7.23': ['Validaci\u00f3n SPF fallida', 'La IP emisora real no est\u00e1 autorizada por el SPF del dominio del sobre.', 'Verifique MAIL FROM y el servicio emisor. Publique un \u00fanico SPF v\u00e1lido que lo autorice, sin superar el l\u00edmite de consultas DNS.'],
    'smtpEnhanced7.24': ['Error de evaluaci\u00f3n SPF', 'Fallos DNS, varios registros SPF, t\u00e9rminos incorrectos o demasiadas consultas impiden evaluar SPF.', 'Corrija DNS o SPF; revise include y redirect, mantenga un solo registro y como m\u00e1ximo diez t\u00e9rminos que consultan DNS.'],
    'smtpEnhanced7.25': ['Validaci\u00f3n DNS inversa fallida', 'La IP emisora carece de PTR aceptable o de DNS directo coincidente.', 'Pida al propietario de la IP que configure PTR y A/AAAA coincidentes seg\u00fan los requisitos del proveedor.'],
    'smtpEnhanced7.26': ['Comprobaciones de autenticaci\u00f3n fallidas', 'Fallaron varias comprobaciones. Puede relacionarse con SPF, DKIM o DMARC; el c\u00f3digo solo no indica cu\u00e1l fall\u00f3.', 'Revise Authentication-Results y la respuesta receptora. Corrija SPF y DKIM y compruebe la alineaci\u00f3n con From para DMARC.'],
    'smtpEnhanced7.27': ['El dominio remitente publica MX nulo', 'El dominio remitente no acepta devoluciones y el receptor rechaza ese remitente.', 'Use un dominio de remitente del sobre verificado que pueda recibir las devoluciones necesarias.'],
    'smtpEnhanced7.28': ['Sospecha de env\u00edo masivo abusivo', 'El receptor considera el tr\u00e1fico parte de una inundaci\u00f3n de mensajes.', 'Detenga env\u00edos no previstos, investigue la seguridad, reduzca el volumen y siga el proceso de recuperaci\u00f3n del receptor.'],
    'smtpEnhanced7.29': ['Validaci\u00f3n ARC fallida', 'No se pudo validar la cadena de recepci\u00f3n autenticada del mensaje.', 'Revise firmas ARC, orden de sellado y modificaciones en puertas de enlace de reenv\u00edo.'],
    'smtpEnhanced7.30': ['TLS requerido no disponible', 'El mensaje exige REQUIRETLS y el siguiente salto no lo admite.', 'Use una ruta con REQUIRETLS en todos los saltos y pida resolver la incompatibilidad.'],
    'smtpProvider4.4.316': ['Conexi\u00f3n remota rechazada', 'Exchange Online no pudo conectar con el SMTP de destino.', 'Pida revisar el servicio de escucha, firewall, destinos MX y disponibilidad.'],
    'smtpProvider4.4.317': ['Certificado TLS remoto no confiable', 'Exchange Online no pudo validar la cadena del certificado de destino.', 'Pida al receptor instalar un certificado v\u00e1lido con la cadena de confianza completa en SMTP.'],
    'smtpProvider5.2.121': ['L\u00edmite por remitente para este destinatario', 'Exchange Online limit\u00f3 los mensajes de un remitente a un destinatario concreto.', 'Reduzca los mensajes a ese destinatario y espere a recuperar capacidad antes de un nuevo env\u00edo.'],
    'smtpProvider5.2.122': ['Frecuencia de recepci\u00f3n superada', 'El destinatario de Exchange Online super\u00f3 su frecuencia total de recepci\u00f3n.', 'Coordine con su administrador y reduzca el tr\u00e1fico autom\u00e1tico antes de reenviar.'],
    'smtpProvider5.4.1': ['Acceso de destinatario o retransmisi\u00f3n denegado', 'Exchange Online puede no reconocer al destinatario o no aceptar correo para el dominio.', 'Revise buz\u00f3n, alias, sincronizaci\u00f3n del directorio, dominios aceptados y rutas MX o de conectores.'],
    'smtpProvider5.4.14': ['Bucle de correo detectado', 'Exchange Online detect\u00f3 reenv\u00edo circular o rutas circulares de conectores.', 'Trace los saltos y corrija conectores, dominios aceptados o reenv\u00edos que causan el bucle.'],
    'smtpProvider5.6.11': ['Finales de l\u00ednea no v\u00e1lidos', 'El mensaje contiene saltos LF sin el CRLF requerido.', 'Actualice la aplicaci\u00f3n o biblioteca SMTP para generar finales de l\u00ednea correctos.'],
    'smtpProvider5.7.12': ['El destinatario exige un remitente interno', 'El destinatario de Exchange Online rechaza remitentes externos o no autenticados.', 'Pida al administrador revisar las restricciones y autorizar al remitente previsto cuando corresponda.'],
    'smtpProvider5.7.57': ['Cliente no autenticado para enviar', 'Una aplicaci\u00f3n o dispositivo no se autentic\u00f3 como requiere Exchange Online.', 'Revise punto de env\u00edo, STARTTLS, autenticaci\u00f3n y directivas SMTP AUTH de cuenta e inquilino. No habilite retransmisi\u00f3n an\u00f3nima.'],
    'smtpProvider5.7.64': ['El conector no pudo identificar al inquilino', 'La IP o el certificado local ya no coincide con el conector entrante de Exchange Online.', 'Revise IP autorizadas, identidad del certificado TLS y dominios aceptados del conector.'],
    'smtpProvider5.7.124': ['Remitente no permitido para el grupo', 'El remitente no figura en la lista autorizada del grupo de distribuci\u00f3n.', 'Solicite al propietario que revise y autorice al remitente previsto.'],
    'smtpProvider5.7.133': ['El grupo rechaza remitentes externos', 'El grupo acepta \u00fanicamente remitentes internos autenticados.', 'Pida al propietario que revise la restricci\u00f3n de remitentes externos.'],
    'smtpProvider5.7.134': ['El buz\u00f3n rechaza remitentes externos', 'El buz\u00f3n est\u00e1 limitado a remitentes internos autenticados.', 'Pida al administrador receptor que revise las restricciones de entrega.'],
    'smtpProvider5.7.509': ['Se aplic\u00f3 la directiva de rechazo DMARC', 'El dominio From visible fall\u00f3 DMARC y publica una directiva de rechazo.', 'Corrija SPF o DKIM alineados del emisor real. Investigue reenv\u00edos; no elimine DMARC como soluci\u00f3n general.'],
    'smtpProvider5.7.520': ['Reenv\u00edo externo autom\u00e1tico bloqueado', 'Una directiva de salida de Exchange Online no permite el reenv\u00edo externo autom\u00e1tico.', 'Revise la regla y la seguridad. Use un destino aprobado o una excepci\u00f3n limitada solo cuando est\u00e9 justificada.'],
    'smtpProvider5.7.705': ['Inquilino emisor restringido', 'Microsoft detect\u00f3 tr\u00e1fico de salida sospechoso y restringi\u00f3 al inquilino.', 'Detenga el abuso, investigue cuentas comprometidas o retransmisores abiertos, proteja las cuentas y contacte con soporte.'],
    'smtpProvider5.7.708': ['Tr\u00e1fico de la IP emisora rechazado', 'Microsoft restringi\u00f3 al inquilino o su tr\u00e1fico de salida por actividad sospechosa.', 'Investigue y corrija env\u00edos no deseados y siga el proceso de soporte de Microsoft.'],
    'smtpProvider5.7.750': ['Env\u00edo desde dominios no registrados bloqueado', 'Exchange Online detect\u00f3 uso sospechoso de dominios no provisionados en el inquilino.', 'Agregue y verifique los dominios leg\u00edtimos e investigue los env\u00edos no autorizados.']
  },
  fr: {
    smtpBasic211: ['\u00c9tat du syst\u00e8me', "Le serveur fournit des informations de statut ou d'aide.", "Aucune erreur \u00e0 corriger. Poursuivez la conversation SMTP."],
    smtpBasic214: ["R\u00e9ponse d'aide", "Le serveur fournit l'aide d'une commande.", 'Utilisez la syntaxe annonc\u00e9e par le serveur.'],
    smtpBasic220: ['Service pr\u00eat', 'Le service SMTP est pr\u00eat, ou STARTTLS peut commencer.', "Continuez avec EHLO ou terminez TLS apr\u00e8s STARTTLS. Ce n'est pas un accus\u00e9 de r\u00e9ception du message."],
    smtpBasic221: ['Fermeture de connexion', 'Le serveur ferme la session, g\u00e9n\u00e9ralement apr\u00e8s QUIT.', 'Une fermeture normale ne n\u00e9cessite rien. Consultez la r\u00e9ponse pr\u00e9c\u00e9dente pour le r\u00e9sultat du message.'],
    smtpBasic235: ['Authentification r\u00e9ussie', "Le serveur a accept\u00e9 l'authentification SMTP.", "Poursuivez l'envoi. L'authentification seule ne prouve pas la remise."],
    smtpBasic250: ['Action demand\u00e9e accept\u00e9e', 'La commande est termin\u00e9e. Apr\u00e8s DATA, le serveur prend le message en charge.', "V\u00e9rifiez le r\u00e9sultat par le suivi des messages. L'acceptation ne garantit pas le placement en bo\u00eete de r\u00e9ception."],
    smtpBasic251: ['Destinataire transf\u00e9r\u00e9', "Le destinataire n'est pas local ; le serveur transf\u00e9rera le message.", "Confirmez l'adresse de transfert avant de modifier vos contacts."],
    smtpBasic252: ['Destinataire non v\u00e9rifiable', "Le serveur ne v\u00e9rifie pas l'adresse, mais tentera la remise.", "Cela ne prouve pas que la bo\u00eete existe. V\u00e9rifiez le r\u00e9sultat final."],
    smtpBasic334: ["D\u00e9fi d'authentification", "Le serveur attend la suite de l'\u00e9change AUTH.", "Laissez le client terminer la m\u00e9thode prise en charge sur une connexion s\u00e9curis\u00e9e."],
    smtpBasic354: ['Pr\u00eat \u00e0 recevoir le contenu', 'Le serveur a accept\u00e9 DATA et attend le message.', "Envoyez le contenu et attendez la r\u00e9ponse finale. Le message n'est pas encore accept\u00e9."],
    smtpBasic421: ['Service temporairement indisponible', 'Maintenance, surcharge, limitation ou strat\u00e9gie de connexion ont ferm\u00e9 la session.', "V\u00e9rifiez le service et les limites. Laissez les tentatives s'espacer ; \u00e9vitez les reconnexions en boucle."],
    smtpBasic432: ["Transition d'authentification requise", "SMTP AUTH exige une transition du compte. Certains fournisseurs emploient ce code autrement.", "Suivez la migration du fournisseur. Le code am\u00e9lior\u00e9 peut pr\u00e9ciser une limitation d'envoi propre au fournisseur."],
    smtpBasic450: ['Bo\u00eete temporairement indisponible', 'La bo\u00eete peut \u00eatre occup\u00e9e, temporairement d\u00e9sactiv\u00e9e, en liste grise ou restreinte.', 'Laissez les tentatives programm\u00e9es se poursuivre. Si le probl\u00e8me persiste, faites v\u00e9rifier bo\u00eete et strat\u00e9gies.'],
    smtpBasic451: ['Erreur temporaire de traitement', "Un traitement local, l'annuaire, DNS ou une \u00e9valuation de strat\u00e9gie a \u00e9chou\u00e9.", 'Consultez le code am\u00e9lior\u00e9 et la sant\u00e9 du service. Faites corriger les erreurs persistantes.'],
    smtpBasic452: ['Ressources insuffisantes', 'Le stockage manque ou la limite de destinataires par transaction est atteinte.', 'Selon la r\u00e9ponse, lib\u00e9rez du stockage ou r\u00e9duisez les lots de destinataires.'],
    smtpBasic454: ["Erreur temporaire d'authentification ou TLS", "Le service d'authentification ou TLS est temporairement indisponible.", 'V\u00e9rifiez le code am\u00e9lior\u00e9, le service et TLS. Conservez le chiffrement.'],
    smtpBasic455: ['Param\u00e8tres temporairement non accept\u00e9s', 'Un param\u00e8tre MAIL FROM ou RCPT TO ne peut pas \u00eatre accept\u00e9 actuellement.', "Utilisez les param\u00e8tres EHLO et la strat\u00e9gie de nouvelle tentative du service d'envoi."],
    smtpBasic500: ['Commande non reconnue', 'La commande est non prise en charge, mal form\u00e9e ou trop longue.', 'V\u00e9rifiez le client, la longueur des lignes et les capacit\u00e9s EHLO.'],
    smtpBasic501: ['Arguments de commande incorrects', "Un argument, une adresse ou un param\u00e8tre a une syntaxe incorrecte.", "Corrigez les adresses d'enveloppe et les param\u00e8tres. Utilisez une biblioth\u00e8que SMTP maintenue."],
    smtpBasic502: ['Commande non impl\u00e9ment\u00e9e', 'Le serveur reconna\u00eet la commande sans la prendre en charge.', 'Utilisez les commandes disponibles et v\u00e9rifiez le point de terminaison SMTP.'],
    smtpBasic503: ['Commandes dans le mauvais ordre', 'Une commande pr\u00e9alable manque ou une transaction est d\u00e9j\u00e0 ouverte.', 'V\u00e9rifiez EHLO, authentification, MAIL FROM, RCPT TO et DATA dans le client.'],
    smtpBasic504: ['Param\u00e8tre non pris en charge', "Le serveur ne prend pas en charge un param\u00e8tre ou un m\u00e9canisme d'authentification.", 'Utilisez les m\u00e9canismes et extensions annonc\u00e9s apr\u00e8s EHLO et STARTTLS.'],
    smtpBasic521: ["Cet h\u00f4te n'accepte pas le courrier", "L'h\u00f4te indique explicitement ne pas fournir de service SMTP.", 'V\u00e9rifiez le domaine destinataire et les enregistrements MX avec son administrateur.'],
    smtpBasic530: ['Authentification ou STARTTLS requis', 'Le serveur exige une authentification ou une connexion s\u00e9curis\u00e9e avant la commande.', 'Consultez la r\u00e9ponse ; configurez STARTTLS et une m\u00e9thode admise. Ne d\u00e9sactivez pas TLS.'],
    smtpBasic534: ['Authentification trop faible', 'La m\u00e9thode ne satisfait pas la strat\u00e9gie du serveur.', 'Utilisez une m\u00e9thode plus forte prise en charge et une connexion s\u00e9curis\u00e9e.'],
    smtpBasic535: ['Authentification refus\u00e9e', "Les identifiants, autorisations ou le flux d'authentification ont \u00e9t\u00e9 refus\u00e9s.", "V\u00e9rifiez compte, droits de l'application et m\u00e9thode admise. Ne collez jamais de mot de passe ni de jeton ici."],
    smtpBasic538: ["Chiffrement requis pour l'authentification", 'Le m\u00e9canisme n\u00e9cessite une connexion chiffr\u00e9e.', "Configurez STARTTLS ou le point TLS document\u00e9 avant l'authentification."],
    smtpBasic550: ['Bo\u00eete indisponible ou action refus\u00e9e', "L'adresse peut ne pas exister, ou une restriction de destinataire, de relais ou d'acc\u00e8s s'applique.", "Utilisez le code am\u00e9lior\u00e9 et la r\u00e9ponse originale pour distinguer adresse, strat\u00e9gie et authentification."],
    smtpBasic551: ["Le destinataire n'est pas local", 'Le serveur refuse la remise et peut proposer une adresse de transfert.', 'Confirmez cette adresse avec le destinataire et corrigez contacts ou routage.'],
    smtpBasic552: ['Limite de stockage ou de taille d\u00e9pass\u00e9e', 'Quota ou taille d\u00e9pass\u00e9s. Les anciens serveurs utilisent aussi ce code pour trop de destinataires.', 'Lib\u00e9rez la bo\u00eete ou r\u00e9duisez le message. Si la r\u00e9ponse vise le nombre de destinataires, divisez le lot et reprenez ceux concern\u00e9s.'],
    smtpBasic553: ['Nom de bo\u00eete non autoris\u00e9', "Une adresse d'enveloppe est mal form\u00e9e ou interdite.", 'V\u00e9rifiez exp\u00e9diteur, destinataire, identit\u00e9s autoris\u00e9es et code am\u00e9lior\u00e9.'],
    smtpBasic554: ['Transaction refus\u00e9e', 'Le message ou la connexion est rejet\u00e9 ; ce code seul ne pr\u00e9cise pas la cause.', 'Consultez le code am\u00e9lior\u00e9 pour les probl\u00e8mes de contenu, strat\u00e9gie, authentification ou routage.'],
    smtpBasic555: ["Param\u00e8tres d'enveloppe non pris en charge", "Un param\u00e8tre MAIL FROM ou RCPT TO n'est pas reconnu ou impl\u00e9ment\u00e9.", 'Retirez les param\u00e8tres non admis et utilisez uniquement les extensions EHLO annonc\u00e9es.'],
    smtpBasic556: ["Le domaine destinataire n'accepte pas de courrier", 'Le domaine refuse explicitement les messages, souvent avec un MX nul.', "Utilisez une autre adresse confirm\u00e9e. Ne remplacez pas un MX nul intentionnel sans l'accord du propri\u00e9taire."],
    'smtpEnhanced0.0': ['Aucun d\u00e9tail de statut suppl\u00e9mentaire', 'Le serveur ne fournit que le r\u00e9sultat g\u00e9n\u00e9ral.', 'Consultez la r\u00e9ponse compl\u00e8te et le suivi du message.'],
    'smtpEnhanced1.0': ["Erreur li\u00e9e \u00e0 l'adresse", "Une adresse d'exp\u00e9diteur ou de destinataire est inutilisable, sans autre d\u00e9tail.", "V\u00e9rifiez les deux adresses d'enveloppe et l'annuaire destinataire."],
    'smtpEnhanced1.1': ['Bo\u00eete du destinataire introuvable', "La bo\u00eete ou l'alias n'existe pas, a \u00e9t\u00e9 supprim\u00e9 ou est mal saisi.", "Confirmez l'adresse, corrigez les fautes et supprimez les anciennes suggestions. Faites v\u00e9rifier les alias par l'administrateur destinataire."],
    'smtpEnhanced1.2': ['Domaine destinataire invalide pour le courrier', "Le domaine n'existe pas ou ne peut pas recevoir de messages.", 'Corrigez le nom et faites v\u00e9rifier enregistrement du domaine, MX et service de messagerie.'],
    'smtpEnhanced1.3': ["Syntaxe d'adresse destinataire incorrecte", "L'adresse destinataire est mal form\u00e9e.", "Corrigez la partie locale, le s\u00e9parateur @ et le domaine de l'enveloppe."],
    'smtpEnhanced1.4': ['Adresse destinataire ambigu\u00eb', "L'annuaire associe cette adresse \u00e0 plusieurs destinataires.", "Faites corriger les alias ou entr\u00e9es d'annuaire en conflit."],
    'smtpEnhanced1.5': ['Adresse destinataire accept\u00e9e', "Le syst\u00e8me a accept\u00e9 l'adresse indiqu\u00e9e.", "Aucune correction d'adresse indiqu\u00e9e. Cette \u00e9tape ne prouve pas la remise finale en bo\u00eete de r\u00e9ception."],
    'smtpEnhanced1.6': ['Destinataire d\u00e9plac\u00e9 sans transfert', "L'ancienne bo\u00eete ne re\u00e7oit plus et ne poss\u00e8de pas de transfert.", "Obtenez l'adresse actuelle et mettez vos contacts \u00e0 jour."],
    'smtpEnhanced1.7': ["Syntaxe d'adresse exp\u00e9diteur incorrecte", "L'adresse de retour dans l'enveloppe est mal form\u00e9e.", "Corrigez MAIL FROM et la configuration de l'application."],
    'smtpEnhanced1.8': ['Domaine exp\u00e9diteur inapte aux retours', "Le domaine est invalide pour les retours. Exchange Online utilise aussi 5.1.8 pour un exp\u00e9diteur sortant bloqu\u00e9.", "V\u00e9rifiez domaine et DNS. Pour un blocage Exchange, recherchez une compromission et suivez la r\u00e9cup\u00e9ration des entit\u00e9s restreintes."],
    'smtpEnhanced1.10': ['Le domaine destinataire publie un MX nul', "Le sens normalis\u00e9 est un refus explicite de courrier. Exchange Online utilise aussi 5.1.10 pour un destinataire absent de l'annuaire.", 'V\u00e9rifiez fournisseur et r\u00e9ponse. Pour MX nul, changez de destinataire ; pour Exchange, v\u00e9rifiez bo\u00eete et alias.'],
    'smtpEnhanced2.0': ['Erreur li\u00e9e \u00e0 la bo\u00eete', 'Un \u00e9tat de la bo\u00eete emp\u00eache la remise sans autre pr\u00e9cision.', 'Faites v\u00e9rifier \u00e9tat, quota et restrictions de remise.'],
    'smtpEnhanced2.1': ['Bo\u00eete d\u00e9sactiv\u00e9e', "La bo\u00eete existe, mais n'accepte pas les messages.", 'Faites v\u00e9rifier \u00e9tat du compte, licence et disponibilit\u00e9 de la bo\u00eete.'],
    'smtpEnhanced2.2': ['Bo\u00eete pleine ou quota d\u00e9pass\u00e9', "La bo\u00eete a atteint son quota. Exchange Online peut plut\u00f4t indiquer un quota de soumission de l'exp\u00e9diteur.", "Pour une bo\u00eete pleine, lib\u00e9rez de la place ou ajustez le quota. Pour l'envoi, r\u00e9duisez le volume et v\u00e9rifiez limites et s\u00e9curit\u00e9 du compte."],
    'smtpEnhanced2.3': ['Taille maximale de la bo\u00eete d\u00e9pass\u00e9e', 'Le message d\u00e9passe une limite propre au destinataire.', 'R\u00e9duisez message et pi\u00e8ces jointes, en tenant compte de MIME, ou utilisez un lien de partage autoris\u00e9.'],
    'smtpEnhanced2.4': ['\u00c9chec de d\u00e9veloppement de liste', 'Le groupe ne peut pas \u00eatre d\u00e9velopp\u00e9 en destinataires.', "Faites corriger les membres, l'annuaire et le service des groupes."],
    'smtpEnhanced3.0': ['Erreur du syst\u00e8me de messagerie', 'Le service destinataire signale un probl\u00e8me g\u00e9n\u00e9ral.', 'Faites v\u00e9rifier service, files et diagnostics du serveur.'],
    'smtpEnhanced3.1': ['Stockage du syst\u00e8me \u00e9puis\u00e9', 'Le stockage partag\u00e9 du serveur est plein, pas seulement une bo\u00eete.', 'Le destinataire doit restaurer la capacit\u00e9 du serveur. Laissez les tentatives espac\u00e9es se poursuivre.'],
    'smtpEnhanced3.2': ["Le syst\u00e8me n'accepte pas de messages", 'Maintenance, arr\u00eat, surcharge ou autre refus de courrier.', 'V\u00e9rifiez service et limites de connexion. Une r\u00e9ponse permanente exige une correction avant un nouvel envoi.'],
    'smtpEnhanced3.3': ['Fonction de messagerie requise indisponible', 'Le destinataire ou une passerelle ne g\u00e8re pas une fonction demand\u00e9e.', 'Utilisez des fonctions admises ou faites corriger la passerelle.'],
    'smtpEnhanced3.4': ['Taille maximale du syst\u00e8me d\u00e9pass\u00e9e', 'Le message d\u00e9passe la taille autoris\u00e9e par le serveur destinataire.', 'R\u00e9duisez la taille encod\u00e9e ou partagez un lien autoris\u00e9. V\u00e9rifiez les limites sur toute la route.'],
    'smtpEnhanced3.5': ['Syst\u00e8me de messagerie mal configur\u00e9', 'Un serveur destinataire ou interm\u00e9diaire est mal configur\u00e9.', 'Faites v\u00e9rifier domaines accept\u00e9s, connecteurs, routage et service.'],
    'smtpEnhanced4.0': ['Erreur r\u00e9seau ou routage', 'Une erreur de connexion ou de routage est signal\u00e9e sans d\u00e9tail.', 'V\u00e9rifiez MX, adresses, accessibilit\u00e9 r\u00e9seau et routes de courrier.'],
    'smtpEnhanced4.1': ["L'h\u00f4te destinataire ne r\u00e9pond pas", 'Le serveur peut \u00eatre hors ligne, surcharg\u00e9 ou bloqu\u00e9 par un pare-feu.', "V\u00e9rifiez \u00e9coute SMTP, cibles MX et pare-feu avec l'administrateur destinataire."],
    'smtpEnhanced4.2': ['Connexion interrompue pendant la remise', "Une connexion \u00e9tablie s'est interrompue ou a expir\u00e9 avant la fin.", 'V\u00e9rifiez stabilit\u00e9 r\u00e9seau, d\u00e9lais SMTP, erreurs TLS et service destinataire.'],
    'smtpEnhanced4.3': ['Annuaire ou DNS indisponible', "Une recherche DNS ou d'annuaire n\u00e9cessaire au routage a \u00e9chou\u00e9.", 'V\u00e9rifiez DNS autoritatif, r\u00e9solveurs, DNSSEC et annuaire.'],
    'smtpEnhanced4.4': ['Aucune route de courrier utilisable', 'Le serveur suivant est ind\u00e9termin\u00e9 ou la route configur\u00e9e est incorrecte.', 'V\u00e9rifiez MX, A/AAAA, domaines accept\u00e9s, connecteurs et h\u00f4tes actifs de relais.'],
    'smtpEnhanced4.5': ['Syst\u00e8me de messagerie satur\u00e9', 'Les files ou la capacit\u00e9 de remise sont surcharg\u00e9es.', "R\u00e9duisez parall\u00e9lisme et d\u00e9bit ; laissez les files se vider."],
    'smtpEnhanced4.6': ['Boucle de routage', 'Transferts ou connecteurs font repasser le message par les m\u00eames syst\u00e8mes.', 'Tracez les sauts et supprimez le transfert ou connecteur circulaire.'],
    'smtpEnhanced4.7': ['D\u00e9lai de remise expir\u00e9', 'Le message est rest\u00e9 en file au-del\u00e0 de sa dur\u00e9e de vie.', "Corrigez la cause des erreurs pr\u00e9c\u00e9dentes. Un message expir\u00e9 n'est plus r\u00e9essay\u00e9 automatiquement et peut n\u00e9cessiter un nouvel envoi."],
    'smtpEnhanced5.0': ['Erreur de protocole de messagerie', "L'\u00e9change SMTP a \u00e9chou\u00e9 sans d\u00e9tail pr\u00e9cis.", 'Examinez la s\u00e9quence SMTP du client et la r\u00e9ponse du serveur.'],
    'smtpEnhanced5.1': ['Commande invalide ou mal ordonn\u00e9e', "La commande n'est pas admise ou intervient dans un \u00e9tat SMTP incorrect.", 'V\u00e9rifiez la s\u00e9quence et les capacit\u00e9s annonc\u00e9es.'],
    'smtpEnhanced5.2': ['Erreur de syntaxe SMTP', 'Le destinataire ne peut pas analyser une commande.', 'Corrigez le format et mettez \u00e0 jour la biblioth\u00e8que SMTP.'],
    'smtpEnhanced5.3': ['Trop de destinataires', 'La transaction d\u00e9passe le nombre de destinataires admis.', 'Divisez la liste selon les limites publi\u00e9es. Ne renvoyez pas aux destinataires d\u00e9j\u00e0 accept\u00e9s.'],
    'smtpEnhanced5.4': ['Arguments SMTP incorrects', 'Une commande reconnue contient des arguments invalides ou non admis.', "Corrigez les adresses d'enveloppe et utilisez seulement les extensions n\u00e9goci\u00e9es."],
    'smtpEnhanced5.5': ['Versions de protocole incompatibles', 'Les syst\u00e8mes ne partagent pas les fonctions de protocole requises.', 'Mettez \u00e0 jour client ou passerelle et v\u00e9rifiez la compatibilit\u00e9.'],
    'smtpEnhanced6.0': ["Probl\u00e8me de contenu ou d'encodage", 'La repr\u00e9sentation du contenu emp\u00eache le traitement.', 'Validez en-t\u00eates MIME, encodages et pi\u00e8ces jointes selon le diagnostic original.'],
    'smtpEnhanced6.1': ['Type de contenu non pris en charge', "Un type MIME ou un encodage n'est pas pris en charge.", 'Utilisez des formats admis ou un lien de partage autoris\u00e9.'],
    'smtpEnhanced6.2': ['Conversion requise interdite', 'La remise n\u00e9cessite une conversion interdite par la strat\u00e9gie.', 'Envoyez un format compatible ou faites examiner la strat\u00e9gie applicable.'],
    'smtpEnhanced6.3': ['Conversion requise indisponible', 'Une passerelle ne peut pas convertir le message pour le saut suivant.', 'Produisez un message MIME compatible et v\u00e9rifiez les capacit\u00e9s de conversion.'],
    'smtpEnhanced6.5': ['\u00c9chec de conversion du message', "Une conversion de contenu n\u00e9cessaire n'a pas pu aboutir.", "V\u00e9rifiez l'encodage et les erreurs de la passerelle de conversion."],
    'smtpEnhanced6.7': ['Adresse internationalis\u00e9e non prise en charge', "Cette route n'accepte pas les adresses d'enveloppe non ASCII.", 'Utilisez SMTPUTF8 ou un v\u00e9ritable alias ASCII fourni par le destinataire. Ne retirez pas simplement des caract\u00e8res.'],
    'smtpEnhanced6.8': ['R\u00e9ponse UTF-8 indisponible pour ce client', "Le serveur a besoin d'une r\u00e9ponse UTF-8 non n\u00e9goci\u00e9e par le client.", 'Utilisez un client SMTPUTF8 et une route compatible.'],
    'smtpEnhanced6.9': ['Message UTF-8 incompatible avec certains destinataires', "Au moins un destinataire n'est pas accessible via SMTPUTF8.", 'V\u00e9rifiez toute la route et utilisez des alias compatibles confirm\u00e9s, si disponibles.'],
    'smtpEnhanced7.0': ['Erreur de s\u00e9curit\u00e9 ou strat\u00e9gie non pr\u00e9cis\u00e9e', "Une restriction, l'authentification ou un filtre emp\u00eache l'action.", 'Lisez la r\u00e9ponse compl\u00e8te et faites v\u00e9rifier authentification et d\u00e9cisions de strat\u00e9gie.'],
    'smtpEnhanced7.1': ['Remise restreinte par une strat\u00e9gie', 'Relais refus\u00e9, restrictions, filtrage ou authentification manquante sont possibles. Une r\u00e9ponse temporaire peut signaler une liste grise.', 'V\u00e9rifiez point SMTP, authentification, autorisations et r\u00e9putation. Consultez la strat\u00e9gie pr\u00e9cise sans d\u00e9sactiver globalement les protections.'],
    'smtpEnhanced7.2': ['Envoi \u00e0 cette liste non autoris\u00e9', "L'exp\u00e9diteur ne peut pas utiliser cette liste.", 'Demandez une autorisation au propri\u00e9taire ou utilisez une adresse autoris\u00e9e.'],
    'smtpEnhanced7.3': ['Conversion s\u00e9curis\u00e9e indisponible', 'La passerelle ne peut pas effectuer une conversion s\u00e9curis\u00e9e requise.', "Utilisez un format s\u00e9curis\u00e9 commun et consultez l'administrateur."],
    'smtpEnhanced7.4': ['Fonction de s\u00e9curit\u00e9 non prise en charge', 'Le destinataire ne g\u00e8re pas une fonction de s\u00e9curit\u00e9 demand\u00e9e.', 'Utilisez une m\u00e9thode admise sans affaiblir la s\u00e9curit\u00e9 du transport.'],
    'smtpEnhanced7.5': ['\u00c9chec de validation cryptographique', 'Une cl\u00e9 ou un certificat manque ou est invalide. Certains fournisseurs visent les certificats TLS ou MTA-STS.', 'V\u00e9rifiez validit\u00e9, noms, cha\u00eene de confiance et strat\u00e9gie de s\u00e9curit\u00e9 concern\u00e9e.'],
    'smtpEnhanced7.6': ['Algorithme cryptographique non pris en charge', 'Les syst\u00e8mes ne partagent pas un algorithme requis.', 'Mettez les syst\u00e8mes \u00e0 jour et choisissez un algorithme s\u00fbr commun.'],
    'smtpEnhanced7.7': ["\u00c9chec du contr\u00f4le d'int\u00e9grit\u00e9", 'Le contenu a chang\u00e9 ou un contr\u00f4le cryptographique a \u00e9chou\u00e9.', 'Recherchez les modifications des passerelles ou transferts et v\u00e9rifiez les signatures.'],
    'smtpEnhanced7.8': ["Identifiants d'authentification refus\u00e9s", 'AUTH a utilis\u00e9 des identifiants invalides ou insuffisants.', "V\u00e9rifiez compte, OAuth ou m\u00e9thode admise, droits de l'application et param\u00e8tres du service."],
    'smtpEnhanced7.9': ["M\u00e9thode d'authentification trop faible", 'Le m\u00e9canisme choisi ne satisfait pas la strat\u00e9gie destinataire.', 'Utilisez une m\u00e9thode plus forte annonc\u00e9e et gardez TLS activ\u00e9.'],
    'smtpEnhanced7.10': ['Connexion chiffr\u00e9e n\u00e9cessaire', 'Le m\u00e9canisme exige une couche de confidentialit\u00e9 plus forte.', "\u00c9tablissez TLS avant l'authentification ou choisissez un m\u00e9canisme plus fort admis."],
    'smtpEnhanced7.11': ["L'authentification exige le chiffrement", "La m\u00e9thode ne peut pas fonctionner sur une connexion non chiffr\u00e9e.", "Configurez STARTTLS ou le point TLS document\u00e9 avant l'authentification."],
    'smtpEnhanced7.12': ["Transition d'authentification n\u00e9cessaire", 'Le compte doit \u00eatre migr\u00e9 avant de pouvoir utiliser le m\u00e9canisme choisi.', 'Suivez la proc\u00e9dure de transition du fournisseur sur une connexion s\u00e9curis\u00e9e.'],
    'smtpEnhanced7.13': ['Compte d\u00e9sactiv\u00e9 ou destinataire restreint', 'Le standard indique un compte d\u00e9sactiv\u00e9. Exchange Online vise aussi les dossiers publics r\u00e9serv\u00e9s aux exp\u00e9diteurs internes authentifi\u00e9s.', 'V\u00e9rifiez fournisseur et r\u00e9ponse. Consultez le responsable du compte ou du dossier public.'],
    'smtpEnhanced7.20': ['Aucune signature DKIM valide', 'Le destinataire ne valide aucune signature DKIM du message.', "Activez DKIM sur le service d'envoi r\u00e9el, publiez les s\u00e9lecteurs corrects et recherchez les modifications apr\u00e8s signature."],
    'smtpEnhanced7.21': ['Aucune signature DKIM acceptable', 'Une signature valide ne satisfait pas la strat\u00e9gie destinataire.', 'V\u00e9rifiez domaine signataire, algorithme, force de cl\u00e9 et exigences du destinataire.'],
    'smtpEnhanced7.22': ["Le domaine DKIM diff\u00e8re de l'auteur", 'Une signature valide ne correspond pas au domaine From requis.', 'Configurez une signature avec un domaine align\u00e9 sur le From visible.'],
    'smtpEnhanced7.23': ['\u00c9chec de validation SPF', "L'IP \u00e9mettrice r\u00e9elle n'est pas autoris\u00e9e par le SPF du domaine d'enveloppe.", "V\u00e9rifiez MAIL FROM et le service. Publiez un seul SPF valide autorisant l'envoi dans la limite de recherches DNS."],
    'smtpEnhanced7.24': ["Erreur d'\u00e9valuation SPF", "DNS, plusieurs SPF, une syntaxe incorrecte ou trop de recherches emp\u00eachent l'\u00e9valuation.", 'Corrigez DNS ou SPF, contr\u00f4lez include et redirect et gardez un seul SPF avec au plus dix termes interrogeant DNS.'],
    'smtpEnhanced7.25': ['\u00c9chec de validation DNS inverse', "L'IP \u00e9mettrice manque de PTR acceptable ou de r\u00e9solution directe correspondante.", "Faites configurer PTR et A/AAAA concordants par le propri\u00e9taire de l'IP selon les exigences du fournisseur."],
    'smtpEnhanced7.26': ["\u00c9chec des contr\u00f4les d'authentification", 'Plusieurs contr\u00f4les ont \u00e9chou\u00e9, souvent SPF, DKIM ou DMARC. Le code seul ne pr\u00e9cise pas lequel.', 'Examinez Authentication-Results et la r\u00e9ponse. Corrigez SPF et DKIM puis leur alignement avec From pour DMARC.'],
    'smtpEnhanced7.27': ['Le domaine exp\u00e9diteur publie un MX nul', 'Le domaine refuse les retours et le destinataire refuse de tels exp\u00e9diteurs.', "Utilisez un domaine d'enveloppe v\u00e9rifi\u00e9 pouvant recevoir les retours n\u00e9cessaires."],
    'smtpEnhanced7.28': ['Flux abusif de messages suspect\u00e9', 'Le destinataire consid\u00e8re le trafic comme une inondation de messages.', "Arr\u00eatez les envois involontaires, v\u00e9rifiez la s\u00e9curit\u00e9, r\u00e9duisez le volume et suivez la proc\u00e9dure du destinataire."],
    'smtpEnhanced7.29': ['\u00c9chec de validation ARC', 'La cha\u00eene de r\u00e9ception authentifi\u00e9e ne peut pas \u00eatre valid\u00e9e.', "V\u00e9rifiez les signatures ARC, l'ordre des sceaux et les modifications des passerelles de transfert."],
    'smtpEnhanced7.30': ['Prise en charge TLS requise indisponible', 'Le message exige REQUIRETLS, mais le prochain saut ne le g\u00e8re pas.', 'Utilisez une route REQUIRETLS de bout en bout et faites r\u00e9soudre cette incompatibilit\u00e9.'],
    'smtpProvider4.4.316': ['Connexion distante refus\u00e9e', "Exchange Online ne peut pas joindre le SMTP destinataire.", 'Faites v\u00e9rifier \u00e9coute, pare-feu, MX et disponibilit\u00e9 du service.'],
    'smtpProvider4.4.317': ['Certificat TLS distant non approuv\u00e9', 'Exchange Online ne valide pas la cha\u00eene du certificat destinataire.', 'Faites installer un certificat valide avec sa cha\u00eene de confiance compl\u00e8te sur SMTP.'],
    'smtpProvider5.2.121': ['Limite par exp\u00e9diteur pour ce destinataire', "Exchange Online limite les messages d'un exp\u00e9diteur \u00e0 un destinataire pr\u00e9cis.", 'R\u00e9duisez les messages \u00e0 ce destinataire et attendez la r\u00e9cup\u00e9ration de capacit\u00e9 avant un nouvel envoi.'],
    'smtpProvider5.2.122': ['D\u00e9bit de r\u00e9ception d\u00e9pass\u00e9', 'Le destinataire Exchange Online d\u00e9passe son d\u00e9bit total de r\u00e9ception.', 'Coordonnez avec son administrateur et r\u00e9duisez le trafic automatique avant de renvoyer.'],
    'smtpProvider5.4.1': ['Acc\u00e8s destinataire ou relais refus\u00e9', 'Exchange Online peut ignorer le destinataire ou ne pas accepter le domaine.', 'V\u00e9rifiez bo\u00eete, alias, synchronisation, domaines accept\u00e9s et routes MX ou connecteurs.'],
    'smtpProvider5.4.14': ['Boucle de messagerie d\u00e9tect\u00e9e', 'Exchange Online d\u00e9tecte un transfert ou connecteur circulaire.', 'Tracez les sauts et corrigez connecteurs, domaines accept\u00e9s ou transferts en boucle.'],
    'smtpProvider5.6.11': ['Fins de ligne incorrectes', 'Le message contient des LF seuls au lieu des CRLF requis.', "Mettez l'application ou la biblioth\u00e8que SMTP \u00e0 jour pour produire des fins de ligne conformes."],
    'smtpProvider5.7.12': ['Le destinataire exige un exp\u00e9diteur interne', 'Le destinataire Exchange Online refuse les exp\u00e9diteurs externes ou non authentifi\u00e9s.', "Faites examiner les restrictions et autoriser l'exp\u00e9diteur pr\u00e9vu si appropri\u00e9."],
    'smtpProvider5.7.57': ['Client non authentifi\u00e9 pour la soumission', "Une application ou un appareil ne s'est pas authentifi\u00e9 comme requis par Exchange Online.", 'V\u00e9rifiez point de soumission, STARTTLS, m\u00e9thode et strat\u00e9gies SMTP AUTH du compte et du locataire. Ne cr\u00e9ez pas de relais anonyme.'],
    'smtpProvider5.7.64': ["Le connecteur n'identifie pas le locataire", "L'IP ou le certificat local ne correspond plus au connecteur entrant Exchange Online.", 'V\u00e9rifiez IP autoris\u00e9es, identit\u00e9 du certificat TLS et domaines accept\u00e9s du connecteur.'],
    'smtpProvider5.7.124': ['Exp\u00e9diteur non autoris\u00e9 pour le groupe', "L'exp\u00e9diteur ne figure pas parmi ceux autoris\u00e9s par le groupe.", "Demandez au propri\u00e9taire de v\u00e9rifier et d'autoriser l'exp\u00e9diteur pr\u00e9vu."],
    'smtpProvider5.7.133': ['Le groupe refuse les exp\u00e9diteurs externes', 'Le groupe accepte uniquement les exp\u00e9diteurs internes authentifi\u00e9s.', 'Demandez au propri\u00e9taire de revoir la restriction externe.'],
    'smtpProvider5.7.134': ['La bo\u00eete refuse les exp\u00e9diteurs externes', 'La bo\u00eete est r\u00e9serv\u00e9e aux exp\u00e9diteurs internes authentifi\u00e9s.', 'Faites examiner les restrictions de remise de la bo\u00eete.'],
    'smtpProvider5.7.509': ['Strat\u00e9gie de rejet DMARC appliqu\u00e9e', 'Le domaine From visible \u00e9choue \u00e0 DMARC et publie un rejet.', "Corrigez SPF ou DKIM align\u00e9 du service r\u00e9el. Examinez les transferts sans supprimer globalement la protection DMARC."],
    'smtpProvider5.7.520': ['Transfert externe automatique bloqu\u00e9', 'Une strat\u00e9gie sortante Exchange Online interdit le transfert externe automatique.', 'Examinez r\u00e8gle et s\u00e9curit\u00e9. Utilisez une destination approuv\u00e9e ou une exception cibl\u00e9e uniquement si justifi\u00e9e.'],
    'smtpProvider5.7.705': ['Locataire exp\u00e9diteur restreint', 'Microsoft d\u00e9tecte du trafic sortant suspect et restreint le locataire.', 'Arr\u00eatez les abus, recherchez compromission ou relais ouverts, s\u00e9curisez les comptes puis contactez le support.'],
    'smtpProvider5.7.708': ["Trafic de l'IP \u00e9mettrice refus\u00e9", 'Microsoft restreint le locataire ou son trafic sortant pour activit\u00e9 suspecte.', 'Corrigez les envois ind\u00e9sirables puis suivez la proc\u00e9dure de support Microsoft.'],
    'smtpProvider5.7.750': ['Envoi depuis des domaines non inscrits bloqu\u00e9', 'Exchange Online d\u00e9tecte un usage suspect de domaines non provisionn\u00e9s dans le locataire.', 'Ajoutez et v\u00e9rifiez les domaines l\u00e9gitimes et recherchez les envois non autoris\u00e9s.']
  },
  de: {
    smtpBasic211: ['Systemstatus', 'Der Server liefert Status- oder Hilfeinformationen.', 'Kein Fehler zu beheben. Setzen Sie den SMTP-Dialog fort.'],
    smtpBasic214: ['Hilfeantwort', 'Der Server liefert Hilfe zu einem Befehl.', 'Verwenden Sie die angegebene Befehlssyntax.'],
    smtpBasic220: ['Dienst bereit', 'SMTP ist bereit oder STARTTLS kann beginnen.', 'Fahren Sie mit EHLO fort oder schlie\u00dfen Sie nach STARTTLS den TLS-Handshake ab. Dies ist keine Zustellbest\u00e4tigung.'],
    smtpBasic221: ['Verbindung wird geschlossen', 'Der Server beendet die Sitzung, meist nach QUIT.', 'Ein regul\u00e4res Ende erfordert keine Korrektur. Pr\u00fcfen Sie die vorherige Antwort zum Nachrichtenergebnis.'],
    smtpBasic235: ['Authentifizierung erfolgreich', 'Der Server hat die SMTP-Authentifizierung akzeptiert.', 'Fahren Sie mit dem Versand fort. Authentifizierung allein beweist keine Zustellung.'],
    smtpBasic250: ['Angeforderte Aktion angenommen', 'Der Befehl wurde abgeschlossen. Nach DATA \u00fcbernimmt der Server die Verantwortung f\u00fcr die Nachricht.', 'Pr\u00fcfen Sie die Nachrichtenverfolgung. Die Annahme garantiert keine Ablage im Posteingang.'],
    smtpBasic251: ['Empf\u00e4nger wird weitergeleitet', 'Der Empf\u00e4nger ist nicht lokal; der Server leitet die Nachricht weiter.', 'Best\u00e4tigen Sie die Weiterleitungsadresse beim Empf\u00e4nger, bevor Sie Kontakte \u00e4ndern.'],
    smtpBasic252: ['Empf\u00e4nger nicht \u00fcberpr\u00fcfbar', 'Der Server pr\u00fcft die Adresse nicht, versucht aber die Zustellung.', 'Dies beweist nicht, dass das Postfach existiert. Pr\u00fcfen Sie das endg\u00fcltige Ergebnis.'],
    smtpBasic334: ['Authentifizierungsanforderung', 'Der Server erwartet den n\u00e4chsten AUTH-Schritt.', 'Lassen Sie den Client das unterst\u00fctzte Verfahren \u00fcber eine sichere Verbindung abschlie\u00dfen.'],
    smtpBasic354: ['Bereit f\u00fcr Nachrichteninhalt', 'Der Server hat DATA akzeptiert und wartet auf den Inhalt.', 'Senden Sie den Inhalt und warten Sie auf die abschlie\u00dfende Antwort. Die Nachricht ist noch nicht angenommen.'],
    smtpBasic421: ['Dienst vor\u00fcbergehend nicht verf\u00fcgbar', 'Wartung, \u00dcberlastung, Drosselung oder eine Verbindungsrichtlinie beendet die Sitzung.', 'Pr\u00fcfen Sie Dienst und Sendelimits. Nutzen Sie Wiederholungen mit Wartezeiten statt st\u00e4ndiger Neuverbindungen.'],
    smtpBasic432: ['Authentifizierungsumstellung erforderlich', 'SMTP AUTH verlangt eine Kontoumstellung auf das gew\u00e4hlte Verfahren. Anbieter k\u00f6nnen den Code anders nutzen.', 'Folgen Sie der Anbieter-Migration. Pr\u00fcfen Sie den erweiterten Code auf anbieterspezifische Drosselung.'],
    smtpBasic450: ['Postfach vor\u00fcbergehend nicht verf\u00fcgbar', 'Das Postfach ist m\u00f6glicherweise belegt, vor\u00fcbergehend deaktiviert, durch Greylisting oder Richtlinien eingeschr\u00e4nkt.', 'Lassen Sie geplante Wiederholungen zu. Bei anhaltenden Fehlern Postfach und Richtlinien pr\u00fcfen lassen.'],
    smtpBasic451: ['Vor\u00fcbergehender Verarbeitungsfehler', 'Lokale Verarbeitung, Verzeichnis, DNS oder Richtlinienauswertung ist fehlgeschlagen.', 'Pr\u00fcfen Sie erweiterten Code und Dienstzustand. Anhaltende Fehler muss der zust\u00e4ndige Administrator beheben.'],
    smtpBasic452: ['Unzureichende Ressourcen', 'Speicher fehlt oder die Empf\u00e4ngergrenze pro Transaktion wurde erreicht.', 'Je nach Antwort Speicher freigeben oder kleinere Empf\u00e4ngergruppen verwenden.'],
    smtpBasic454: ['Vor\u00fcbergehender Authentifizierungs- oder TLS-Fehler', 'Authentifizierungsdienst oder TLS ist kurzzeitig nicht verf\u00fcgbar.', 'Pr\u00fcfen Sie erweiterten Code, Dienstzustand und TLS. Lassen Sie Verschl\u00fcsselung aktiviert.'],
    smtpBasic455: ['Parameter vor\u00fcbergehend nicht unterst\u00fctzt', 'Ein MAIL FROM- oder RCPT TO-Parameter kann derzeit nicht verarbeitet werden.', 'Verwenden Sie EHLO-Parameter und die Wiederholungsrichtlinie des Versanddienstes.'],
    smtpBasic500: ['Befehl nicht erkannt', 'Der Befehl wird nicht unterst\u00fctzt, ist fehlerhaft oder zu lang.', 'Pr\u00fcfen Sie Clientkonfiguration, Zeilenl\u00e4nge und EHLO-Funktionen.'],
    smtpBasic501: ['Ung\u00fcltige Befehlsargumente', 'Ein Argument, eine Adresse oder ein Parameter hat eine ung\u00fcltige Syntax.', 'Korrigieren Sie Umschlagadressen und Parameter. Nutzen Sie eine gepflegte SMTP-Bibliothek.'],
    smtpBasic502: ['Befehl nicht implementiert', 'Der Server erkennt den Befehl, implementiert ihn aber nicht.', 'Nutzen Sie unterst\u00fctzte Befehle und pr\u00fcfen Sie den SMTP-Endpunkt.'],
    smtpBasic503: ['Falsche Befehlsreihenfolge', 'Ein vorheriger Befehl fehlt oder eine Transaktion ist bereits ge\u00f6ffnet.', 'Pr\u00fcfen Sie EHLO, Authentifizierung, MAIL FROM, RCPT TO und DATA im Client.'],
    smtpBasic504: ['Befehlsparameter nicht unterst\u00fctzt', 'Ein Parameter oder Authentifizierungsverfahren wird nicht unterst\u00fctzt.', 'Nutzen Sie die nach EHLO und STARTTLS angek\u00fcndigten Verfahren und Erweiterungen.'],
    smtpBasic521: ['Host nimmt keine E-Mails an', 'Der Zielhost bietet ausdr\u00fccklich keinen SMTP-Maildienst an.', 'Pr\u00fcfen Sie Empf\u00e4ngerdom\u00e4ne und MX-Konfiguration mit deren Administrator.'],
    smtpBasic530: ['Authentifizierung oder STARTTLS erforderlich', 'Der Server verlangt Authentifizierung oder eine sichere Verbindung vor dem Befehl.', 'Pr\u00fcfen Sie die Antwort und aktivieren Sie STARTTLS sowie das unterst\u00fctzte Verfahren. TLS nicht deaktivieren.'],
    smtpBasic534: ['Authentifizierung zu schwach', 'Das gew\u00e4hlte Verfahren erf\u00fcllt die Serverrichtlinie nicht.', 'Nutzen Sie ein st\u00e4rkeres unterst\u00fctztes Verfahren und eine sichere Verbindung.'],
    smtpBasic535: ['Authentifizierung abgelehnt', 'Anmeldedaten, Berechtigungen oder Authentifizierungsablauf wurden abgelehnt.', 'Pr\u00fcfen Sie Konto, Anwendungsrechte und unterst\u00fctzte Verfahren. Hier niemals Kennw\u00f6rter oder Token einf\u00fcgen.'],
    smtpBasic538: ['Verschl\u00fcsselung f\u00fcr Authentifizierung erforderlich', 'Das Verfahren ben\u00f6tigt eine verschl\u00fcsselte Verbindung.', 'Konfigurieren Sie STARTTLS oder den dokumentierten TLS-Endpunkt vor der Anmeldung.'],
    smtpBasic550: ['Postfach nicht verf\u00fcgbar oder Aktion abgelehnt', 'Die Adresse fehlt m\u00f6glicherweise oder eine Zugriffs-, Empf\u00e4nger- oder Relayrichtlinie blockiert die Anfrage.', 'Unterscheiden Sie Adressfehler von Richtlinien- oder Authentifizierungsfehlern anhand des erweiterten Codes und der Originalantwort.'],
    smtpBasic551: ['Empf\u00e4nger ist nicht lokal', 'Der Server lehnt die Zustellung ab und nennt m\u00f6glicherweise eine Weiterleitungsadresse.', 'Best\u00e4tigen Sie die Ersatzadresse beim Empf\u00e4nger und korrigieren Sie Kontakte oder Routing.'],
    smtpBasic552: ['Speicher- oder Nachrichtengrenze \u00fcberschritten', 'Postfachquote oder Nachrichtengr\u00f6\u00dfe \u00fcberschritten. \u00c4ltere Server verwenden dies auch bei zu vielen Empf\u00e4ngern.', 'Geben Sie Speicher frei oder verkleinern Sie die Nachricht. Nur bei ausdr\u00fccklich zu vielen Empf\u00e4ngern den Stapel teilen und diese erneut versuchen.'],
    smtpBasic553: ['Postfachname nicht erlaubt', 'Eine Umschlagadresse ist syntaktisch falsch oder nicht erlaubt.', 'Pr\u00fcfen Sie Absender, Empf\u00e4nger, erlaubte Identit\u00e4ten und erweiterten Statuscode.'],
    smtpBasic554: ['Transaktion abgelehnt', 'Nachricht oder Verbindung abgelehnt; der allgemeine Code allein erkl\u00e4rt die Ursache nicht.', 'Pr\u00fcfen Sie erweiterten Code und Empfangsdiagnose zu Inhalt, Richtlinien, Authentifizierung oder Routing.'],
    smtpBasic555: ['Umschlagparameter nicht unterst\u00fctzt', 'Ein MAIL FROM- oder RCPT TO-Parameter ist unbekannt oder nicht implementiert.', 'Entfernen Sie nicht unterst\u00fctzte Parameter und nutzen Sie nur angek\u00fcndigte EHLO-Erweiterungen.'],
    smtpBasic556: ['Empf\u00e4ngerdom\u00e4ne nimmt keine E-Mails an', 'Die Dom\u00e4ne lehnt E-Mails ausdr\u00fccklich ab, h\u00e4ufig per Null-MX.', 'Nutzen Sie eine andere best\u00e4tigte Adresse. Ein absichtliches Null-MX nicht ohne Zustimmung des Eigent\u00fcmers ersetzen.'],
    'smtpEnhanced0.0': ['Keine zus\u00e4tzlichen Statusdetails', 'Der Server meldet nur ein allgemeines Ergebnis.', 'Pr\u00fcfen Sie vollst\u00e4ndige Serverantwort und Nachrichtenverfolgung.'],
    'smtpEnhanced1.0': ['Adressbezogener Fehler', 'Absender- oder Empf\u00e4ngeradresse konnte ohne genauere Angabe nicht verwendet werden.', 'Pr\u00fcfen Sie beide Umschlagadressen und das Empf\u00e4ngerverzeichnis.'],
    'smtpEnhanced1.1': ['Empf\u00e4ngerpostfach nicht gefunden', 'Postfach oder Alias fehlt, wurde gel\u00f6scht oder falsch eingegeben.', 'Best\u00e4tigen Sie die Adresse, korrigieren Sie Tippfehler und veraltete Autovervollst\u00e4ndigung. Lassen Sie Aliase pr\u00fcfen.'],
    'smtpEnhanced1.2': ['Empf\u00e4ngerdom\u00e4ne f\u00fcr E-Mail ung\u00fcltig', 'Die Zieldom\u00e4ne existiert nicht oder kann keine E-Mails annehmen.', 'Korrigieren Sie den Namen und lassen Sie Registrierung, MX und Maildienst pr\u00fcfen.'],
    'smtpEnhanced1.3': ['Ung\u00fcltige Empf\u00e4ngeradresssyntax', 'Die Empf\u00e4ngeradresse ist fehlerhaft aufgebaut.', 'Korrigieren Sie lokalen Teil, @-Trennzeichen und Dom\u00e4ne der Umschlagadresse.'],
    'smtpEnhanced1.4': ['Mehrdeutige Empf\u00e4ngeradresse', 'Das Verzeichnis ordnet die Adresse mehreren Empf\u00e4ngern zu.', 'Lassen Sie widerspr\u00fcchliche Aliase oder Verzeichniseintr\u00e4ge korrigieren.'],
    'smtpEnhanced1.5': ['Empf\u00e4ngeradresse angenommen', 'Das Zielsystem hat die angegebene Adresse akzeptiert.', 'Kein Adressfehler angezeigt. Dies beweist noch keine endg\u00fcltige Zustellung im Posteingang.'],
    'smtpEnhanced1.6': ['Empf\u00e4nger ohne Weiterleitung umgezogen', 'Das alte Postfach nimmt keine E-Mails mehr an und hat kein Weiterleitungsziel.', 'Erfragen Sie die aktuelle Adresse und aktualisieren Sie Kontakte.'],
    'smtpEnhanced1.7': ['Ung\u00fcltige Absenderadresssyntax', 'Die Umschlag-Absenderadresse ist fehlerhaft.', 'Korrigieren Sie MAIL FROM und die Absenderkonfiguration der Anwendung.'],
    'smtpEnhanced1.8': ['Absenderdom\u00e4ne empf\u00e4ngt keine R\u00fcckl\u00e4ufer', 'Die Dom\u00e4ne ist f\u00fcr R\u00fcckl\u00e4ufer ung\u00fcltig. Exchange Online nutzt 5.1.8 auch f\u00fcr gesperrte ausgehende Absender.', 'Pr\u00fcfen Sie Umschlagdom\u00e4ne und DNS. Bei Exchange-Sperren Kompromittierung untersuchen und den Wiederherstellungsprozess f\u00fcr eingeschr\u00e4nkte Entit\u00e4ten verwenden.'],
    'smtpEnhanced1.10': ['Empf\u00e4ngerdom\u00e4ne ver\u00f6ffentlicht Null-MX', 'Standardm\u00e4\u00dfig nimmt die Dom\u00e4ne ausdr\u00fccklich keine E-Mails an. Exchange Online nutzt 5.1.10 auch f\u00fcr nicht gefundene Empf\u00e4nger.', 'Pr\u00fcfen Sie Anbieter und Antwort. Bei Null-MX anderen Empf\u00e4nger verwenden; bei Exchange Postfach und Aliase pr\u00fcfen.'],
    'smtpEnhanced2.0': ['Postfachbezogener Fehler', 'Ein nicht n\u00e4her beschriebener Postfachzustand verhindert die Zustellung.', 'Lassen Sie Zustand, Quote und Zustellbeschr\u00e4nkungen pr\u00fcfen.'],
    'smtpEnhanced2.1': ['Postfach deaktiviert', 'Das Postfach existiert, nimmt aber keine Nachrichten an.', 'Lassen Sie Kontostatus, Lizenz und Postfachverf\u00fcgbarkeit pr\u00fcfen.'],
    'smtpEnhanced2.2': ['Postfach voll oder Quote \u00fcberschritten', 'Das Empf\u00e4ngerpostfach hat seine Quote erreicht. Exchange Online kann stattdessen eine Absender-Einlieferungsquote meinen.', 'Bei vollem Postfach Speicher freigeben oder Quote anpassen. Bei Versandquote Sendevolumen, Anbieterlimits und Kontosicherheit pr\u00fcfen.'],
    'smtpEnhanced2.3': ['Postfach-Nachrichtengr\u00f6\u00dfe \u00fcberschritten', 'Die Nachricht \u00fcberschreitet die Gr\u00f6\u00dfenbegrenzung dieses Postfachs.', 'Verkleinern Sie Nachricht und Anh\u00e4nge einschlie\u00dflich MIME-Aufschlag oder nutzen Sie einen genehmigten Dateilink.'],
    'smtpEnhanced2.4': ['Verteileraufl\u00f6sung fehlgeschlagen', 'Die Gruppe oder Liste l\u00e4sst sich nicht in Empf\u00e4nger aufl\u00f6sen.', 'Lassen Sie Mitgliedschaft, Verzeichnisfehler und Gruppendienst pr\u00fcfen.'],
    'smtpEnhanced3.0': ['Fehler im Mailsystem', 'Der Zieldienst meldet ein allgemeines Systemproblem.', 'Lassen Sie Dienstzustand, Warteschlangen und Serverdiagnosen pr\u00fcfen.'],
    'smtpEnhanced3.1': ['Systemspeicher ersch\u00f6pft', 'Gemeinsamer Serverspeicher ist ersch\u00f6pft, nicht nur eine Postfachquote.', 'Der Empfangsadministrator muss Kapazit\u00e4t wiederherstellen. Lassen Sie Wiederholungen mit Wartezeiten zu.'],
    'smtpEnhanced3.2': ['Mailsystem nimmt keine Nachrichten an', 'Wartung, Abschaltung, \u00dcberlastung oder eine andere Sperre verhindert die Annahme.', 'Pr\u00fcfen Sie Dienst und Verbindungslimits. Eine permanente Antwort erfordert Korrektur vor erneutem Versand.'],
    'smtpEnhanced3.3': ['Erforderliche Mailfunktion nicht verf\u00fcgbar', 'Ziel oder Gateway unterst\u00fctzt eine ben\u00f6tigte Funktion nicht.', 'Nutzen Sie unterst\u00fctzte Funktionen oder lassen Sie die Gatewaykonfiguration korrigieren.'],
    'smtpEnhanced3.4': ['System-Nachrichtengr\u00f6\u00dfe \u00fcberschritten', 'Die Nachricht \u00fcberschreitet die maximale Gr\u00f6\u00dfe des Empfangsservers.', 'Verkleinern Sie die kodierte Nachricht oder nutzen Sie genehmigte Dateilinks. Pr\u00fcfen Sie die gesamte Zustellstrecke.'],
    'smtpEnhanced3.5': ['Mailsystem falsch konfiguriert', 'Ein empfangendes oder zwischengeschaltetes System ist falsch konfiguriert.', 'Lassen Sie akzeptierte Dom\u00e4nen, Connectors, Routing und Dienstkonfiguration pr\u00fcfen.'],
    'smtpEnhanced4.0': ['Netzwerk- oder Routingfehler', 'Ein Verbindungs- oder Routingproblem wurde ohne Detail gemeldet.', 'Pr\u00fcfen Sie MX, Zieladressen, Erreichbarkeit und Mailrouting.'],
    'smtpEnhanced4.1': ['Zielhost antwortet nicht', 'Der Zielserver ist m\u00f6glicherweise offline, \u00fcberlastet oder durch eine Firewall blockiert.', 'Lassen Sie SMTP-Listener, MX-Ziele und Firewallregeln pr\u00fcfen.'],
    'smtpEnhanced4.2': ['Verbindung w\u00e4hrend Zustellung unterbrochen', 'Die Verbindung wurde hergestellt, brach aber vor Abschluss ab oder lief ab.', 'Pr\u00fcfen Sie Netzwerkstabilit\u00e4t, SMTP-Zeitlimits, TLS-Fehler und Empfangsdienst.'],
    'smtpEnhanced4.3': ['Verzeichnis oder DNS nicht verf\u00fcgbar', 'Eine f\u00fcr das Routing n\u00f6tige Verzeichnis- oder DNS-Abfrage schlug fehl.', 'Pr\u00fcfen Sie autoritatives DNS, Resolver, DNSSEC und Verzeichnisverf\u00fcgbarkeit.'],
    'smtpEnhanced4.4': ['Keine verwendbare Mailroute', 'Der n\u00e4chste Mailserver ist unbekannt oder eine konfigurierte Route ung\u00fcltig.', 'Pr\u00fcfen Sie MX, A/AAAA, akzeptierte Dom\u00e4nen sowie Connector- und Smarthost-Routen.'],
    'smtpEnhanced4.5': ['Mailsystem \u00fcberlastet', 'Warteschlangen oder Zustellkapazit\u00e4t sind ausgelastet.', 'Reduzieren Sie Parallelit\u00e4t und Senderate, damit Warteschlangen abgearbeitet werden.'],
    'smtpEnhanced4.6': ['Mail-Routingschleife', 'Weiterleitungen oder Connectors f\u00fchren wiederholt durch dieselben Systeme.', 'Verfolgen Sie die Stationen und entfernen Sie zyklische Weiterleitungen oder Routen.'],
    'smtpEnhanced4.7': ['Zustellzeit abgelaufen', 'Die Nachricht blieb bis zum Ablauf ihrer Warteschlangenlebensdauer unzugestellt.', 'Beheben Sie die Ursache fr\u00fcherer Fehler. Eine abgelaufene Nachricht wird nicht mehr automatisch wiederholt und muss eventuell neu gesendet werden.'],
    'smtpEnhanced5.0': ['Mailprotokollfehler', 'Der SMTP-Austausch ist ohne genauere Protokollangabe fehlgeschlagen.', 'Pr\u00fcfen Sie die SMTP-Sequenz und die Erkl\u00e4rung des Empf\u00e4ngers.'],
    'smtpEnhanced5.1': ['Ung\u00fcltiger oder falsch angeordneter Befehl', 'Ein Befehl ist nicht unterst\u00fctzt oder wurde im falschen SMTP-Zustand gesendet.', 'Pr\u00fcfen Sie Reihenfolge und angek\u00fcndigte Serverfunktionen.'],
    'smtpEnhanced5.2': ['SMTP-Syntaxfehler', 'Der Empf\u00e4nger konnte einen Befehl nicht auswerten.', 'Korrigieren Sie das Format und aktualisieren Sie die SMTP-Bibliothek.'],
    'smtpEnhanced5.3': ['Zu viele Empf\u00e4nger', 'Die Transaktion \u00fcberschreitet die Empf\u00e4ngergrenze des Empfangsdienstes.', 'Teilen Sie die Liste innerhalb der ver\u00f6ffentlichten Grenzen. Bereits akzeptierte Empf\u00e4nger nicht erneut anschreiben.'],
    'smtpEnhanced5.4': ['Ung\u00fcltige SMTP-Argumente', 'Ein bekannter Befehl enth\u00e4lt ung\u00fcltige oder nicht unterst\u00fctzte Argumente.', 'Korrigieren Sie Umschlagadressen und nutzen Sie nur ausgehandelte Erweiterungen.'],
    'smtpEnhanced5.5': ['Protokollversionen unvertr\u00e4glich', 'Die Systeme k\u00f6nnen sich nicht auf n\u00f6tige Protokollfunktionen einigen.', 'Aktualisieren Sie Client oder Gateway und pr\u00fcfen Sie die Kompatibilit\u00e4t.'],
    'smtpEnhanced6.0': ['Inhalts- oder Kodierungsproblem', 'Die Inhaltsdarstellung verhindert die Verarbeitung der Nachricht.', 'Pr\u00fcfen Sie MIME-Header, Kodierungen und Anh\u00e4nge anhand der Originaldiagnose.'],
    'smtpEnhanced6.1': ['Nachrichtenformat nicht unterst\u00fctzt', 'Ein Inhaltstyp oder eine Kodierung wird nicht unterst\u00fctzt.', 'Nutzen Sie unterst\u00fctzte MIME-Typen und Kodierungen oder genehmigte Dateilinks.'],
    'smtpEnhanced6.2': ['Erforderliche Konvertierung verboten', 'Die Zustellung ben\u00f6tigt eine durch Richtlinien verbotene Konvertierung.', 'Senden Sie in einem unterst\u00fctzten Format oder lassen Sie die betreffende Richtlinie pr\u00fcfen.'],
    'smtpEnhanced6.3': ['Erforderliche Konvertierung nicht verf\u00fcgbar', 'Ein Gateway kann die Nachricht nicht f\u00fcr den n\u00e4chsten Hop konvertieren.', 'Erzeugen Sie kompatibles MIME und pr\u00fcfen Sie die Gatewayf\u00e4higkeiten.'],
    'smtpEnhanced6.5': ['Nachrichtenkonvertierung fehlgeschlagen', 'Eine n\u00f6tige Inhaltskonvertierung konnte nicht abgeschlossen werden.', 'Pr\u00fcfen Sie Kodierung und Fehler des konvertierenden Gateways.'],
    'smtpEnhanced6.7': ['Internationalisierte Adresse nicht unterst\u00fctzt', 'Nicht-ASCII-Umschlagadressen sind auf dieser Strecke nicht zul\u00e4ssig.', 'Nutzen Sie SMTPUTF8 oder einen echten ASCII-Alias des Empf\u00e4ngers. Adresszeichen nicht einfach entfernen.'],
    'smtpEnhanced6.8': ['UTF-8-Antwort f\u00fcr diesen Client nicht verf\u00fcgbar', 'Der Server ben\u00f6tigt eine vom Client nicht ausgehandelte UTF-8-Antwort.', 'Nutzen Sie einen SMTPUTF8-f\u00e4higen Client und eine kompatible Route.'],
    'smtpEnhanced6.9': ['UTF-8-Nachricht erreicht nicht alle Empf\u00e4nger', 'Mindestens ein Empf\u00e4nger ist nicht \u00fcber eine SMTPUTF8-f\u00e4hige Route erreichbar.', 'Pr\u00fcfen Sie SMTPUTF8 entlang der gesamten Strecke und nutzen Sie best\u00e4tigte kompatible Aliase, falls vorhanden.'],
    'smtpEnhanced7.0': ['Unbestimmter Sicherheits- oder Richtlinienfehler', 'Eine Sicherheitsbeschr\u00e4nkung, Authentifizierung oder Filterrichtlinie verhindert die Aktion.', 'Lesen Sie die vollst\u00e4ndige Antwort und lassen Sie Authentifizierung und Richtlinienentscheidung pr\u00fcfen.'],
    'smtpEnhanced7.1': ['Zustellung durch Richtlinie eingeschr\u00e4nkt', 'M\u00f6glich sind Relayverbot, Empf\u00e4ngerbeschr\u00e4nkung, Filterung oder fehlende Authentifizierung. Tempor\u00e4re Antworten k\u00f6nnen Greylisting bedeuten.', 'Pr\u00fcfen Sie SMTP-Endpunkt, Anmeldung, Rechte und Reputation. Erfragen Sie die konkrete Regel, ohne Schutzma\u00dfnahmen pauschal abzuschalten.'],
    'smtpEnhanced7.2': ['Versand an Verteiler nicht erlaubt', 'Der Absender ist f\u00fcr diese Liste nicht berechtigt.', 'Bitten Sie den Listenbesitzer um Freigabe oder nutzen Sie eine autorisierte Adresse.'],
    'smtpEnhanced7.3': ['Sichere Nachrichtenkonvertierung nicht verf\u00fcgbar', 'Das Gateway kann eine erforderliche sichere Konvertierung nicht durchf\u00fchren.', 'Nutzen Sie ein gemeinsam unterst\u00fctztes sicheres Format und kontaktieren Sie den Administrator.'],
    'smtpEnhanced7.4': ['Sicherheitsfunktion nicht unterst\u00fctzt', 'Das Empfangssystem unterst\u00fctzt eine angeforderte Sicherheitsfunktion nicht.', 'Nutzen Sie ein unterst\u00fctztes Verfahren ohne die Transportsicherheit zu schw\u00e4chen.'],
    'smtpEnhanced7.5': ['Kryptografische Pr\u00fcfung fehlgeschlagen', 'Ein Schl\u00fcssel oder Zertifikat fehlt oder ist ung\u00fcltig. Anbieter k\u00f6nnen damit TLS- oder MTA-STS-Zertifikate meinen.', 'Pr\u00fcfen Sie G\u00fcltigkeit, Hostnamen, Vertrauenskette und relevante Nachrichten- oder Transportrichtlinien.'],
    'smtpEnhanced7.6': ['Kryptografischer Algorithmus nicht unterst\u00fctzt', 'Sender und Empf\u00e4nger unterst\u00fctzen keinen gemeinsamen erforderlichen Algorithmus.', 'Aktualisieren Sie Systeme und w\u00e4hlen Sie einen gemeinsam unterst\u00fctzten sicheren Algorithmus.'],
    'smtpEnhanced7.7': ['Nachrichtenintegrit\u00e4t verletzt', 'Der Inhalt wurde ge\u00e4ndert oder eine kryptografische Integrit\u00e4tspr\u00fcfung schlug fehl.', 'Ermitteln Sie \u00c4nderungen durch Gateways oder Weiterleitungen und pr\u00fcfen Sie Signaturen.'],
    'smtpEnhanced7.8': ['Anmeldedaten abgelehnt', 'AUTH verwendete ung\u00fcltige oder unzureichende Anmeldedaten.', 'Pr\u00fcfen Sie Konto, OAuth oder unterst\u00fctzte Anmeldung, Anwendungsrechte und Diensteinstellungen.'],
    'smtpEnhanced7.9': ['Authentifizierungsverfahren zu schwach', 'Der Mechanismus erf\u00fcllt die Empfangsrichtlinie nicht.', 'Nutzen Sie ein st\u00e4rkeres angek\u00fcndigtes Verfahren und lassen Sie TLS aktiviert.'],
    'smtpEnhanced7.10': ['Verschl\u00fcsselte Verbindung n\u00f6tig', 'Das Authentifizierungsverfahren verlangt eine st\u00e4rkere Datenschutzschicht.', 'Stellen Sie vor der Anmeldung TLS her oder nutzen Sie ein st\u00e4rkeres unterst\u00fctztes Verfahren.'],
    'smtpEnhanced7.11': ['Authentifizierung verlangt Verschl\u00fcsselung', 'Das Verfahren darf nicht auf einer unverschl\u00fcsselten Verbindung verwendet werden.', 'Konfigurieren Sie STARTTLS oder den dokumentierten TLS-Endpunkt vor der Anmeldung.'],
    'smtpEnhanced7.12': ['Kontoumstellung f\u00fcr Authentifizierung n\u00f6tig', 'Das Konto muss vor Nutzung des gew\u00e4hlten Mechanismus umgestellt werden.', 'Folgen Sie dem dokumentierten Umstellungsprozess des Anbieters \u00fcber eine sichere Verbindung.'],
    'smtpEnhanced7.13': ['Konto deaktiviert oder Empf\u00e4nger eingeschr\u00e4nkt', 'Standardbedeutung ist ein deaktiviertes Konto. Exchange Online nutzt den Code auch f\u00fcr \u00f6ffentliche Ordner nur f\u00fcr authentifizierte interne Absender.', 'Pr\u00fcfen Sie Anbieter und Antwort. Lassen Sie die Einschr\u00e4nkung durch Konto- oder Ordnerverantwortliche pr\u00fcfen.'],
    'smtpEnhanced7.20': ['Keine g\u00fcltige DKIM-Signatur', 'Der Empf\u00e4nger kann keine DKIM-Signatur der Nachricht validieren.', 'Aktivieren Sie DKIM beim tats\u00e4chlichen Versanddienst, ver\u00f6ffentlichen Sie richtige Selektoren und pr\u00fcfen Sie nachtr\u00e4gliche \u00c4nderungen.'],
    'smtpEnhanced7.21': ['Keine akzeptable DKIM-Signatur', 'Eine Signatur ist g\u00fcltig, erf\u00fcllt aber die Empfangsrichtlinie nicht.', 'Pr\u00fcfen Sie Signaturdom\u00e4ne, Algorithmus, Schl\u00fcsselst\u00e4rke und Empf\u00e4ngeranforderungen.'],
    'smtpEnhanced7.22': ['DKIM-Dom\u00e4ne stimmt nicht mit Autor \u00fcberein', 'Eine g\u00fcltige DKIM-Signatur passt nicht wie gefordert zur From-Dom\u00e4ne.', 'Konfigurieren Sie eine zur sichtbaren From-Adresse ausgerichtete Signaturdom\u00e4ne.'],
    'smtpEnhanced7.23': ['SPF-Pr\u00fcfung fehlgeschlagen', 'Die tats\u00e4chliche Versand-IP ist vom SPF der Umschlagdom\u00e4ne nicht autorisiert.', 'Pr\u00fcfen Sie MAIL FROM und Versanddienst. Ver\u00f6ffentlichen Sie einen g\u00fcltigen SPF mit dessen Freigabe innerhalb des DNS-Abfragelimits.'],
    'smtpEnhanced7.24': ['SPF-Auswertungsfehler', 'DNS-Fehler, mehrere SPF-Eintr\u00e4ge, Syntaxfehler oder zu viele Abfragen verhindern die Auswertung.', 'Beheben Sie DNS oder SPF, pr\u00fcfen Sie include und redirect und behalten Sie einen SPF mit h\u00f6chstens zehn DNS-abfragenden Termen.'],
    'smtpEnhanced7.25': ['Reverse-DNS-Pr\u00fcfung fehlgeschlagen', 'Der Versand-IP fehlt ein geeigneter PTR oder passende Vorw\u00e4rtsaufl\u00f6sung.', 'Der IP-Eigent\u00fcmer muss PTR und passende A/AAAA-Eintr\u00e4ge nach Anbieteranforderungen konfigurieren.'],
    'smtpEnhanced7.26': ['Nachrichtenauthentifizierung fehlgeschlagen', 'Mehrere Pr\u00fcfungen schlugen fehl, h\u00e4ufig SPF, DKIM oder DMARC. Der Code allein unterscheidet diese nicht.', 'Pr\u00fcfen Sie Authentication-Results und Empfangsantwort. Korrigieren Sie SPF und DKIM sowie From-Alignment f\u00fcr DMARC.'],
    'smtpEnhanced7.27': ['Absenderdom\u00e4ne ver\u00f6ffentlicht Null-MX', 'Die Absenderdom\u00e4ne nimmt keine R\u00fcckl\u00e4ufer an und wird deshalb abgelehnt.', 'Nutzen Sie eine verifizierte Umschlagdom\u00e4ne, die erforderliche R\u00fcckl\u00e4ufer empfangen kann.'],
    'smtpEnhanced7.28': ['Missbr\u00e4uchliche Nachrichtenflut vermutet', 'Der Empf\u00e4nger betrachtet den Verkehr als Teil einer Nachrichtenflut.', 'Stoppen Sie unerw\u00fcnschten Versand, pr\u00fcfen Sie Kontosicherheit, reduzieren Sie Volumen und folgen Sie dem Empf\u00e4ngerprozess.'],
    'smtpEnhanced7.29': ['ARC-Pr\u00fcfung fehlgeschlagen', 'Die authentifizierte Empfangskette konnte nicht validiert werden.', 'Pr\u00fcfen Sie ARC-Signaturen, Siegelreihenfolge und \u00c4nderungen durch Weiterleitungsgateways.'],
    'smtpEnhanced7.30': ['Erforderliches TLS nicht unterst\u00fctzt', 'Die Nachricht verlangt REQUIRETLS, der n\u00e4chste Hop unterst\u00fctzt es nicht.', 'Nutzen Sie eine durchgehend REQUIRETLS-f\u00e4hige Route und lassen Sie die Unvertr\u00e4glichkeit beheben.'],
    'smtpProvider4.4.316': ['Remoteverbindung verweigert', 'Exchange Online konnte den SMTP-Zieldienst nicht erreichen.', 'Lassen Sie Listener, Firewall, MX-Ziele und Dienstverf\u00fcgbarkeit pr\u00fcfen.'],
    'smtpProvider4.4.317': ['Remote-TLS-Zertifikat nicht vertrauensw\u00fcrdig', 'Exchange Online konnte die Zertifikatskette des Ziels nicht validieren.', 'Der Empf\u00e4nger muss ein g\u00fcltiges Zertifikat samt vollst\u00e4ndiger Vertrauenskette am SMTP-Endpunkt installieren.'],
    'smtpProvider5.2.121': ['Empf\u00e4ngerlimit f\u00fcr diesen Absender', 'Exchange Online begrenzt Nachrichten eines Absenders an einen bestimmten Empf\u00e4nger.', 'Reduzieren Sie Nachrichten an diesen Empf\u00e4nger und warten Sie auf freie Kapazit\u00e4t vor erneutem Versand.'],
    'smtpProvider5.2.122': ['Empfangsrate \u00fcberschritten', 'Der Exchange Online-Empf\u00e4nger hat seine gesamte Empfangsrate \u00fcberschritten.', 'Stimmen Sie sich mit dessen Administrator ab und reduzieren Sie automatischen Verkehr.'],
    'smtpProvider5.4.1': ['Empf\u00e4nger- oder Relayzugriff verweigert', 'Exchange Online erkennt m\u00f6glicherweise den Empf\u00e4nger nicht oder akzeptiert die Zieldom\u00e4ne nicht.', 'Pr\u00fcfen Sie Postfach, Aliase, Verzeichnissynchronisierung, akzeptierte Dom\u00e4nen und MX- oder Connectorrouting.'],
    'smtpProvider5.4.14': ['Routingschleife erkannt', 'Exchange Online hat zyklische Weiterleitungen oder Connectorrouten erkannt.', 'Verfolgen Sie Hops und korrigieren Sie Connectors, akzeptierte Dom\u00e4nen oder Weiterleitungen.'],
    'smtpProvider5.6.11': ['Ung\u00fcltige Zeilenenden', 'Die Nachricht enth\u00e4lt einzelne LF statt der erforderlichen CRLF-Zeilenenden.', 'Aktualisieren Sie die erzeugende Anwendung oder SMTP-Bibliothek f\u00fcr normgerechte Zeilenenden.'],
    'smtpProvider5.7.12': ['Empf\u00e4nger verlangt internen Absender', 'Der Exchange Online-Empf\u00e4nger lehnt externe oder nicht authentifizierte Absender ab.', 'Lassen Sie Zustellbeschr\u00e4nkungen pr\u00fcfen und den vorgesehenen Absender gegebenenfalls autorisieren.'],
    'smtpProvider5.7.57': ['Client f\u00fcr Einlieferung nicht authentifiziert', 'Eine Anwendung oder ein Ger\u00e4t hat sich bei Exchange Online nicht wie erforderlich angemeldet.', 'Pr\u00fcfen Sie Endpunkt, STARTTLS, Verfahren und SMTP AUTH-Richtlinien f\u00fcr Konto und Mandant. Kein anonymes Relay aktivieren.'],
    'smtpProvider5.7.64': ['Relayconnector erkennt Mandant nicht', 'Lokale Absender-IP oder Zertifikat passt nicht mehr zum eingehenden Exchange Online-Connector.', 'Lassen Sie zugelassene IPs, TLS-Zertifikatsidentit\u00e4t und akzeptierte Dom\u00e4nen pr\u00fcfen.'],
    'smtpProvider5.7.124': ['Absender f\u00fcr Gruppe nicht zugelassen', 'Der Absender fehlt in der Liste erlaubter Absender des Verteilers.', 'Bitten Sie den Gruppenbesitzer, den vorgesehenen Absender zu pr\u00fcfen und zu autorisieren.'],
    'smtpProvider5.7.133': ['Gruppe lehnt externe Absender ab', 'Die Gruppe nimmt nur authentifizierte interne Absender an.', 'Lassen Sie die Beschr\u00e4nkung durch den Gruppenbesitzer pr\u00fcfen.'],
    'smtpProvider5.7.134': ['Postfach lehnt externe Absender ab', 'Das Postfach ist auf authentifizierte interne Absender beschr\u00e4nkt.', 'Lassen Sie dessen Zustellbeschr\u00e4nkungen pr\u00fcfen.'],
    'smtpProvider5.7.509': ['DMARC-Ablehnungsrichtlinie angewendet', 'Die sichtbare From-Dom\u00e4ne besteht DMARC nicht und ver\u00f6ffentlicht eine Ablehnungsrichtlinie.', 'Korrigieren Sie ausgerichtetes SPF oder DKIM des echten Versanddienstes. Pr\u00fcfen Sie Weiterleitungen; DMARC nicht pauschal entfernen.'],
    'smtpProvider5.7.520': ['Automatische externe Weiterleitung gesperrt', 'Eine ausgehende Exchange Online-Richtlinie verbietet automatische externe Weiterleitung.', 'Pr\u00fcfen Sie Regel und Sicherheitsbedarf. Nutzen Sie genehmigte Ziele oder nur begr\u00fcndete eng begrenzte Ausnahmen.'],
    'smtpProvider5.7.705': ['Sendender Mandant eingeschr\u00e4nkt', 'Microsoft hat verd\u00e4chtigen ausgehenden Verkehr erkannt und den Mandanten eingeschr\u00e4nkt.', 'Stoppen Sie Missbrauch, untersuchen Sie kompromittierte Konten oder offene Relays, sichern Sie Konten und kontaktieren Sie Support.'],
    'smtpProvider5.7.708': ['Verkehr der Versand-IP abgelehnt', 'Microsoft hat Mandant oder ausgehenden Verkehr wegen verd\u00e4chtiger Aktivit\u00e4t eingeschr\u00e4nkt.', 'Beheben Sie unerw\u00fcnschten Versand und nutzen Sie den dokumentierten Microsoft-Supportprozess.'],
    'smtpProvider5.7.750': ['Versand aus unregistrierten Dom\u00e4nen gesperrt', 'Exchange Online erkennt verd\u00e4chtige Nutzung nicht im Mandanten bereitgestellter Dom\u00e4nen.', 'F\u00fcgen Sie legitime Dom\u00e4nen hinzu, verifizieren Sie diese und untersuchen Sie unbefugten Versand.']
  },
  'pt-BR': {
    smtpBasic211: ['Status do sistema', 'O servidor retornou informa\u00e7\u00f5es de status ou ajuda.', 'N\u00e3o h\u00e1 erro a corrigir. Continue a conversa SMTP.'],
    smtpBasic214: ['Resposta de ajuda', 'O servidor retornou ajuda para um comando.', 'Use a sintaxe de comandos informada pelo servidor.'],
    smtpBasic220: ['Servi\u00e7o pronto', 'O servi\u00e7o SMTP est\u00e1 pronto ou pode iniciar STARTTLS.', 'Continue com EHLO ou conclua TLS ap\u00f3s STARTTLS. Isto n\u00e3o \u00e9 um comprovante de entrega.'],
    smtpBasic221: ['Encerramento da conex\u00e3o', 'O servidor encerra a sess\u00e3o, geralmente ap\u00f3s QUIT.', 'Um encerramento normal n\u00e3o exige corre\u00e7\u00e3o. Consulte a resposta anterior para saber o resultado da mensagem.'],
    smtpBasic235: ['Autentica\u00e7\u00e3o bem-sucedida', 'O servidor aceitou a autentica\u00e7\u00e3o SMTP.', 'Continue o envio. A autentica\u00e7\u00e3o sozinha n\u00e3o comprova a entrega.'],
    smtpBasic250: ['A\u00e7\u00e3o solicitada aceita', 'O comando foi conclu\u00eddo. Ap\u00f3s DATA, o servidor assume a responsabilidade pela mensagem.', 'Confirme o resultado no rastreamento de mensagens. A aceita\u00e7\u00e3o n\u00e3o garante a chegada \u00e0 caixa de entrada.'],
    smtpBasic251: ['O destinat\u00e1rio ser\u00e1 encaminhado', 'O destinat\u00e1rio n\u00e3o \u00e9 local; o servidor encaminhar\u00e1 a mensagem.', 'Confirme o endere\u00e7o de encaminhamento com o destinat\u00e1rio antes de atualizar contatos.'],
    smtpBasic252: ['N\u00e3o \u00e9 poss\u00edvel verificar o destinat\u00e1rio', 'O servidor n\u00e3o verifica o endere\u00e7o, mas tentar\u00e1 entregar.', 'Isto n\u00e3o comprova que a caixa existe. Verifique o resultado final da entrega.'],
    smtpBasic334: ['Desafio de autentica\u00e7\u00e3o', 'O servidor precisa da pr\u00f3xima etapa do AUTH.', 'Deixe o cliente concluir o m\u00e9todo compat\u00edvel por uma conex\u00e3o segura.'],
    smtpBasic354: ['Pronto para receber os dados', 'O servidor aceitou DATA e aguarda o conte\u00fado.', 'Envie o conte\u00fado e aguarde a resposta final. A mensagem ainda n\u00e3o foi aceita.'],
    smtpBasic421: ['Servi\u00e7o temporariamente indispon\u00edvel', 'Manuten\u00e7\u00e3o, sobrecarga, limita\u00e7\u00e3o ou pol\u00edtica de conex\u00e3o causou o encerramento.', 'Verifique o servi\u00e7o e os limites. Permita tentativas com espera progressiva; evite reconex\u00f5es cont\u00ednuas.'],
    smtpBasic432: ['Transi\u00e7\u00e3o de autentica\u00e7\u00e3o necess\u00e1ria', 'SMTP AUTH exige migrar a conta para o mecanismo escolhido. Provedores podem usar o c\u00f3digo de outra forma.', 'Siga a migra\u00e7\u00e3o documentada. Confira o c\u00f3digo aprimorado para limites de envio espec\u00edficos do provedor.'],
    smtpBasic450: ['Caixa temporariamente indispon\u00edvel', 'A caixa pode estar ocupada, temporariamente desabilitada ou limitada por pol\u00edtica ou lista cinza.', 'Permita as tentativas programadas. Se persistir, pe\u00e7a ao administrador destinat\u00e1rio para verificar caixa e pol\u00edticas.'],
    smtpBasic451: ['Falha tempor\u00e1ria de processamento', 'Falhou o processamento local, diret\u00f3rio, DNS ou a avalia\u00e7\u00e3o de pol\u00edticas.', 'Consulte o c\u00f3digo aprimorado e a integridade do servi\u00e7o. O administrador respons\u00e1vel deve resolver falhas persistentes.'],
    smtpBasic452: ['Recursos insuficientes', 'Falta armazenamento ou foi atingido o limite de destinat\u00e1rios por transa\u00e7\u00e3o.', 'Conforme a resposta, libere armazenamento ou divida os destinat\u00e1rios em lotes menores.'],
    smtpBasic454: ['Falha tempor\u00e1ria de autentica\u00e7\u00e3o ou TLS', 'O servi\u00e7o de autentica\u00e7\u00e3o ou TLS est\u00e1 temporariamente indispon\u00edvel.', 'Verifique c\u00f3digo aprimorado, servi\u00e7o e TLS. Mantenha a criptografia ativada.'],
    smtpBasic455: ['Par\u00e2metros temporariamente incompat\u00edveis', 'Um par\u00e2metro MAIL FROM ou RCPT TO n\u00e3o pode ser aceito agora.', 'Use par\u00e2metros anunciados em EHLO e a pol\u00edtica de tentativas do servi\u00e7o de envio.'],
    smtpBasic500: ['Comando n\u00e3o reconhecido', 'O comando n\u00e3o \u00e9 compat\u00edvel, est\u00e1 malformado ou \u00e9 longo demais.', 'Verifique configura\u00e7\u00e3o do cliente, comprimento das linhas e recursos EHLO.'],
    smtpBasic501: ['Argumentos de comando inv\u00e1lidos', 'Um argumento, endere\u00e7o ou par\u00e2metro tem sintaxe inv\u00e1lida.', 'Corrija endere\u00e7os do envelope e par\u00e2metros. Use uma biblioteca SMTP com manuten\u00e7\u00e3o ativa.'],
    smtpBasic502: ['Comando n\u00e3o implementado', 'O servidor reconhece o comando, mas n\u00e3o o implementa.', 'Use comandos compat\u00edveis e confirme o ponto de conex\u00e3o SMTP correto.'],
    smtpBasic503: ['Comandos fora de sequ\u00eancia', 'Falta um comando anterior ou uma transa\u00e7\u00e3o j\u00e1 est\u00e1 aberta.', 'Verifique a sequ\u00eancia EHLO, autentica\u00e7\u00e3o, MAIL FROM, RCPT TO e DATA no cliente.'],
    smtpBasic504: ['Par\u00e2metro n\u00e3o compat\u00edvel', 'O servidor n\u00e3o aceita um par\u00e2metro ou mecanismo de autentica\u00e7\u00e3o solicitado.', 'Use os mecanismos e extens\u00f5es anunciados ap\u00f3s EHLO e STARTTLS.'],
    smtpBasic521: ['O host n\u00e3o aceita email', 'O host de destino informa explicitamente que n\u00e3o oferece servi\u00e7o SMTP.', 'Confirme o dom\u00ednio destinat\u00e1rio e a configura\u00e7\u00e3o MX com seu administrador.'],
    smtpBasic530: ['Autentica\u00e7\u00e3o ou STARTTLS obrigat\u00f3rio', 'O servidor exige autentica\u00e7\u00e3o ou conex\u00e3o segura antes do comando.', 'Consulte a resposta e configure STARTTLS e o m\u00e9todo compat\u00edvel. N\u00e3o desative TLS.'],
    smtpBasic534: ['Mecanismo de autentica\u00e7\u00e3o fraco', 'O m\u00e9todo selecionado n\u00e3o atende \u00e0 pol\u00edtica do servidor.', 'Use um m\u00e9todo compat\u00edvel mais forte e uma conex\u00e3o segura.'],
    smtpBasic535: ['Autentica\u00e7\u00e3o rejeitada', 'Credenciais, autoriza\u00e7\u00e3o ou fluxo de autentica\u00e7\u00e3o foram rejeitados.', 'Verifique conta, permiss\u00f5es do aplicativo e m\u00e9todo compat\u00edvel. Nunca cole senhas ou tokens aqui.'],
    smtpBasic538: ['Autentica\u00e7\u00e3o requer criptografia', 'O mecanismo exige uma conex\u00e3o criptografada.', 'Configure STARTTLS ou o ponto TLS documentado antes da autentica\u00e7\u00e3o.'],
    smtpBasic550: ['Caixa indispon\u00edvel ou a\u00e7\u00e3o rejeitada', 'O endere\u00e7o pode n\u00e3o existir, o acesso pode ser negado ou uma pol\u00edtica de destinat\u00e1rio ou retransmiss\u00e3o pode rejeitar a solicita\u00e7\u00e3o.', 'Use o c\u00f3digo aprimorado e a resposta original para distinguir endere\u00e7o, pol\u00edtica e autentica\u00e7\u00e3o.'],
    smtpBasic551: ['Destinat\u00e1rio n\u00e3o \u00e9 local', 'O servidor recusou a entrega e pode ter indicado um endere\u00e7o de encaminhamento.', 'Confirme o novo endere\u00e7o com o destinat\u00e1rio e corrija contatos ou roteamento.'],
    smtpBasic552: ['Limite de armazenamento ou mensagem excedido', 'A cota da caixa ou o tamanho da mensagem foi excedido. Servidores antigos tamb\u00e9m usam este c\u00f3digo para muitos destinat\u00e1rios.', 'Libere espa\u00e7o ou reduza a mensagem. Apenas se o texto indicar muitos destinat\u00e1rios, divida o lote e repita esses destinat\u00e1rios.'],
    smtpBasic553: ['Nome de caixa n\u00e3o permitido', 'Um endere\u00e7o do envelope \u00e9 inv\u00e1lido ou n\u00e3o permitido.', 'Confira remetente, destinat\u00e1rio, identidades autorizadas e c\u00f3digo aprimorado.'],
    smtpBasic554: ['Transa\u00e7\u00e3o rejeitada', 'A mensagem ou conex\u00e3o foi rejeitada; o c\u00f3digo geral sozinho n\u00e3o define a causa.', 'Consulte o c\u00f3digo aprimorado e a explica\u00e7\u00e3o sobre conte\u00fado, pol\u00edtica, autentica\u00e7\u00e3o ou roteamento.'],
    smtpBasic555: ['Par\u00e2metros de envelope incompat\u00edveis', 'Um par\u00e2metro MAIL FROM ou RCPT TO n\u00e3o \u00e9 reconhecido ou implementado.', 'Remova par\u00e2metros incompat\u00edveis e use apenas extens\u00f5es anunciadas em EHLO.'],
    smtpBasic556: ['Dom\u00ednio destinat\u00e1rio n\u00e3o aceita email', 'O dom\u00ednio recusa email explicitamente, normalmente por um registro MX nulo.', 'Use outro endere\u00e7o confirmado. N\u00e3o substitua um MX nulo intencional sem autoriza\u00e7\u00e3o do propriet\u00e1rio.'],
    'smtpEnhanced0.0': ['Sem detalhes adicionais de status', 'O servidor informou apenas um resultado geral.', 'Consulte a resposta completa e o rastreamento de mensagens.'],
    'smtpEnhanced1.0': ['Falha relacionada a endere\u00e7o', 'O endere\u00e7o do remetente ou destinat\u00e1rio n\u00e3o p\u00f4de ser usado; faltam detalhes.', 'Verifique os dois endere\u00e7os do envelope e o diret\u00f3rio destinat\u00e1rio.'],
    'smtpEnhanced1.1': ['Caixa do destinat\u00e1rio n\u00e3o encontrada', 'A caixa ou alias n\u00e3o existe, foi removido ou foi digitado incorretamente.', 'Confirme o endere\u00e7o, corrija a digita\u00e7\u00e3o e remova sugest\u00f5es antigas. Pe\u00e7a ao administrador destinat\u00e1rio para verificar aliases.'],
    'smtpEnhanced1.2': ['Dom\u00ednio destinat\u00e1rio inv\u00e1lido para email', 'O dom\u00ednio de destino n\u00e3o existe ou n\u00e3o pode receber email.', 'Corrija o nome e pe\u00e7a ao propriet\u00e1rio para verificar registro, MX e servi\u00e7o de email.'],
    'smtpEnhanced1.3': ['Sintaxe de destinat\u00e1rio inv\u00e1lida', 'O endere\u00e7o do destinat\u00e1rio est\u00e1 malformado.', 'Corrija parte local, separador @ e dom\u00ednio no endere\u00e7o do envelope.'],
    'smtpEnhanced1.4': ['Endere\u00e7o de destinat\u00e1rio amb\u00edguo', 'O diret\u00f3rio associa o endere\u00e7o a v\u00e1rios destinat\u00e1rios.', 'Pe\u00e7a ao administrador para corrigir aliases ou entradas conflitantes.'],
    'smtpEnhanced1.5': ['Endere\u00e7o de destinat\u00e1rio aceito', 'O sistema receptor aceitou o endere\u00e7o informado.', 'N\u00e3o h\u00e1 corre\u00e7\u00e3o de endere\u00e7o indicada. Esta etapa n\u00e3o comprova a entrega final na caixa de entrada.'],
    'smtpEnhanced1.6': ['Destinat\u00e1rio mudou sem encaminhamento', 'A caixa antiga n\u00e3o recebe mais e n\u00e3o possui encaminhamento.', 'Obtenha o endere\u00e7o atual do destinat\u00e1rio e atualize os contatos.'],
    'smtpEnhanced1.7': ['Sintaxe de remetente inv\u00e1lida', 'O endere\u00e7o do remetente do envelope est\u00e1 malformado.', 'Corrija MAIL FROM e a configura\u00e7\u00e3o do remetente no aplicativo.'],
    'smtpEnhanced1.8': ['Dom\u00ednio remetente n\u00e3o recebe devolu\u00e7\u00f5es', 'O dom\u00ednio \u00e9 inv\u00e1lido para devolu\u00e7\u00f5es. Exchange Online tamb\u00e9m usa 5.1.8 para remetente de sa\u00edda bloqueado.', 'Verifique dom\u00ednio e DNS. Para bloqueio do Exchange, investigue comprometimento da conta e siga a recupera\u00e7\u00e3o de entidades restritas.'],
    'smtpEnhanced1.10': ['Dom\u00ednio destinat\u00e1rio publica MX nulo', 'O padr\u00e3o significa recusa expl\u00edcita de email. Exchange Online tamb\u00e9m usa 5.1.10 para destinat\u00e1rio ausente no diret\u00f3rio.', 'Verifique provedor e resposta. Para MX nulo use outro destinat\u00e1rio; no Exchange confira caixa e aliases.'],
    'smtpEnhanced2.0': ['Falha relacionada \u00e0 caixa', 'Uma condi\u00e7\u00e3o da caixa impediu a entrega sem outros detalhes.', 'Pe\u00e7a ao administrador para verificar estado, cota e restri\u00e7\u00f5es de entrega.'],
    'smtpEnhanced2.1': ['Caixa desabilitada', 'A caixa existe, mas n\u00e3o aceita mensagens.', 'Verifique estado da conta, licen\u00e7a e disponibilidade com o administrador.'],
    'smtpEnhanced2.2': ['Caixa cheia ou cota excedida', 'A caixa atingiu sua cota. No Exchange Online, a resposta pode indicar uma cota de envio do remetente.', 'Se a caixa estiver cheia, libere espa\u00e7o ou ajuste a cota. Para envio, reduza o tr\u00e1fego e confira limites e seguran\u00e7a da conta.'],
    'smtpEnhanced2.3': ['Limite de tamanho da caixa excedido', 'A mensagem excede o tamanho permitido para essa caixa.', 'Reduza mensagem e anexos considerando a codifica\u00e7\u00e3o MIME, ou use um link de arquivos aprovado.'],
    'smtpEnhanced2.4': ['Falha na expans\u00e3o da lista', 'O grupo ou lista n\u00e3o p\u00f4de ser expandido em destinat\u00e1rios.', 'Pe\u00e7a ao propriet\u00e1rio para corrigir membros, diret\u00f3rio e servi\u00e7o de grupos.'],
    'smtpEnhanced3.0': ['Falha do sistema de email', 'O destino informou um problema geral do sistema.', 'Pe\u00e7a ao administrador receptor para verificar servi\u00e7o, filas e diagn\u00f3sticos.'],
    'smtpEnhanced3.1': ['Armazenamento do sistema esgotado', 'O armazenamento compartilhado do servidor acabou, n\u00e3o apenas a cota de uma caixa.', 'O administrador receptor deve restaurar a capacidade. Permita tentativas com espera progressiva.'],
    'smtpEnhanced3.2': ['Sistema n\u00e3o aceita mensagens', 'O sistema est\u00e1 em manuten\u00e7\u00e3o, encerramento, sobrecarga ou recusando email.', 'Verifique servi\u00e7o e limites de conex\u00e3o. Uma resposta permanente exige corre\u00e7\u00e3o antes de novo envio.'],
    'smtpEnhanced3.3': ['Recurso de email necess\u00e1rio indispon\u00edvel', 'O destino ou gateway n\u00e3o oferece um recurso solicitado.', 'Use recursos compat\u00edveis ou pe\u00e7a para corrigir a configura\u00e7\u00e3o do gateway.'],
    'smtpEnhanced3.4': ['Limite de tamanho do sistema excedido', 'A mensagem supera o tamanho m\u00e1ximo do servidor receptor.', 'Reduza o tamanho codificado ou use um link aprovado. Verifique limites em toda a rota.'],
    'smtpEnhanced3.5': ['Sistema de email mal configurado', 'Um sistema receptor ou intermedi\u00e1rio tem configura\u00e7\u00e3o incorreta.', 'Pe\u00e7a para verificar dom\u00ednios aceitos, conectores, roteamento e configura\u00e7\u00e3o do servi\u00e7o.'],
    'smtpEnhanced4.0': ['Falha de rede ou roteamento', 'Foi informado um problema de conex\u00e3o ou rota sem detalhes.', 'Verifique MX, endere\u00e7os, conectividade e roteamento de email.'],
    'smtpEnhanced4.1': ['Host de destino n\u00e3o respondeu', 'O destino pode estar offline, sobrecarregado ou bloqueado por firewall.', 'Verifique listener SMTP, destinos MX e regras de firewall com o administrador receptor.'],
    'smtpEnhanced4.2': ['Conex\u00e3o interrompida durante a entrega', 'A conex\u00e3o foi estabelecida, mas caiu ou expirou antes de concluir a transa\u00e7\u00e3o.', 'Confira estabilidade da rede, tempos limite SMTP, falhas TLS e servi\u00e7o receptor.'],
    'smtpEnhanced4.3': ['Diret\u00f3rio ou DNS indispon\u00edvel', 'Uma consulta DNS ou de diret\u00f3rio necess\u00e1ria ao roteamento falhou.', 'Verifique DNS autoritativo, resolvedores, DNSSEC e disponibilidade do diret\u00f3rio.'],
    'smtpEnhanced4.4': ['Nenhuma rota de email utiliz\u00e1vel', 'O pr\u00f3ximo servidor n\u00e3o p\u00f4de ser determinado ou a rota configurada \u00e9 inv\u00e1lida.', 'Confira MX, A/AAAA, dom\u00ednios aceitos e rotas de conectores ou hosts inteligentes.'],
    'smtpEnhanced4.5': ['Sistema de email congestionado', 'As filas ou a capacidade de entrega est\u00e3o sobrecarregadas.', 'Reduza simultaneidade e taxa de envio e deixe as filas esvaziarem.'],
    'smtpEnhanced4.6': ['Loop de roteamento de email', 'Encaminhamentos ou conectores repetem a passagem pelos mesmos sistemas.', 'Rastreie os saltos e remova encaminhamento circular ou rota incorreta.'],
    'smtpEnhanced4.7': ['Prazo de entrega expirado', 'A mensagem ficou sem entrega at\u00e9 expirar o tempo de perman\u00eancia na fila.', 'Corrija a causa dos erros anteriores. Uma mensagem expirada n\u00e3o recebe mais tentativas autom\u00e1ticas e pode exigir novo envio.'],
    'smtpEnhanced5.0': ['Falha de protocolo de email', 'O di\u00e1logo SMTP falhou sem detalhe mais espec\u00edfico.', 'Confira a sequ\u00eancia SMTP do cliente e a explica\u00e7\u00e3o do receptor.'],
    'smtpEnhanced5.1': ['Comando inv\u00e1lido ou fora de ordem', 'Um comando n\u00e3o \u00e9 compat\u00edvel ou foi enviado no estado SMTP errado.', 'Verifique a sequ\u00eancia e os recursos anunciados pelo servidor.'],
    'smtpEnhanced5.2': ['Erro de sintaxe SMTP', 'O receptor n\u00e3o conseguiu interpretar um comando.', 'Corrija a formata\u00e7\u00e3o e atualize a biblioteca SMTP.'],
    'smtpEnhanced5.3': ['Destinat\u00e1rios em excesso', 'A transa\u00e7\u00e3o excede o limite de destinat\u00e1rios do servi\u00e7o receptor.', 'Divida a lista conforme os limites publicados. N\u00e3o reenvie para destinat\u00e1rios j\u00e1 aceitos.'],
    'smtpEnhanced5.4': ['Argumentos SMTP inv\u00e1lidos', 'Um comando reconhecido cont\u00e9m argumentos inv\u00e1lidos ou incompat\u00edveis.', 'Corrija endere\u00e7os do envelope e use apenas extens\u00f5es negociadas.'],
    'smtpEnhanced5.5': ['Vers\u00f5es de protocolo incompat\u00edveis', 'Os sistemas n\u00e3o concordam com os recursos de protocolo necess\u00e1rios.', 'Atualize o cliente ou gateway e verifique a compatibilidade.'],
    'smtpEnhanced6.0': ['Problema de conte\u00fado ou codifica\u00e7\u00e3o', 'A representa\u00e7\u00e3o do conte\u00fado impede o processamento.', 'Valide cabe\u00e7alhos MIME, codifica\u00e7\u00f5es e anexos conforme o diagn\u00f3stico original.'],
    'smtpEnhanced6.1': ['Tipo de conte\u00fado incompat\u00edvel', 'Um tipo de conte\u00fado ou codifica\u00e7\u00e3o n\u00e3o \u00e9 aceito pelo receptor.', 'Use tipos MIME e codifica\u00e7\u00f5es compat\u00edveis ou um link de arquivos aprovado.'],
    'smtpEnhanced6.2': ['Convers\u00e3o necess\u00e1ria proibida', 'A entrega exige uma convers\u00e3o n\u00e3o permitida pela pol\u00edtica.', 'Envie em formato compat\u00edvel ou pe\u00e7a ao administrador para revisar a pol\u00edtica aplic\u00e1vel.'],
    'smtpEnhanced6.3': ['Convers\u00e3o necess\u00e1ria indispon\u00edvel', 'Um gateway n\u00e3o consegue converter a mensagem para o pr\u00f3ximo salto.', 'Gere MIME compat\u00edvel e confira os recursos de codifica\u00e7\u00e3o do gateway.'],
    'smtpEnhanced6.5': ['Convers\u00e3o da mensagem falhou', 'Uma convers\u00e3o de conte\u00fado necess\u00e1ria n\u00e3o p\u00f4de ser conclu\u00edda.', 'Verifique a codifica\u00e7\u00e3o e os erros no gateway de convers\u00e3o.'],
    'smtpEnhanced6.7': ['Endere\u00e7o internacionalizado incompat\u00edvel', 'A rota n\u00e3o permite endere\u00e7os do envelope com caracteres n\u00e3o ASCII.', 'Use SMTPUTF8 ou um alias ASCII real fornecido pelo destinat\u00e1rio. N\u00e3o remova caracteres do endere\u00e7o.'],
    'smtpEnhanced6.8': ['Resposta UTF-8 indispon\u00edvel para este cliente', 'O servidor precisa responder em UTF-8, mas o cliente n\u00e3o negociou esse recurso.', 'Use cliente SMTPUTF8 e rota compat\u00edvel.'],
    'smtpEnhanced6.9': ['Mensagem UTF-8 n\u00e3o alcan\u00e7a todos os destinat\u00e1rios', 'Um ou mais destinat\u00e1rios n\u00e3o t\u00eam uma rota compat\u00edvel com SMTPUTF8.', 'Confira SMTPUTF8 em toda a rota e use aliases compat\u00edveis confirmados, quando dispon\u00edveis.'],
    'smtpEnhanced7.0': ['Falha de seguran\u00e7a ou pol\u00edtica n\u00e3o especificada', 'Uma restri\u00e7\u00e3o, autentica\u00e7\u00e3o ou filtragem impediu a a\u00e7\u00e3o.', 'Leia a resposta completa e pe\u00e7a para verificar autentica\u00e7\u00e3o e decis\u00f5es de pol\u00edtica.'],
    'smtpEnhanced7.1': ['Entrega restrita por pol\u00edtica', 'Pode ser retransmiss\u00e3o negada, restri\u00e7\u00f5es, filtros ou falta de autentica\u00e7\u00e3o. Respostas tempor\u00e1rias tamb\u00e9m podem indicar lista cinza.', 'Verifique ponto SMTP, autentica\u00e7\u00e3o, permiss\u00f5es e reputa\u00e7\u00e3o. Consulte a pol\u00edtica espec\u00edfica sem desativar prote\u00e7\u00f5es de modo geral.'],
    'smtpEnhanced7.2': ['Envio para a lista n\u00e3o permitido', 'O remetente n\u00e3o est\u00e1 autorizado a usar essa lista.', 'Pe\u00e7a aprova\u00e7\u00e3o ao propriet\u00e1rio ou use um endere\u00e7o autorizado.'],
    'smtpEnhanced7.3': ['Convers\u00e3o de mensagem segura indispon\u00edvel', 'O gateway n\u00e3o consegue realizar uma convers\u00e3o segura necess\u00e1ria.', 'Use um formato seguro compat\u00edvel com ambos os sistemas e consulte o administrador.'],
    'smtpEnhanced7.4': ['Recurso de seguran\u00e7a incompat\u00edvel', 'O receptor n\u00e3o oferece um recurso de seguran\u00e7a solicitado.', 'Use um m\u00e9todo compat\u00edvel sem enfraquecer a seguran\u00e7a do transporte.'],
    'smtpEnhanced7.5': ['Valida\u00e7\u00e3o criptogr\u00e1fica falhou', 'Uma chave ou certificado est\u00e1 ausente ou inv\u00e1lido. Provedores podem usar isso para certificados TLS ou MTA-STS.', 'Verifique validade, nomes de host, cadeia de confian\u00e7a e pol\u00edtica de seguran\u00e7a pertinente.'],
    'smtpEnhanced7.6': ['Algoritmo criptogr\u00e1fico incompat\u00edvel', 'Remetente e receptor n\u00e3o compartilham um algoritmo necess\u00e1rio.', 'Atualize os sistemas e selecione um algoritmo seguro compat\u00edvel com ambos.'],
    'smtpEnhanced7.7': ['Verifica\u00e7\u00e3o de integridade falhou', 'O conte\u00fado mudou ou uma verifica\u00e7\u00e3o criptogr\u00e1fica falhou.', 'Identifique altera\u00e7\u00f5es em gateways ou encaminhamentos e valide as assinaturas.'],
    'smtpEnhanced7.8': ['Credenciais de autentica\u00e7\u00e3o rejeitadas', 'AUTH usou credenciais inv\u00e1lidas ou insuficientes.', 'Confira conta, OAuth ou m\u00e9todo compat\u00edvel, permiss\u00f5es do aplicativo e configura\u00e7\u00e3o do servi\u00e7o.'],
    'smtpEnhanced7.9': ['M\u00e9todo de autentica\u00e7\u00e3o fraco', 'O mecanismo selecionado n\u00e3o atende \u00e0 pol\u00edtica receptora.', 'Use um m\u00e9todo mais forte anunciado pelo servidor e mantenha TLS ativado.'],
    'smtpEnhanced7.10': ['Conex\u00e3o criptografada necess\u00e1ria', 'O mecanismo exige uma camada de privacidade mais forte.', 'Estabele\u00e7a TLS antes de autenticar ou use um mecanismo compat\u00edvel mais forte.'],
    'smtpEnhanced7.11': ['Autentica\u00e7\u00e3o exige criptografia', 'O m\u00e9todo n\u00e3o pode ser usado em conex\u00e3o sem criptografia.', 'Configure STARTTLS ou o ponto TLS documentado antes da autentica\u00e7\u00e3o.'],
    'smtpEnhanced7.12': ['Transi\u00e7\u00e3o de autentica\u00e7\u00e3o exigida', 'A conta precisa de uma transi\u00e7\u00e3o antes de usar o mecanismo selecionado.', 'Siga o procedimento documentado do provedor por uma conex\u00e3o segura.'],
    'smtpEnhanced7.13': ['Conta desabilitada ou destinat\u00e1rio restrito', 'O padr\u00e3o indica conta desabilitada. Exchange Online tamb\u00e9m usa o c\u00f3digo para pasta p\u00fablica limitada a remetentes internos autenticados.', 'Confira provedor e resposta completa. Consulte a restri\u00e7\u00e3o com o administrador da conta ou propriet\u00e1rio da pasta.'],
    'smtpEnhanced7.20': ['Nenhuma assinatura DKIM v\u00e1lida', 'O receptor n\u00e3o consegue validar nenhuma assinatura DKIM da mensagem.', 'Ative DKIM no servi\u00e7o real de envio, publique os seletores corretos e confira altera\u00e7\u00f5es ap\u00f3s a assinatura.'],
    'smtpEnhanced7.21': ['Nenhuma assinatura DKIM aceit\u00e1vel', 'Uma assinatura \u00e9 v\u00e1lida, mas n\u00e3o atende \u00e0 pol\u00edtica receptora.', 'Confira dom\u00ednio de assinatura, algoritmo, for\u00e7a da chave e requisitos do receptor.'],
    'smtpEnhanced7.22': ['Dom\u00ednio DKIM n\u00e3o corresponde ao autor', 'Uma assinatura v\u00e1lida n\u00e3o corresponde ao dom\u00ednio From exigido.', 'Configure uma assinatura de dom\u00ednio alinhada com o From vis\u00edvel.'],
    'smtpEnhanced7.23': ['Valida\u00e7\u00e3o SPF falhou', 'O IP real de envio n\u00e3o est\u00e1 autorizado pelo SPF do dom\u00ednio do envelope.', 'Confira MAIL FROM e o servi\u00e7o emissor. Publique um \u00fanico SPF v\u00e1lido que o autorize dentro do limite de consultas DNS.'],
    'smtpEnhanced7.24': ['Erro de avalia\u00e7\u00e3o SPF', 'Falhas DNS, v\u00e1rios registros SPF, termos malformados ou consultas excessivas impedem a avalia\u00e7\u00e3o.', 'Corrija DNS ou SPF, revise include e redirect e mantenha um SPF com no m\u00e1ximo dez termos que consultam DNS.'],
    'smtpEnhanced7.25': ['Valida\u00e7\u00e3o DNS reversa falhou', 'O IP de envio n\u00e3o possui PTR aceit\u00e1vel ou DNS direto correspondente.', 'Pe\u00e7a ao propriet\u00e1rio do IP para configurar PTR e A/AAAA correspondentes conforme o provedor.'],
    'smtpEnhanced7.26': ['Verifica\u00e7\u00f5es de autentica\u00e7\u00e3o falharam', 'V\u00e1rias verifica\u00e7\u00f5es falharam, geralmente SPF, DKIM ou DMARC. O c\u00f3digo sozinho n\u00e3o identifica qual delas.', 'Confira Authentication-Results e a resposta receptora. Corrija SPF e DKIM e o alinhamento com From para DMARC.'],
    'smtpEnhanced7.27': ['Dom\u00ednio remetente publica MX nulo', 'O dom\u00ednio n\u00e3o recebe devolu\u00e7\u00f5es e o receptor rejeita esse tipo de remetente.', 'Use um dom\u00ednio de envelope verificado que possa receber as devolu\u00e7\u00f5es necess\u00e1rias.'],
    'smtpEnhanced7.28': ['Suspeita de fluxo abusivo de mensagens', 'O receptor considera esse tr\u00e1fego uma inunda\u00e7\u00e3o de mensagens.', 'Interrompa envios n\u00e3o intencionais, investigue seguran\u00e7a, reduza o volume e siga o processo de recupera\u00e7\u00e3o do receptor.'],
    'smtpEnhanced7.29': ['Valida\u00e7\u00e3o ARC falhou', 'A cadeia de recebimento autenticada n\u00e3o p\u00f4de ser validada.', 'Confira assinaturas ARC, ordem dos selos e altera\u00e7\u00f5es nos gateways de encaminhamento.'],
    'smtpEnhanced7.30': ['Suporte TLS exigido indispon\u00edvel', 'A mensagem exige REQUIRETLS, mas o pr\u00f3ximo salto n\u00e3o oferece suporte.', 'Use uma rota com REQUIRETLS em todos os saltos e pe\u00e7a para resolver a incompatibilidade.'],
    'smtpProvider4.4.316': ['Conex\u00e3o remota recusada', 'Exchange Online n\u00e3o conseguiu conectar ao SMTP de destino.', 'Pe\u00e7a para conferir listener, firewall, destinos MX e disponibilidade do servi\u00e7o.'],
    'smtpProvider4.4.317': ['Certificado TLS remoto n\u00e3o confi\u00e1vel', 'Exchange Online n\u00e3o conseguiu validar a cadeia do certificado de destino.', 'Pe\u00e7a ao receptor para instalar certificado v\u00e1lido e cadeia de confian\u00e7a completa no SMTP.'],
    'smtpProvider5.2.121': ['Limite deste remetente para o destinat\u00e1rio', 'Exchange Online limitou mensagens de um remetente para um destinat\u00e1rio espec\u00edfico.', 'Reduza os envios a esse destinat\u00e1rio e aguarde recuperar capacidade antes de uma nova mensagem.'],
    'smtpProvider5.2.122': ['Taxa de recebimento excedida', 'O destinat\u00e1rio Exchange Online ultrapassou sua taxa total de recebimento.', 'Coordene com seu administrador e reduza tr\u00e1fego automatizado antes de novo envio.'],
    'smtpProvider5.4.1': ['Acesso de destinat\u00e1rio ou retransmiss\u00e3o negado', 'Exchange Online pode n\u00e3o reconhecer o destinat\u00e1rio ou n\u00e3o aceitar email para o dom\u00ednio.', 'Verifique caixa, aliases, sincroniza\u00e7\u00e3o do diret\u00f3rio, dom\u00ednios aceitos e rotas MX ou de conectores.'],
    'smtpProvider5.4.14': ['Loop de roteamento detectado', 'Exchange Online detectou encaminhamento ou conectores circulares.', 'Rastreie saltos e corrija conectores, dom\u00ednios aceitos ou encaminhamentos que causam o loop.'],
    'smtpProvider5.6.11': ['Finais de linha inv\u00e1lidos', 'A mensagem cont\u00e9m LF isolado em vez do CRLF obrigat\u00f3rio.', 'Atualize o aplicativo gerador ou biblioteca SMTP para produzir finais de linha compat\u00edveis.'],
    'smtpProvider5.7.12': ['Destinat\u00e1rio exige remetente interno', 'O destinat\u00e1rio Exchange Online rejeita remetentes externos ou n\u00e3o autenticados.', 'Pe\u00e7a para revisar restri\u00e7\u00f5es de entrega e autorizar o remetente pretendido quando apropriado.'],
    'smtpProvider5.7.57': ['Cliente n\u00e3o autenticado para envio', 'Um aplicativo ou dispositivo n\u00e3o se autenticou conforme exigido pelo Exchange Online.', 'Confira ponto de envio, STARTTLS, m\u00e9todo e pol\u00edticas SMTP AUTH da conta e locat\u00e1rio. N\u00e3o habilite retransmiss\u00e3o an\u00f4nima.'],
    'smtpProvider5.7.64': ['Conector n\u00e3o identificou o locat\u00e1rio', 'O IP ou certificado local n\u00e3o corresponde mais ao conector de entrada do Exchange Online.', 'Confira IPs autorizados, identidade do certificado TLS e dom\u00ednios aceitos no conector.'],
    'smtpProvider5.7.124': ['Remetente n\u00e3o permitido no grupo', 'O remetente n\u00e3o est\u00e1 na lista autorizada do grupo de distribui\u00e7\u00e3o.', 'Pe\u00e7a ao propriet\u00e1rio para revisar e autorizar o remetente pretendido.'],
    'smtpProvider5.7.133': ['Grupo rejeita remetentes externos', 'O grupo s\u00f3 aceita remetentes internos autenticados.', 'Pe\u00e7a ao propriet\u00e1rio para revisar a restri\u00e7\u00e3o a remetentes externos.'],
    'smtpProvider5.7.134': ['Caixa rejeita remetentes externos', 'A caixa \u00e9 restrita a remetentes internos autenticados.', 'Pe\u00e7a ao administrador destinat\u00e1rio para revisar as restri\u00e7\u00f5es de entrega.'],
    'smtpProvider5.7.509': ['Pol\u00edtica de rejei\u00e7\u00e3o DMARC aplicada', 'O dom\u00ednio From vis\u00edvel falhou em DMARC e publica uma pol\u00edtica de rejei\u00e7\u00e3o.', 'Corrija SPF ou DKIM alinhados do servi\u00e7o real. Investigue encaminhamentos e n\u00e3o remova DMARC como solu\u00e7\u00e3o geral.'],
    'smtpProvider5.7.520': ['Encaminhamento externo autom\u00e1tico bloqueado', 'Uma pol\u00edtica de sa\u00edda do Exchange Online n\u00e3o permite encaminhamento externo autom\u00e1tico.', 'Revise regra e requisitos de seguran\u00e7a. Use destino aprovado ou exce\u00e7\u00e3o restrita somente quando justificada.'],
    'smtpProvider5.7.705': ['Locat\u00e1rio remetente restrito', 'Microsoft detectou tr\u00e1fego de sa\u00edda suspeito e restringiu o locat\u00e1rio.', 'Pare abusos, investigue contas comprometidas ou retransmissores abertos, proteja contas e contate o suporte.'],
    'smtpProvider5.7.708': ['Tr\u00e1fego do IP de envio rejeitado', 'Microsoft restringiu o locat\u00e1rio ou tr\u00e1fego de sa\u00edda devido a atividade suspeita.', 'Investigue e corrija envios indesejados e siga o processo de suporte da Microsoft.'],
    'smtpProvider5.7.750': ['Envio por dom\u00ednios n\u00e3o registrados bloqueado', 'Exchange Online detectou uso suspeito de dom\u00ednios n\u00e3o provisionados no locat\u00e1rio.', 'Adicione e verifique dom\u00ednios leg\u00edtimos e investigue envios n\u00e3o autorizados.']
  },
  'zh-CN': {
    smtpBasic211: ['\u7cfb\u7edf\u72b6\u6001', '\u670d\u52a1\u5668\u8fd4\u56de\u4e86\u72b6\u6001\u6216\u5e2e\u52a9\u4fe1\u606f\u3002', '\u65e0\u9700\u4fee\u590d\u9519\u8bef\u3002\u7ee7\u7eed SMTP \u4f1a\u8bdd\u3002'],
    smtpBasic214: ['\u5e2e\u52a9\u54cd\u5e94', '\u670d\u52a1\u5668\u8fd4\u56de\u4e86\u547d\u4ee4\u5e2e\u52a9\u3002', '\u6309\u7167\u670d\u52a1\u5668\u516c\u5e03\u7684\u547d\u4ee4\u8bed\u6cd5\u64cd\u4f5c\u3002'],
    smtpBasic220: ['\u670d\u52a1\u5c31\u7eea', 'SMTP \u670d\u52a1\u5df2\u5c31\u7eea\uff0c\u6216 STARTTLS \u53ef\u4ee5\u5f00\u59cb\u3002', '\u7ee7\u7eed\u53d1\u9001 EHLO\uff0c\u6216\u5728 STARTTLS \u540e\u5b8c\u6210 TLS \u63e1\u624b\u3002\u8fd9\u4e0d\u662f\u6295\u9012\u56de\u6267\u3002'],
    smtpBasic221: ['\u8fde\u63a5\u6b63\u5728\u5173\u95ed', '\u670d\u52a1\u5668\u6b63\u5728\u7ed3\u675f\u4f1a\u8bdd\uff0c\u901a\u5e38\u53d1\u751f\u5728 QUIT \u4e4b\u540e\u3002', '\u6b63\u5e38\u5173\u95ed\u65e0\u9700\u5904\u7406\u3002\u67e5\u770b\u4e0a\u4e00\u6761\u54cd\u5e94\u4ee5\u786e\u5b9a\u90ae\u4ef6\u7ed3\u679c\u3002'],
    smtpBasic235: ['\u8eab\u4efd\u9a8c\u8bc1\u6210\u529f', '\u670d\u52a1\u5668\u63a5\u53d7\u4e86 SMTP \u8eab\u4efd\u9a8c\u8bc1\u3002', '\u7ee7\u7eed\u63d0\u4ea4\u90ae\u4ef6\u3002\u8eab\u4efd\u9a8c\u8bc1\u6210\u529f\u672c\u8eab\u4e0d\u4ee3\u8868\u90ae\u4ef6\u5df2\u6295\u9012\u3002'],
    smtpBasic250: ['\u8bf7\u6c42\u7684\u64cd\u4f5c\u5df2\u63a5\u53d7', '\u524d\u4e00\u6761\u547d\u4ee4\u5df2\u5b8c\u6210\u3002\u5728 DATA \u540e\uff0c\u8868\u793a\u670d\u52a1\u5668\u5df2\u627f\u62c5\u90ae\u4ef6\u7684\u5904\u7406\u8d23\u4efb\u3002', '\u901a\u8fc7\u90ae\u4ef6\u8ddf\u8e2a\u6216\u6295\u9012\u4e8b\u4ef6\u786e\u8ba4\u6700\u7ec8\u7ed3\u679c\u3002\u63a5\u53d7\u90ae\u4ef6\u4e0d\u4fdd\u8bc1\u8fdb\u5165\u6536\u4ef6\u7bb1\u3002'],
    smtpBasic251: ['\u5c06\u8f6c\u53d1\u7ed9\u6536\u4ef6\u4eba', '\u6536\u4ef6\u4eba\u4e0d\u662f\u672c\u5730\u7528\u6237\uff0c\u670d\u52a1\u5668\u5c06\u8f6c\u53d1\u90ae\u4ef6\u3002', '\u66f4\u65b0\u8054\u7cfb\u4eba\u4e4b\u524d\uff0c\u8bf7\u5411\u6536\u4ef6\u4eba\u786e\u8ba4\u8f6c\u53d1\u5730\u5740\u3002'],
    smtpBasic252: ['\u65e0\u6cd5\u9a8c\u8bc1\u6536\u4ef6\u4eba', '\u670d\u52a1\u5668\u4e0d\u9a8c\u8bc1\u6b64\u5730\u5740\uff0c\u4f46\u4f1a\u5c1d\u8bd5\u6295\u9012\u3002', '\u4e0d\u80fd\u636e\u6b64\u786e\u8ba4\u90ae\u7bb1\u5b58\u5728\u3002\u8bf7\u68c0\u67e5\u6700\u7ec8\u6295\u9012\u7ed3\u679c\u3002'],
    smtpBasic334: ['\u8eab\u4efd\u9a8c\u8bc1\u8d28\u8be2', '\u670d\u52a1\u5668\u9700\u8981 AUTH \u4ea4\u6362\u7684\u4e0b\u4e00\u6b65\u3002', '\u8ba9 SMTP \u5ba2\u6237\u7aef\u901a\u8fc7\u5b89\u5168\u8fde\u63a5\u5b8c\u6210\u53d7\u652f\u6301\u7684\u9a8c\u8bc1\u6d41\u7a0b\u3002'],
    smtpBasic354: ['\u51c6\u5907\u63a5\u6536\u90ae\u4ef6\u6570\u636e', '\u670d\u52a1\u5668\u5df2\u63a5\u53d7 DATA\uff0c\u6b63\u5728\u7b49\u5f85\u5185\u5bb9\u3002', '\u53d1\u9001\u90ae\u4ef6\u5185\u5bb9\u5e76\u7b49\u5f85\u6700\u7ec8\u54cd\u5e94\u3002\u76ee\u524d\u90ae\u4ef6\u5c1a\u672a\u88ab\u63a5\u53d7\u3002'],
    smtpBasic421: ['\u670d\u52a1\u6682\u65f6\u4e0d\u53ef\u7528', '\u7ef4\u62a4\u3001\u8fc7\u8f7d\u3001\u9650\u6d41\u6216\u8fde\u63a5\u7b56\u7565\u5bfc\u81f4\u670d\u52a1\u5668\u5173\u95ed\u4f1a\u8bdd\u3002', '\u68c0\u67e5\u670d\u52a1\u72b6\u6001\u548c\u53d1\u9001\u9650\u5236\u3002\u6309\u9000\u907f\u95f4\u9694\u91cd\u8bd5\uff0c\u907f\u514d\u8fde\u7eed\u91cd\u65b0\u8fde\u63a5\u3002'],
    smtpBasic432: ['\u9700\u8981\u8eab\u4efd\u9a8c\u8bc1\u8fc1\u79fb', 'SMTP AUTH \u8981\u6c42\u8d26\u6237\u8fc1\u79fb\u5230\u6240\u9009\u673a\u5236\u3002\u63d0\u4f9b\u5546\u53ef\u80fd\u6709\u4e0d\u540c\u7528\u6cd5\u3002', '\u9075\u5faa\u63d0\u4f9b\u5546\u7684\u8fc1\u79fb\u6d41\u7a0b\u3002\u67e5\u770b\u589e\u5f3a\u4ee3\u7801\u548c\u54cd\u5e94\uff0c\u4ee5\u5224\u65ad\u662f\u5426\u5c5e\u4e8e\u7279\u5b9a\u9650\u6d41\u3002'],
    smtpBasic450: ['\u90ae\u7bb1\u6682\u65f6\u4e0d\u53ef\u7528', '\u90ae\u7bb1\u53ef\u80fd\u7e41\u5fd9\u3001\u6682\u65f6\u7981\u7528\uff0c\u6216\u53d7\u5230\u7070\u540d\u5355\u53ca\u7b56\u7565\u9650\u5236\u3002', '\u5141\u8bb8\u53d1\u9001\u670d\u52a1\u6309\u8ba1\u5212\u91cd\u8bd5\u3002\u6301\u7eed\u5931\u8d25\u65f6\uff0c\u8bf7\u63a5\u6536\u7ba1\u7406\u5458\u68c0\u67e5\u90ae\u7bb1\u548c\u7b56\u7565\u3002'],
    smtpBasic451: ['\u4e34\u65f6\u5904\u7406\u6545\u969c', '\u672c\u5730\u5904\u7406\u3001\u76ee\u5f55\u3001DNS \u6216\u7b56\u7565\u8bc4\u4f30\u51fa\u73b0\u95ee\u9898\u3002', '\u67e5\u770b\u589e\u5f3a\u4ee3\u7801\u548c\u670d\u52a1\u72b6\u6001\uff0c\u8bf7\u8d1f\u8d23\u7684\u7ba1\u7406\u5458\u4fee\u590d\u6301\u7eed\u6545\u969c\u3002'],
    smtpBasic452: ['\u8d44\u6e90\u4e0d\u8db3', '\u670d\u52a1\u5668\u5b58\u50a8\u4e0d\u8db3\uff0c\u6216\u8fbe\u5230\u4e86\u5355\u6b21\u4e8b\u52a1\u7684\u6536\u4ef6\u4eba\u6570\u9650\u5236\u3002', '\u6839\u636e\u54cd\u5e94\u91ca\u653e\u670d\u52a1\u5668\u7a7a\u95f4\uff0c\u6216\u5728\u6536\u4ef6\u4eba\u8fc7\u591a\u65f6\u7f29\u5c0f\u6279\u6b21\u3002'],
    smtpBasic454: ['\u4e34\u65f6\u8eab\u4efd\u9a8c\u8bc1\u6216 TLS \u6545\u969c', '\u8eab\u4efd\u9a8c\u8bc1\u540e\u7aef\u6216 TLS \u670d\u52a1\u6682\u65f6\u4e0d\u53ef\u7528\u3002', '\u68c0\u67e5\u589e\u5f3a\u4ee3\u7801\u3001\u670d\u52a1\u72b6\u6001\u548c TLS \u914d\u7f6e\u3002\u4fdd\u6301\u52a0\u5bc6\u542f\u7528\u3002'],
    smtpBasic455: ['\u6682\u4e0d\u652f\u6301\u8fd9\u4e9b\u53c2\u6570', '\u670d\u52a1\u5668\u76ee\u524d\u65e0\u6cd5\u5904\u7406 MAIL FROM \u6216 RCPT TO \u53c2\u6570\u3002', '\u4f7f\u7528 EHLO \u516c\u5e03\u7684\u53c2\u6570\uff0c\u5e76\u9075\u5faa\u53d1\u9001\u670d\u52a1\u7684\u91cd\u8bd5\u7b56\u7565\u3002'],
