    smtpBasic334: ['\u062a\u062d\u062f\u064a \u0645\u0635\u0627\u062f\u0642\u0629', '\u064a\u062d\u062a\u0627\u062c \u0627\u0644\u062e\u0627\u062f\u0645 \u0625\u0644\u0649 \u0627\u0644\u062e\u0637\u0648\u0629 \u0627\u0644\u062a\u0627\u0644\u064a\u0629 \u0641\u064a \u062a\u0628\u0627\u062f\u0644 AUTH.', '\u062f\u0639 \u0627\u0644\u0639\u0645\u064a\u0644 \u064a\u0643\u0645\u0644 \u0637\u0631\u064a\u0642\u0629 \u0627\u0644\u0645\u0635\u0627\u062f\u0642\u0629 \u0627\u0644\u0645\u062f\u0639\u0648\u0645\u0629 \u0639\u0628\u0631 \u0627\u062a\u0635\u0627\u0644 \u0622\u0645\u0646.'],
