    smtpBasic421: ['\u0627\u0644\u062e\u062f\u0645\u0629 \u063a\u064a\u0631 \u0645\u062a\u0627\u062d\u0629 \u0645\u0624\u0642\u062a\u0627', '\u0623\u062f\u062a \u0627\u0644\u0635\u064a\u0627\u0646\u0629 \u0623\u0648 \u0627\u0644\u0636\u063a\u0637 \u0623\u0648 \u062d\u062f\u0648\u062f \u0627\u0644\u0625\u0631\u0633\u0627\u0644 \u0623\u0648 \u0633\u064a\u0627\u0633\u0629 \u0627\u0644\u0627\u062a\u0635\u0627\u0644 \u0625\u0644\u0649 \u0625\u063a\u0644\u0627\u0642 \u0627\u0644\u062c\u0644\u0633\u0629.', '\u062a\u062d\u0642\u0642 \u0645\u0646 \u0627\u0644\u062e\u062f\u0645\u0629 \u0648\u0627\u0644\u062d\u062f\u0648\u062f. \u0627\u0633\u0645\u062d \u0628\u0625\u0639\u0627\u062f\u0629 \u0627\u0644\u0645\u062d\u0627\u0648\u0644\u0629 \u0628\u0641\u0648\u0627\u0635\u0644 \u0645\u062a\u0632\u0627\u064a\u062f\u0629 \u0648\u062a\u062c\u0646\u0628 \u0625\u0639\u0627\u062f\u0629 \u0627\u0644\u0627\u062a\u0635\u0627\u0644 \u0627\u0644\u0645\u062a\u0648\u0627\u0635\u0644.'],
    smtpBasic432: ['\u064a\u0644\u0632\u0645 \u0627\u0646\u062a\u0642\u0627\u0644 \u0641\u064a \u0627\u0644\u0645\u0635\u0627\u062f\u0642\u0629', '\u062a\u062d\u062a\u0627\u062c \u0627\u0644\u062d\u0633\u0627\u0628\u0627\u062a \u0641\u064a SMTP AUTH \u0625\u0644\u0649 \u0627\u0646\u062a\u0642\u0627\u0644 \u0644\u0644\u0622\u0644\u064a\u0629 \u0627\u0644\u0645\u062e\u062a\u0627\u0631\u0629. \u0642\u062f \u064a\u0633\u062a\u062e\u062f\u0645 \u0627\u0644\u0645\u0632\u0648\u062f \u0627\u0644\u0631\u0645\u0632 \u0628\u0635\u0648\u0631\u0629 \u0645\u062e\u062a\u0644\u0641\u0629.', '\u0627\u062a\u0628\u0639 \u0625\u062c\u0631\u0627\u0621 \u0627\u0644\u0627\u0646\u062a\u0642\u0627\u0644 \u0644\u062f\u0649 \u0627\u0644\u0645\u0632\u0648\u062f. \u0631\u0627\u062c\u0639 \u0627\u0644\u0631\u0645\u0632 \u0627\u0644\u0645\u062d\u0633\u0646 \u0648\u0627\u0644\u0646\u0635 \u0644\u0627\u062d\u062a\u0645\u0627\u0644 \u0648\u062c\u0648\u062f \u062d\u062f \u0625\u0631\u0633\u0627\u0644 \u062e\u0627\u0635 \u0628\u0627\u0644\u0645\u0632\u0648\u062f.'],
    smtpBasic450: ['\u0635\u0646\u062f\u0648\u0642 \u0627\u0644\u0628\u0631\u064a\u062f \u063a\u064a\u0631 \u0645\u062a\u0627\u062d \u0645\u0624\u0642\u062a\u0627', '\u0642\u062f \u064a\u0643\u0648\u0646 \u0627\u0644\u0635\u0646\u062f\u0648\u0642 \u0645\u0634\u063a\u0648\u0644\u0627 \u0623\u0648 \u0645\u0639\u0637\u0644\u0627 \u0645\u0624\u0642\u062a\u0627 \u0623\u0648 \u062e\u0627\u0636\u0639\u0627 \u0644\u0644\u0642\u0627\u0626\u0645\u0629 \u0627\u0644\u0631\u0645\u0627\u062f\u064a\u0629 \u0623\u0648 \u0633\u064a\u0627\u0633\u0629 \u062a\u0642\u064a\u064a\u062f.', '\u0627\u0633\u0645\u062d \u0628\u0627\u0644\u0645\u062d\u0627\u0648\u0644\u0627\u062a \u0627\u0644\u0645\u062c\u062f\u0648\u0644\u0629. \u0625\u0630\u0627 \u0627\u0633\u062a\u0645\u0631 \u0627\u0644\u0641\u0634\u0644 \u0641\u0627\u0637\u0644\u0628 \u0645\u0646 \u0645\u0633\u0624\u0648\u0644 \u0627\u0644\u0627\u0633\u062a\u0642\u0628\u0627\u0644 \u0641\u062d\u0635 \u0627\u0644\u0635\u0646\u062f\u0648\u0642 \u0648\u0627\u0644\u0633\u064a\u0627\u0633\u0629.'],
    smtpBasic451: ['\u0641\u0634\u0644 \u0645\u0624\u0642\u062a \u0641\u064a \u0627\u0644\u0645\u0639\u0627\u0644\u062c\u0629', '\u062d\u062f\u062b\u062a \u0645\u0634\u0643\u0644\u0629 \u0641\u064a \u0627\u0644\u0645\u0639\u0627\u0644\u062c\u0629 \u0627\u0644\u0645\u062d\u0644\u064a\u0629 \u0623\u0648 \u0627\u0644\u062f\u0644\u064a\u0644 \u0623\u0648 DNS \u0623\u0648 \u062a\u0642\u064a\u064a\u0645 \u0627\u0644\u0633\u064a\u0627\u0633\u0627\u062a.', '\u0631\u0627\u062c\u0639 \u0627\u0644\u0631\u0645\u0632 \u0627\u0644\u0645\u062d\u0633\u0646 \u0648\u062d\u0627\u0644\u0629 \u0627\u0644\u062e\u062f\u0645\u0629. \u064a\u0646\u0628\u063a\u064a \u0644\u0644\u0645\u0633\u0624\u0648\u0644 \u0627\u0644\u0645\u062e\u062a\u0635 \u0625\u0635\u0644\u0627\u062d \u0627\u0644\u0623\u0639\u0637\u0627\u0644 \u0627\u0644\u0645\u0633\u062a\u0645\u0631\u0629.'],
    smtpBasic452: ['\u0645\u0648\u0627\u0631\u062f \u063a\u064a\u0631 \u0643\u0627\u0641\u064a\u0629', '\u0642\u062f \u064a\u0646\u0642\u0635 \u0627\u0644\u062a\u062e\u0632\u064a\u0646 \u0623\u0648 \u062a\u0645 \u0628\u0644\u0648\u063a \u062d\u062f \u0627\u0644\u0645\u0633\u062a\u0644\u0645\u064a\u0646 \u0644\u0643\u0644 \u0645\u0639\u0627\u0645\u0644\u0629.', '\u062d\u0633\u0628 \u0646\u0635 \u0627\u0644\u0631\u062f\u060c \u0648\u0641\u0631 \u0645\u0633\u0627\u062d\u0629 \u062a\u062e\u0632\u064a\u0646 \u0623\u0648 \u0642\u0633\u0645 \u0627\u0644\u0645\u0633\u062a\u0644\u0645\u064a\u0646 \u0625\u0644\u0649 \u062f\u0641\u0639\u0627\u062a \u0623\u0635\u063a\u0631.'],
    smtpBasic454: ['\u0641\u0634\u0644 \u0645\u0624\u0642\u062a \u0641\u064a \u0627\u0644\u0645\u0635\u0627\u062f\u0642\u0629 \u0623\u0648 TLS', '\u062e\u062f\u0645\u0629 \u0627\u0644\u0645\u0635\u0627\u062f\u0642\u0629 \u0623\u0648 TLS \u063a\u064a\u0631 \u0645\u062a\u0627\u062d\u0629 \u0645\u0624\u0642\u062a\u0627.', '\u062a\u062d\u0642\u0642 \u0645\u0646 \u0627\u0644\u0631\u0645\u0632 \u0627\u0644\u0645\u062d\u0633\u0646 \u0648\u062d\u0627\u0644\u0629 \u0627\u0644\u062e\u062f\u0645\u0629 \u0648\u0625\u0639\u062f\u0627\u062f TLS. \u0623\u0628\u0642 \u0627\u0644\u062a\u0634\u0641\u064a\u0631 \u0645\u0641\u0639\u0644\u0627.'],
    smtpBasic455: ['\u0627\u0644\u0645\u0639\u0644\u0645\u0627\u062a \u063a\u064a\u0631 \u0645\u062f\u0639\u0648\u0645\u0629 \u0645\u0624\u0642\u062a\u0627', '\u0644\u0627 \u064a\u0633\u062a\u0637\u064a\u0639 \u0627\u0644\u062e\u0627\u062f\u0645 \u062d\u0627\u0644\u064a\u0627 \u0627\u0644\u062a\u0639\u0627\u0645\u0644 \u0645\u0639 \u0645\u0639\u0644\u0645\u0629 MAIL FROM \u0623\u0648 RCPT TO.', '\u0627\u0633\u062a\u062e\u062f\u0645 \u0627\u0644\u0645\u0639\u0644\u0645\u0627\u062a \u0627\u0644\u0645\u0639\u0644\u0646\u0629 \u0641\u064a EHLO \u0648\u0633\u064a\u0627\u0633\u0629 \u0625\u0639\u0627\u062f\u0629 \u0627\u0644\u0645\u062d\u0627\u0648\u0644\u0629 \u0644\u062e\u062f\u0645\u0629 \u0627\u0644\u0625\u0631\u0633\u0627\u0644.'],
    smtpBasic500: ['\u0627\u0644\u0623\u0645\u0631 \u063a\u064a\u0631 \u0645\u0639\u0631\u0648\u0641', '\u0627\u0644\u0623\u0645\u0631 \u063a\u064a\u0631 \u0645\u062f\u0639\u0648\u0645 \u0623\u0648 \u062a\u0646\u0633\u064a\u0642\u0647 \u062e\u0627\u0637\u0626 \u0623\u0648 \u0637\u0648\u064a\u0644 \u062c\u062f\u0627.', '\u062a\u062d\u0642\u0642 \u0645\u0646 \u0625\u0639\u062f\u0627\u062f\u0627\u062a \u0627\u0644\u0639\u0645\u064a\u0644 \u0648\u0637\u0648\u0644 \u0627\u0644\u0633\u0637\u0648\u0631 \u0648\u0625\u0645\u0643\u0627\u0646\u0627\u062a EHLO.'],
    smtpBasic501: ['\u0648\u0633\u064a\u0637\u0627\u062a \u0623\u0645\u0631 \u063a\u064a\u0631 \u0635\u0627\u0644\u062d\u0629', '\u0635\u064a\u063a\u0629 \u0639\u0646\u0648\u0627\u0646 \u0623\u0648 \u0645\u0639\u0644\u0645\u0629 \u0623\u0648 \u0648\u0633\u064a\u0637\u0629 \u063a\u064a\u0631 \u0635\u062d\u064a\u062d\u0629.', '\u0635\u062d\u062d \u0639\u0646\u0627\u0648\u064a\u0646 \u0627\u0644\u0645\u063a\u0644\u0641 \u0648\u0627\u0644\u0645\u0639\u0644\u0645\u0627\u062a \u0648\u0627\u0633\u062a\u062e\u062f\u0645 \u0645\u0643\u062a\u0628\u0629 SMTP \u062a\u062a\u0645 \u0635\u064a\u0627\u0646\u062a\u0647\u0627.'],
    smtpBasic502: ['\u0627\u0644\u0623\u0645\u0631 \u063a\u064a\u0631 \u0645\u0646\u0641\u0630', '\u064a\u062a\u0639\u0631\u0641 \u0627\u0644\u062e\u0627\u062f\u0645 \u0639\u0644\u0649 \u0627\u0644\u0623\u0645\u0631 \u0644\u0643\u0646\u0647 \u0644\u0627 \u064a\u0646\u0641\u0630\u0647.', '\u0627\u0633\u062a\u062e\u062f\u0645 \u0623\u0648\u0627\u0645\u0631 \u0645\u062f\u0639\u0648\u0645\u0629 \u0648\u062a\u0623\u0643\u062f \u0645\u0646 \u0646\u0642\u0637\u0629 \u0627\u062a\u0635\u0627\u0644 SMTP \u0627\u0644\u0635\u062d\u064a\u062d\u0629.'],
    smtpBasic503: ['\u062a\u0633\u0644\u0633\u0644 \u0627\u0644\u0623\u0648\u0627\u0645\u0631 \u063a\u064a\u0631 \u0635\u062d\u064a\u062d', '\u0623\u0645\u0631 \u0633\u0627\u0628\u0642 \u0645\u0637\u0644\u0648\u0628 \u0645\u0641\u0642\u0648\u062f \u0623\u0648 \u062a\u0648\u062c\u062f \u0645\u0639\u0627\u0645\u0644\u0629 \u0645\u0641\u062a\u0648\u062d\u0629 \u0628\u0627\u0644\u0641\u0639\u0644.', '\u0631\u0627\u062c\u0639 \u062a\u0633\u0644\u0633\u0644 EHLO \u0648\u0627\u0644\u0645\u0635\u0627\u062f\u0642\u0629 \u0648MAIL FROM \u0648RCPT TO \u0648DATA \u0641\u064a \u0627\u0644\u0639\u0645\u064a\u0644.'],
    smtpBasic504: ['\u0645\u0639\u0644\u0645\u0629 \u0623\u0645\u0631 \u063a\u064a\u0631 \u0645\u062f\u0639\u0648\u0645\u0629', '\u0644\u0627 \u064a\u062f\u0639\u0645 \u0627\u0644\u062e\u0627\u062f\u0645 \u0627\u0644\u0645\u0639\u0644\u0645\u0629 \u0623\u0648 \u0622\u0644\u064a\u0629 \u0627\u0644\u0645\u0635\u0627\u062f\u0642\u0629 \u0627\u0644\u0645\u0637\u0644\u0648\u0628\u0629.', '\u0627\u0633\u062a\u062e\u062f\u0645 \u0627\u0644\u0622\u0644\u064a\u0627\u062a \u0648\u0627\u0644\u0627\u0645\u062a\u062f\u0627\u062f\u0627\u062a \u0627\u0644\u0645\u0639\u0644\u0646\u0629 \u0628\u0639\u062f EHLO \u0648STARTTLS.'],
    smtpBasic521: ['\u0627\u0644\u0645\u0636\u064a\u0641 \u0644\u0627 \u064a\u0642\u0628\u0644 \u0627\u0644\u0628\u0631\u064a\u062f', '\u064a\u0639\u0644\u0646 \u0627\u0644\u0645\u0636\u064a\u0641 \u0627\u0644\u0648\u062c\u0647\u0629 \u0635\u0631\u0627\u062d\u0629 \u0623\u0646\u0647 \u0644\u0627 \u064a\u0642\u062f\u0645 \u062e\u062f\u0645\u0629 \u0628\u0631\u064a\u062f SMTP.', '\u0623\u0643\u062f \u0646\u0637\u0627\u0642 \u0627\u0644\u0645\u0633\u062a\u0644\u0645 \u0648\u0625\u0639\u062f\u0627\u062f MX \u0645\u0639 \u0645\u0633\u0624\u0648\u0644 \u0627\u0644\u0646\u0637\u0627\u0642.'],
    smtpBasic530: ['\u0627\u0644\u0645\u0635\u0627\u062f\u0642\u0629 \u0623\u0648 STARTTLS \u0645\u0637\u0644\u0648\u0628\u0629', '\u064a\u0634\u062a\u0631\u0637 \u0627\u0644\u062e\u0627\u062f\u0645 \u0645\u0635\u0627\u062f\u0642\u0629 \u0623\u0648 \u0627\u062a\u0635\u0627\u0644\u0627 \u0622\u0645\u0646\u0627 \u0642\u0628\u0644 \u0627\u0644\u0623\u0645\u0631.', '\u0631\u0627\u062c\u0639 \u0627\u0644\u0631\u062f \u0648\u0627\u0636\u0628\u0637 STARTTLS \u0648\u0637\u0631\u064a\u0642\u0629 \u0627\u0644\u0645\u0635\u0627\u062f\u0642\u0629 \u0627\u0644\u0645\u062f\u0639\u0648\u0645\u0629. \u0644\u0627 \u062a\u0639\u0637\u0644 TLS.'],
    smtpBasic534: ['\u0622\u0644\u064a\u0629 \u0645\u0635\u0627\u062f\u0642\u0629 \u0636\u0639\u064a\u0641\u0629', '\u0627\u0644\u0637\u0631\u064a\u0642\u0629 \u0627\u0644\u0645\u062e\u062a\u0627\u0631\u0629 \u0644\u0627 \u062a\u062d\u0642\u0642 \u0633\u064a\u0627\u0633\u0629 \u0627\u0644\u062e\u0627\u062f\u0645.', '\u0627\u0633\u062a\u062e\u062f\u0645 \u0637\u0631\u064a\u0642\u0629 \u0623\u0642\u0648\u0649 \u0645\u062f\u0639\u0648\u0645\u0629 \u0648\u0627\u062a\u0635\u0627\u0644\u0627 \u0622\u0645\u0646\u0627.'],
    smtpBasic535: ['\u0641\u0634\u0644\u062a \u0627\u0644\u0645\u0635\u0627\u062f\u0642\u0629', '\u0631\u0641\u0636\u062a \u0628\u064a\u0627\u0646\u0627\u062a \u0627\u0644\u0627\u0639\u062a\u0645\u0627\u062f \u0623\u0648 \u0627\u0644\u0635\u0644\u0627\u062d\u064a\u0627\u062a \u0623\u0648 \u0637\u0631\u064a\u0642\u0629 \u0627\u0644\u0645\u0635\u0627\u062f\u0642\u0629.', '\u062a\u062d\u0642\u0642 \u0645\u0646 \u0627\u0644\u062d\u0633\u0627\u0628 \u0648\u0623\u0630\u0648\u0646\u0627\u062a \u0627\u0644\u062a\u0637\u0628\u064a\u0642 \u0648\u0627\u0644\u0637\u0631\u064a\u0642\u0629 \u0627\u0644\u0645\u062f\u0639\u0648\u0645\u0629. \u0644\u0627 \u062a\u0644\u0635\u0642 \u0643\u0644\u0645\u0627\u062a \u0645\u0631\u0648\u0631 \u0623\u0648 \u0631\u0645\u0648\u0632 \u0648\u0635\u0648\u0644 \u0647\u0646\u0627.'],
    smtpBasic538: ['\u0627\u0644\u0645\u0635\u0627\u062f\u0642\u0629 \u062a\u062a\u0637\u0644\u0628 \u0627\u0644\u062a\u0634\u0641\u064a\u0631', '\u0622\u0644\u064a\u0629 \u0627\u0644\u0645\u0635\u0627\u062f\u0642\u0629 \u062a\u062d\u062a\u0627\u062c \u0627\u062a\u0635\u0627\u0644\u0627 \u0645\u0634\u0641\u0631\u0627.', '\u0627\u0636\u0628\u0637 STARTTLS \u0623\u0648 \u0646\u0642\u0637\u0629 \u0625\u0631\u0633\u0627\u0644 TLS \u0627\u0644\u0645\u0648\u062b\u0642\u0629 \u0642\u0628\u0644 \u0627\u0644\u0645\u0635\u0627\u062f\u0642\u0629.'],
    smtpBasic550: ['\u0627\u0644\u0635\u0646\u062f\u0648\u0642 \u063a\u064a\u0631 \u0645\u062a\u0627\u062d \u0623\u0648 \u0627\u0644\u0625\u062c\u0631\u0627\u0621 \u0645\u0631\u0641\u0648\u0636', '\u0642\u062f \u0644\u0627 \u064a\u0648\u062c\u062f \u0627\u0644\u0639\u0646\u0648\u0627\u0646 \u0623\u0648 \u064a\u0645\u0646\u0639 \u0627\u0644\u0648\u0635\u0648\u0644 \u0623\u0648 \u062a\u0631\u0641\u0636 \u0633\u064a\u0627\u0633\u0629 \u0627\u0644\u0645\u0633\u062a\u0644\u0645 \u0623\u0648 \u0627\u0644\u062a\u0631\u062d\u064a\u0644 \u0627\u0644\u0637\u0644\u0628.', '\u0627\u0633\u062a\u062e\u062f\u0645 \u0627\u0644\u0631\u0645\u0632 \u0627\u0644\u0645\u062d\u0633\u0646 \u0648\u0627\u0644\u0631\u062f \u0627\u0644\u0623\u0635\u0644\u064a \u0644\u0644\u062a\u0645\u064a\u064a\u0632 \u0628\u064a\u0646 \u062e\u0637\u0623 \u0627\u0644\u0639\u0646\u0648\u0627\u0646 \u0648\u0645\u0634\u0643\u0644\u0629 \u0627\u0644\u0633\u064a\u0627\u0633\u0629 \u0623\u0648 \u0627\u0644\u0645\u0635\u0627\u062f\u0642\u0629.'],
    smtpBasic551: ['\u0627\u0644\u0645\u0633\u062a\u0644\u0645 \u063a\u064a\u0631 \u0645\u062d\u0644\u064a', '\u0631\u0641\u0636 \u0627\u0644\u062e\u0627\u062f\u0645 \u0627\u0644\u062a\u0633\u0644\u064a\u0645 \u0648\u0642\u062f \u064a\u0643\u0648\u0646 \u0623\u0639\u0637\u0649 \u0639\u0646\u0648\u0627\u0646 \u0625\u0639\u0627\u062f\u0629 \u062a\u0648\u062c\u064a\u0647.', '\u0623\u0643\u062f \u0627\u0644\u0639\u0646\u0648\u0627\u0646 \u0627\u0644\u0628\u062f\u064a\u0644 \u0645\u0639 \u0627\u0644\u0645\u0633\u062a\u0644\u0645 \u0648\u0635\u062d\u062d \u0627\u0644\u062a\u0648\u062c\u064a\u0647 \u0623\u0648 \u062c\u0647\u0629 \u0627\u0644\u0627\u062a\u0635\u0627\u0644.'],
    smtpBasic552: ['\u062a\u062c\u0627\u0648\u0632 \u062d\u062f \u0627\u0644\u062a\u062e\u0632\u064a\u0646 \u0623\u0648 \u0627\u0644\u0631\u0633\u0627\u0644\u0629', '\u062a\u0645 \u062a\u062c\u0627\u0648\u0632 \u062d\u0635\u0629 \u0627\u0644\u0635\u0646\u062f\u0648\u0642 \u0623\u0648 \u062d\u062c\u0645 \u0627\u0644\u0631\u0633\u0627\u0644\u0629. \u062a\u0633\u062a\u062e\u062f\u0645 \u062e\u0648\u0627\u062f\u0645 \u0642\u062f\u064a\u0645\u0629 \u0627\u0644\u0631\u0645\u0632 \u0623\u064a\u0636\u0627 \u0644\u0643\u062b\u0631\u0629 \u0627\u0644\u0645\u0633\u062a\u0644\u0645\u064a\u0646.', '\u0648\u0641\u0631 \u0645\u0633\u0627\u062d\u0629 \u0623\u0648 \u0642\u0644\u0644 \u0627\u0644\u062d\u062c\u0645. \u0641\u0642\u0637 \u0625\u0630\u0627 \u0630\u0643\u0631 \u0627\u0644\u0646\u0635 \u0643\u062b\u0631\u0629 \u0627\u0644\u0645\u0633\u062a\u0644\u0645\u064a\u0646\u060c \u0642\u0633\u0645 \u0627\u0644\u062f\u0641\u0639\u0629 \u0648\u0623\u0639\u062f \u0627\u0644\u0645\u062d\u0627\u0648\u0644\u0629 \u0644\u0647\u0624\u0644\u0627\u0621 \u0627\u0644\u0645\u0633\u062a\u0644\u0645\u064a\u0646.'],
    smtpBasic553: ['\u0627\u0633\u0645 \u0627\u0644\u0635\u0646\u062f\u0648\u0642 \u063a\u064a\u0631 \u0645\u0633\u0645\u0648\u062d', '\u0639\u0646\u0648\u0627\u0646 \u0627\u0644\u0645\u063a\u0644\u0641 \u063a\u064a\u0631 \u0635\u062d\u064a\u062d \u0623\u0648 \u063a\u064a\u0631 \u0645\u0633\u0645\u0648\u062d \u0644\u062f\u0649 \u0646\u0638\u0627\u0645 \u0627\u0644\u0627\u0633\u062a\u0642\u0628\u0627\u0644.', '\u0631\u0627\u062c\u0639 \u0639\u0646\u0627\u0648\u064a\u0646 \u0627\u0644\u0637\u0631\u0641\u064a\u0646 \u0648\u0647\u0648\u064a\u0627\u062a \u0627\u0644\u0625\u0631\u0633\u0627\u0644 \u0627\u0644\u0645\u0633\u0645\u0648\u062d\u0629 \u0648\u0627\u0644\u0631\u0645\u0632 \u0627\u0644\u0645\u062d\u0633\u0646.'],
    smtpBasic554: ['\u0631\u0641\u0636 \u0627\u0644\u0645\u0639\u0627\u0645\u0644\u0629', '\u0631\u0641\u0636\u062a \u0627\u0644\u0631\u0633\u0627\u0644\u0629 \u0623\u0648 \u0627\u0644\u0627\u062a\u0635\u0627\u0644\u061b \u0644\u0627 \u064a\u062d\u062f\u062f \u0627\u0644\u0631\u0645\u0632 \u0627\u0644\u0639\u0627\u0645 \u0648\u062d\u062f\u0647 \u0627\u0644\u0633\u0628\u0628.', '\u0631\u0627\u062c\u0639 \u0627\u0644\u0631\u0645\u0632 \u0627\u0644\u0645\u062d\u0633\u0646 \u0648\u062a\u0641\u0633\u064a\u0631 \u0627\u0644\u0645\u0633\u062a\u0644\u0645 \u0644\u0645\u0634\u0643\u0644\u0627\u062a \u0627\u0644\u0645\u062d\u062a\u0648\u0649 \u0623\u0648 \u0627\u0644\u0633\u064a\u0627\u0633\u0629 \u0623\u0648 \u0627\u0644\u0645\u0635\u0627\u062f\u0642\u0629 \u0623\u0648 \u0627\u0644\u062a\u0648\u062c\u064a\u0647.'],
    smtpBasic555: ['\u0645\u0639\u0644\u0645\u0627\u062a \u0627\u0644\u0645\u063a\u0644\u0641 \u063a\u064a\u0631 \u0645\u062f\u0639\u0648\u0645\u0629', '\u0645\u0639\u0644\u0645\u0629 MAIL FROM \u0623\u0648 RCPT TO \u063a\u064a\u0631 \u0645\u0639\u0631\u0648\u0641\u0629 \u0623\u0648 \u063a\u064a\u0631 \u0645\u0646\u0641\u0630\u0629.', '\u0627\u062d\u0630\u0641 \u0627\u0644\u0645\u0639\u0644\u0645\u0627\u062a \u063a\u064a\u0631 \u0627\u0644\u0645\u062f\u0639\u0648\u0645\u0629 \u0648\u0627\u0633\u062a\u062e\u062f\u0645 \u0627\u0645\u062a\u062f\u0627\u062f\u0627\u062a EHLO \u0627\u0644\u0645\u0639\u0644\u0646\u0629 \u0641\u0642\u0637.'],
    smtpBasic556: ['\u0646\u0637\u0627\u0642 \u0627\u0644\u0645\u0633\u062a\u0644\u0645 \u0644\u0627 \u064a\u0642\u0628\u0644 \u0627\u0644\u0628\u0631\u064a\u062f', '\u064a\u0631\u0641\u0636 \u0627\u0644\u0646\u0637\u0627\u0642 \u0627\u0644\u0628\u0631\u064a\u062f \u0635\u0631\u0627\u062d\u0629\u060c \u0639\u0627\u062f\u0629 \u0628\u0633\u062c\u0644 MX \u0641\u0627\u0631\u063a.', '\u0627\u0633\u062a\u062e\u062f\u0645 \u0639\u0646\u0648\u0627\u0646\u0627 \u0622\u062e\u0631 \u0645\u0624\u0643\u062f\u0627. \u0644\u0627 \u062a\u0633\u062a\u0628\u062f\u0644 \u0633\u062c\u0644 MX \u0627\u0644\u0641\u0627\u0631\u063a \u0627\u0644\u0645\u0642\u0635\u0648\u062f \u062f\u0648\u0646 \u0645\u0648\u0627\u0641\u0642\u0629 \u0645\u0627\u0644\u0643 \u0627\u0644\u0646\u0637\u0627\u0642.'],
    'smtpEnhanced0.0': ['\u0644\u0627 \u062a\u0648\u062c\u062f \u062a\u0641\u0627\u0635\u064a\u0644 \u062d\u0627\u0644\u0629 \u0625\u0636\u0627\u0641\u064a\u0629', '\u0642\u062f\u0645 \u0627\u0644\u062e\u0627\u062f\u0645 \u0646\u062a\u064a\u062c\u0629 \u0639\u0627\u0645\u0629 \u0641\u0642\u0637.', '\u0631\u0627\u062c\u0639 \u0627\u0644\u0631\u062f \u0627\u0644\u0643\u0627\u0645\u0644 \u0648\u062a\u062a\u0628\u0639 \u0627\u0644\u0631\u0633\u0627\u0644\u0629 \u0644\u0645\u0639\u0631\u0641\u0629 \u0645\u0627 \u062d\u062f\u062b.'],
    'smtpEnhanced1.0': ['\u0641\u0634\u0644 \u0645\u062a\u0639\u0644\u0642 \u0628\u0627\u0644\u0639\u0646\u0627\u0648\u064a\u0646', '\u062a\u0639\u0630\u0631 \u0627\u0633\u062a\u062e\u062f\u0627\u0645 \u0639\u0646\u0648\u0627\u0646 \u0627\u0644\u0645\u0631\u0633\u0644 \u0623\u0648 \u0627\u0644\u0645\u0633\u062a\u0644\u0645 \u062f\u0648\u0646 \u062a\u0641\u0627\u0635\u064a\u0644 \u0623\u062f\u0642.', '\u062a\u062d\u0642\u0642 \u0645\u0646 \u0639\u0646\u0648\u0627\u0646\u064a \u0627\u0644\u0645\u063a\u0644\u0641 \u0648\u062f\u0644\u064a\u0644 \u0627\u0644\u0645\u0633\u062a\u0644\u0645.'],
    'smtpEnhanced1.1': ['\u0644\u0645 \u064a\u0639\u062b\u0631 \u0639\u0644\u0649 \u0635\u0646\u062f\u0648\u0642 \u0627\u0644\u0645\u0633\u062a\u0644\u0645', '\u0627\u0644\u0635\u0646\u062f\u0648\u0642 \u0623\u0648 \u0627\u0644\u0627\u0633\u0645 \u0627\u0644\u0645\u0633\u062a\u0639\u0627\u0631 \u063a\u064a\u0631 \u0645\u0648\u062c\u0648\u062f \u0623\u0648 \u062d\u0630\u0641 \u0623\u0648 \u0643\u062a\u0628 \u0628\u0634\u0643\u0644 \u062e\u0627\u0637\u0626.', '\u0623\u0643\u062f \u0627\u0644\u0639\u0646\u0648\u0627\u0646 \u0645\u0639 \u0627\u0644\u0645\u0633\u062a\u0644\u0645 \u0648\u0635\u062d\u062d \u0627\u0644\u0643\u062a\u0627\u0628\u0629 \u0648\u0627\u062d\u0630\u0641 \u0627\u0642\u062a\u0631\u0627\u062d\u0627\u062a \u0627\u0644\u0625\u0643\u0645\u0627\u0644 \u0627\u0644\u0642\u062f\u064a\u0645\u0629. \u0627\u0637\u0644\u0628 \u0641\u062d\u0635 \u0627\u0644\u0623\u0633\u0645\u0627\u0621 \u0627\u0644\u0645\u0633\u062a\u0639\u0627\u0631\u0629 \u0645\u0646 \u0645\u0633\u0624\u0648\u0644 \u0627\u0644\u0645\u0633\u062a\u0644\u0645.'],
    'smtpEnhanced1.2': ['\u0646\u0637\u0627\u0642 \u0627\u0644\u0645\u0633\u062a\u0644\u0645 \u063a\u064a\u0631 \u0635\u0627\u0644\u062d \u0644\u0644\u0628\u0631\u064a\u062f', '\u0646\u0637\u0627\u0642 \u0627\u0644\u0648\u062c\u0647\u0629 \u063a\u064a\u0631 \u0645\u0648\u062c\u0648\u062f \u0623\u0648 \u0644\u0627 \u064a\u0645\u0643\u0646\u0647 \u0627\u0633\u062a\u0642\u0628\u0627\u0644 \u0627\u0644\u0628\u0631\u064a\u062f.', '\u0635\u062d\u062d \u0627\u0633\u0645 \u0627\u0644\u0646\u0637\u0627\u0642 \u0648\u0627\u0637\u0644\u0628 \u0645\u0646 \u0645\u0627\u0644\u0643\u0647 \u0645\u0631\u0627\u062c\u0639\u0629 \u0627\u0644\u062a\u0633\u062c\u064a\u0644 \u0648MX \u0648\u0625\u0639\u062f\u0627\u062f \u062e\u062f\u0645\u0629 \u0627\u0644\u0628\u0631\u064a\u062f.'],
    'smtpEnhanced1.3': ['\u0635\u064a\u063a\u0629 \u0639\u0646\u0648\u0627\u0646 \u0627\u0644\u0645\u0633\u062a\u0644\u0645 \u063a\u064a\u0631 \u0635\u0627\u0644\u062d\u0629', '\u0639\u0646\u0648\u0627\u0646 \u0627\u0644\u0645\u0633\u062a\u0644\u0645 \u0645\u0643\u062a\u0648\u0628 \u0628\u0635\u064a\u063a\u0629 \u063a\u064a\u0631 \u0635\u062d\u064a\u062d\u0629.', '\u0635\u062d\u062d \u0627\u0644\u062c\u0632\u0621 \u0627\u0644\u0645\u062d\u0644\u064a \u0648\u0627\u0644\u0641\u0627\u0635\u0644 @ \u0648\u0627\u0644\u0646\u0637\u0627\u0642 \u0641\u064a \u0639\u0646\u0648\u0627\u0646 \u0627\u0644\u0645\u063a\u0644\u0641.'],
    'smtpEnhanced1.4': ['\u0639\u0646\u0648\u0627\u0646 \u0627\u0644\u0645\u0633\u062a\u0644\u0645 \u0645\u0644\u062a\u0628\u0633', '\u064a\u0631\u0628\u0637 \u0627\u0644\u062f\u0644\u064a\u0644 \u0627\u0644\u0639\u0646\u0648\u0627\u0646 \u0628\u0623\u0643\u062b\u0631 \u0645\u0646 \u0645\u0633\u062a\u0644\u0645.', '\u0627\u0637\u0644\u0628 \u0645\u0646 \u0627\u0644\u0645\u0633\u0624\u0648\u0644 \u062a\u0635\u062d\u064a\u062d \u0627\u0644\u0623\u0633\u0645\u0627\u0621 \u0627\u0644\u0645\u0633\u062a\u0639\u0627\u0631\u0629 \u0623\u0648 \u0625\u062f\u062e\u0627\u0644\u0627\u062a \u0627\u0644\u062f\u0644\u064a\u0644 \u0627\u0644\u0645\u062a\u0639\u0627\u0631\u0636\u0629.'],
    'smtpEnhanced1.5': ['\u062a\u0645 \u0642\u0628\u0648\u0644 \u0639\u0646\u0648\u0627\u0646 \u0627\u0644\u0645\u0633\u062a\u0644\u0645', '\u0642\u0628\u0644 \u0646\u0638\u0627\u0645 \u0627\u0644\u0627\u0633\u062a\u0642\u0628\u0627\u0644 \u0627\u0644\u0639\u0646\u0648\u0627\u0646 \u0627\u0644\u0645\u062d\u062f\u062f.', '\u0644\u0627 \u064a\u0648\u062c\u062f \u062a\u0635\u062d\u064a\u062d \u0639\u0646\u0648\u0627\u0646 \u0645\u0637\u0644\u0648\u0628. \u0627\u0644\u0642\u0628\u0648\u0644 \u0641\u064a \u0647\u0630\u0647 \u0627\u0644\u0645\u0631\u062d\u0644\u0629 \u0644\u0627 \u064a\u062b\u0628\u062a \u0627\u0644\u0648\u0635\u0648\u0644 \u0627\u0644\u0646\u0647\u0627\u0626\u064a \u0625\u0644\u0649 \u0639\u0644\u0628\u0629 \u0627\u0644\u0648\u0627\u0631\u062f.'],
    'smtpEnhanced1.6': ['\u0627\u0646\u062a\u0642\u0644 \u0627\u0644\u0645\u0633\u062a\u0644\u0645 \u062f\u0648\u0646 \u0625\u0639\u0627\u062f\u0629 \u062a\u0648\u062c\u064a\u0647', '\u0644\u0645 \u064a\u0639\u062f \u0627\u0644\u0635\u0646\u062f\u0648\u0642 \u0627\u0644\u0633\u0627\u0628\u0642 \u064a\u0642\u0628\u0644 \u0627\u0644\u0628\u0631\u064a\u062f \u0648\u0644\u064a\u0633 \u0644\u0647 \u0648\u062c\u0647\u0629 \u0625\u0639\u0627\u062f\u0629 \u062a\u0648\u062c\u064a\u0647.', '\u0627\u062d\u0635\u0644 \u0639\u0644\u0649 \u0627\u0644\u0639\u0646\u0648\u0627\u0646 \u0627\u0644\u062d\u0627\u0644\u064a \u0644\u0644\u0645\u0633\u062a\u0644\u0645 \u0648\u062d\u062f\u062b \u062c\u0647\u0627\u062a \u0627\u0644\u0627\u062a\u0635\u0627\u0644.'],
    'smtpEnhanced1.7': ['\u0635\u064a\u063a\u0629 \u0639\u0646\u0648\u0627\u0646 \u0627\u0644\u0645\u0631\u0633\u0644 \u063a\u064a\u0631 \u0635\u0627\u0644\u062d\u0629', '\u0639\u0646\u0648\u0627\u0646 \u0627\u0644\u0645\u0631\u0633\u0644 \u0641\u064a \u0627\u0644\u0645\u063a\u0644\u0641 \u063a\u064a\u0631 \u0635\u062d\u064a\u062d.', '\u0635\u062d\u062d MAIL FROM \u0648\u0625\u0639\u062f\u0627\u062f \u0627\u0644\u0645\u0631\u0633\u0644 \u0641\u064a \u0627\u0644\u062a\u0637\u0628\u064a\u0642.'],
    'smtpEnhanced1.8': ['\u0646\u0637\u0627\u0642 \u0627\u0644\u0645\u0631\u0633\u0644 \u0644\u0627 \u064a\u0633\u062a\u0642\u0628\u0644 \u0627\u0644\u0631\u0633\u0627\u0626\u0644 \u0627\u0644\u0645\u0631\u062a\u062f\u0629', '\u0627\u0644\u0646\u0637\u0627\u0642 \u063a\u064a\u0631 \u0635\u0627\u0644\u062d \u0644\u0625\u0631\u062c\u0627\u0639 \u0627\u0644\u0628\u0631\u064a\u062f. \u064a\u0633\u062a\u062e\u062f\u0645 Exchange Online \u0627\u0644\u0631\u0645\u0632 5.1.8 \u0623\u064a\u0636\u0627 \u0644\u062d\u0638\u0631 \u0645\u0631\u0633\u0644 \u0635\u0627\u062f\u0631.', '\u062a\u062d\u0642\u0642 \u0645\u0646 \u0646\u0637\u0627\u0642 \u0627\u0644\u0645\u063a\u0644\u0641 \u0648DNS. \u0639\u0646\u062f \u062d\u0638\u0631 Exchange \u0627\u0641\u062d\u0635 \u0627\u062e\u062a\u0631\u0627\u0642 \u0627\u0644\u062d\u0633\u0627\u0628 \u0648\u0627\u062a\u0628\u0639 \u0627\u0633\u062a\u0639\u0627\u062f\u0629 \u0627\u0644\u0643\u064a\u0627\u0646\u0627\u062a \u0627\u0644\u0645\u0642\u064a\u062f\u0629.'],
    'smtpEnhanced1.10': ['\u0646\u0637\u0627\u0642 \u0627\u0644\u0645\u0633\u062a\u0644\u0645 \u064a\u0646\u0634\u0631 MX \u0641\u0627\u0631\u063a\u0627', '\u0627\u0644\u0645\u0639\u0646\u0649 \u0627\u0644\u0642\u064a\u0627\u0633\u064a \u0623\u0646 \u0627\u0644\u0646\u0637\u0627\u0642 \u0644\u0627 \u064a\u0642\u0628\u0644 \u0627\u0644\u0628\u0631\u064a\u062f \u0635\u0631\u0627\u062d\u0629. \u064a\u0633\u062a\u062e\u062f\u0645 Exchange Online \u0627\u0644\u0631\u0645\u0632 \u0623\u064a\u0636\u0627 \u0639\u0646\u062f \u0639\u062f\u0645 \u0627\u0644\u0639\u062b\u0648\u0631 \u0639\u0644\u0649 \u0627\u0644\u0645\u0633\u062a\u0644\u0645 \u0641\u064a \u0627\u0644\u062f\u0644\u064a\u0644.', '\u0631\u0627\u062c\u0639 \u0627\u0644\u0645\u0632\u0648\u062f \u0648\u0627\u0644\u0631\u062f \u0627\u0644\u0643\u0627\u0645\u0644. \u0645\u0639 MX \u0641\u0627\u0631\u063a \u0627\u0633\u062a\u062e\u062f\u0645 \u0645\u0633\u062a\u0644\u0645\u0627 \u0622\u062e\u0631\u061b \u0648\u0645\u0639 Exchange \u0627\u0641\u062d\u0635 \u0627\u0644\u0635\u0646\u062f\u0648\u0642 \u0648\u0627\u0644\u0623\u0633\u0645\u0627\u0621 \u0627\u0644\u0645\u0633\u062a\u0639\u0627\u0631\u0629.'],
    'smtpEnhanced2.0': ['\u0641\u0634\u0644 \u0645\u062a\u0639\u0644\u0642 \u0628\u0635\u0646\u062f\u0648\u0642 \u0627\u0644\u0628\u0631\u064a\u062f', '\u062d\u0627\u0644\u0629 \u0641\u064a \u0627\u0644\u0635\u0646\u062f\u0648\u0642 \u0645\u0646\u0639\u062a \u0627\u0644\u062a\u0633\u0644\u064a\u0645 \u062f\u0648\u0646 \u062a\u0648\u0636\u064a\u062d \u0623\u062f\u0642.', '\u0627\u0637\u0644\u0628 \u0645\u0646 \u0627\u0644\u0645\u0633\u0624\u0648\u0644 \u0641\u062d\u0635 \u0627\u0644\u062d\u0627\u0644\u0629 \u0648\u0627\u0644\u062d\u0635\u0629 \u0648\u0642\u064a\u0648\u062f \u0627\u0644\u062a\u0633\u0644\u064a\u0645.'],
    'smtpEnhanced2.1': ['\u0635\u0646\u062f\u0648\u0642 \u0627\u0644\u0628\u0631\u064a\u062f \u0645\u0639\u0637\u0644', '\u0627\u0644\u0635\u0646\u062f\u0648\u0642 \u0645\u0648\u062c\u0648\u062f \u0644\u0643\u0646\u0647 \u0644\u0627 \u064a\u0642\u0628\u0644 \u0627\u0644\u0631\u0633\u0627\u0626\u0644.', '\u0627\u0637\u0644\u0628 \u0641\u062d\u0635 \u062d\u0627\u0644\u0629 \u0627\u0644\u062d\u0633\u0627\u0628 \u0648\u0627\u0644\u062a\u0631\u062e\u064a\u0635 \u0648\u062a\u0648\u0641\u0631 \u0627\u0644\u0635\u0646\u062f\u0648\u0642.'],
    'smtpEnhanced2.2': ['\u0627\u0644\u0635\u0646\u062f\u0648\u0642 \u0645\u0645\u062a\u0644\u0626 \u0623\u0648 \u0627\u0644\u062d\u0635\u0629 \u0645\u062a\u062c\u0627\u0648\u0632\u0629', '\u0628\u0644\u063a \u0635\u0646\u062f\u0648\u0642 \u0627\u0644\u0645\u0633\u062a\u0644\u0645 \u062d\u0635\u062a\u0647. \u0642\u062f \u064a\u0642\u0635\u062f Exchange Online \u0628\u062f\u0644\u0627 \u0645\u0646 \u0630\u0644\u0643 \u062d\u0635\u0629 \u062a\u0642\u062f\u064a\u0645 \u0627\u0644\u0631\u0633\u0627\u0626\u0644 \u0644\u0644\u0645\u0631\u0633\u0644.', '\u0644\u0644\u0635\u0646\u062f\u0648\u0642 \u0627\u0644\u0645\u0645\u062a\u0644\u0626 \u0648\u0641\u0631 \u0645\u0633\u0627\u062d\u0629 \u0623\u0648 \u0639\u062f\u0644 \u0627\u0644\u062d\u0635\u0629. \u0644\u062d\u0635\u0629 \u0627\u0644\u0625\u0631\u0633\u0627\u0644 \u0642\u0644\u0644 \u0627\u0644\u062d\u062c\u0645 \u0648\u0627\u0641\u062d\u0635 \u062d\u062f\u0648\u062f \u0627\u0644\u0645\u0632\u0648\u062f \u0648\u0623\u0645\u0627\u0646 \u0627\u0644\u062d\u0633\u0627\u0628.'],
    'smtpEnhanced2.3': ['\u062a\u062c\u0627\u0648\u0632 \u062d\u062c\u0645 \u0627\u0644\u0631\u0633\u0627\u0644\u0629 \u0627\u0644\u0645\u0633\u0645\u0648\u062d \u0644\u0644\u0635\u0646\u062f\u0648\u0642', '\u0627\u0644\u0631\u0633\u0627\u0644\u0629 \u0623\u0643\u0628\u0631 \u0645\u0646 \u062d\u062f \u0627\u0644\u062d\u062c\u0645 \u0644\u0647\u0630\u0627 \u0627\u0644\u0635\u0646\u062f\u0648\u0642.', '\u0642\u0644\u0644 \u0627\u0644\u0631\u0633\u0627\u0644\u0629 \u0648\u0627\u0644\u0645\u0631\u0641\u0642\u0627\u062a \u0645\u0639 \u062d\u0633\u0627\u0628 \u0632\u064a\u0627\u062f\u0629 \u062a\u0631\u0645\u064a\u0632 MIME \u0623\u0648 \u0627\u0633\u062a\u062e\u062f\u0645 \u0631\u0627\u0628\u0637 \u0645\u0644\u0641\u0627\u062a \u0645\u0639\u062a\u0645\u062f\u0627.'],
    'smtpEnhanced2.4': ['\u0641\u0634\u0644 \u062a\u0648\u0633\u064a\u0639 \u0627\u0644\u0642\u0627\u0626\u0645\u0629 \u0627\u0644\u0628\u0631\u064a\u062f\u064a\u0629', '\u062a\u0639\u0630\u0631 \u062a\u062d\u0648\u064a\u0644 \u0627\u0644\u0645\u062c\u0645\u0648\u0639\u0629 \u0623\u0648 \u0627\u0644\u0642\u0627\u0626\u0645\u0629 \u0625\u0644\u0649 \u0645\u0633\u062a\u0644\u0645\u064a\u0646.', '\u0627\u0637\u0644\u0628 \u0645\u0646 \u0627\u0644\u0645\u0627\u0644\u0643 \u062a\u0635\u062d\u064a\u062d \u0627\u0644\u0639\u0636\u0648\u064a\u0629 \u0623\u0648 \u0623\u062e\u0637\u0627\u0621 \u0627\u0644\u062f\u0644\u064a\u0644 \u0648\u0627\u0644\u062a\u062d\u0642\u0642 \u0645\u0646 \u062e\u062f\u0645\u0629 \u0627\u0644\u0645\u062c\u0645\u0648\u0639\u0627\u062a.'],
    'smtpEnhanced3.0': ['\u0641\u0634\u0644 \u0646\u0638\u0627\u0645 \u0627\u0644\u0628\u0631\u064a\u062f', '\u0623\u0628\u0644\u063a\u062a \u062e\u062f\u0645\u0629 \u0627\u0644\u0648\u062c\u0647\u0629 \u0639\u0646 \u0645\u0634\u0643\u0644\u0629 \u0639\u0627\u0645\u0629 \u0641\u064a \u0627\u0644\u0646\u0638\u0627\u0645.', '\u0627\u0637\u0644\u0628 \u0645\u0646 \u0645\u0633\u0624\u0648\u0644 \u0627\u0644\u0627\u0633\u062a\u0642\u0628\u0627\u0644 \u0641\u062d\u0635 \u0627\u0644\u062e\u062f\u0645\u0629 \u0648\u0627\u0644\u0637\u0648\u0627\u0628\u064a\u0631 \u0648\u062a\u0634\u062e\u064a\u0635 \u0627\u0644\u062e\u0627\u062f\u0645.'],
    'smtpEnhanced3.1': ['\u0646\u0641\u0627\u062f \u0645\u0633\u0627\u062d\u0629 \u0646\u0638\u0627\u0645 \u0627\u0644\u0628\u0631\u064a\u062f', '\u0646\u0641\u062f \u062a\u062e\u0632\u064a\u0646 \u0627\u0644\u062e\u0627\u062f\u0645 \u0627\u0644\u0645\u0634\u062a\u0631\u0643\u060c \u0648\u0644\u064a\u0633 \u0645\u062c\u0631\u062f \u062d\u0635\u0629 \u0635\u0646\u062f\u0648\u0642 \u0648\u0627\u062d\u062f.', '\u064a\u062c\u0628 \u0639\u0644\u0649 \u0645\u0633\u0624\u0648\u0644 \u0627\u0644\u0627\u0633\u062a\u0642\u0628\u0627\u0644 \u0627\u0633\u062a\u0639\u0627\u062f\u0629 \u0627\u0644\u0633\u0639\u0629. \u0627\u0633\u0645\u062d \u0628\u0627\u0644\u0645\u062d\u0627\u0648\u0644\u0627\u062a \u0628\u0641\u0648\u0627\u0635\u0644 \u0645\u062a\u0632\u0627\u064a\u062f\u0629.'],
    'smtpEnhanced3.2': ['\u0646\u0638\u0627\u0645 \u0627\u0644\u0628\u0631\u064a\u062f \u0644\u0627 \u064a\u0642\u0628\u0644 \u0627\u0644\u0631\u0633\u0627\u0626\u0644', '\u0627\u0644\u0646\u0638\u0627\u0645 \u062a\u062d\u062a \u0627\u0644\u0635\u064a\u0627\u0646\u0629 \u0623\u0648 \u0627\u0644\u0625\u063a\u0644\u0627\u0642 \u0623\u0648 \u0627\u0644\u062d\u0645\u0644 \u0627\u0644\u0632\u0627\u0626\u062f \u0623\u0648 \u064a\u0631\u0641\u0636 \u0627\u0644\u0628\u0631\u064a\u062f \u0644\u0633\u0628\u0628 \u0622\u062e\u0631.', '\u062a\u062d\u0642\u0642 \u0645\u0646 \u0627\u0644\u062e\u062f\u0645\u0629 \u0648\u062d\u062f\u0648\u062f \u0627\u0644\u0627\u062a\u0635\u0627\u0644. \u064a\u062a\u0637\u0644\u0628 \u0627\u0644\u0631\u062f \u0627\u0644\u062f\u0627\u0626\u0645 \u0625\u0635\u0644\u0627\u062d \u0627\u0644\u0633\u0628\u0628 \u0642\u0628\u0644 \u0625\u0631\u0633\u0627\u0644 \u062c\u062f\u064a\u062f.'],
    'smtpEnhanced3.3': ['\u0645\u064a\u0632\u0629 \u0628\u0631\u064a\u062f \u0645\u0637\u0644\u0648\u0628\u0629 \u063a\u064a\u0631 \u0645\u062a\u0627\u062d\u0629', '\u0644\u0627 \u062a\u062f\u0639\u0645 \u0627\u0644\u0648\u062c\u0647\u0629 \u0623\u0648 \u0627\u0644\u0628\u0648\u0627\u0628\u0629 \u0627\u0644\u0645\u064a\u0632\u0629 \u0627\u0644\u0645\u0637\u0644\u0648\u0628\u0629.', '\u0627\u0633\u062a\u062e\u062f\u0645 \u0645\u064a\u0632\u0627\u062a \u0645\u062f\u0639\u0648\u0645\u0629 \u0623\u0648 \u0627\u0637\u0644\u0628 \u062a\u0635\u062d\u064a\u062d \u0625\u0639\u062f\u0627\u062f \u0627\u0644\u0628\u0648\u0627\u0628\u0629.'],
    'smtpEnhanced3.4': ['\u062a\u062c\u0627\u0648\u0632 \u062d\u062f \u062d\u062c\u0645 \u0631\u0633\u0627\u0644\u0629 \u0627\u0644\u0646\u0638\u0627\u0645', '\u0627\u0644\u0631\u0633\u0627\u0644\u0629 \u062a\u062a\u062c\u0627\u0648\u0632 \u0627\u0644\u062d\u062c\u0645 \u0627\u0644\u0623\u0642\u0635\u0649 \u0644\u062e\u0627\u062f\u0645 \u0627\u0644\u0627\u0633\u062a\u0642\u0628\u0627\u0644.', '\u0642\u0644\u0644 \u0627\u0644\u062d\u062c\u0645 \u0628\u0639\u062f \u0627\u0644\u062a\u0631\u0645\u064a\u0632 \u0623\u0648 \u0627\u0633\u062a\u062e\u062f\u0645 \u0631\u0627\u0628\u0637\u0627 \u0645\u0639\u062a\u0645\u062f\u0627. \u0627\u0641\u062d\u0635 \u0627\u0644\u062d\u062f\u0648\u062f \u0639\u0628\u0631 \u0645\u0633\u0627\u0631 \u0627\u0644\u062a\u0633\u0644\u064a\u0645 \u0643\u0644\u0647.'],
    'smtpEnhanced3.5': ['\u0625\u0639\u062f\u0627\u062f \u0646\u0638\u0627\u0645 \u0627\u0644\u0628\u0631\u064a\u062f \u063a\u064a\u0631 \u0635\u062d\u064a\u062d', '\u0646\u0638\u0627\u0645 \u0627\u0633\u062a\u0642\u0628\u0627\u0644 \u0623\u0648 \u0646\u0638\u0627\u0645 \u0648\u0633\u064a\u0637 \u0645\u0647\u064a\u0623 \u0628\u0634\u0643\u0644 \u062e\u0627\u0637\u0626.', '\u0627\u0637\u0644\u0628 \u0645\u0631\u0627\u062c\u0639\u0629 \u0627\u0644\u0646\u0637\u0627\u0642\u0627\u062a \u0627\u0644\u0645\u0642\u0628\u0648\u0644\u0629 \u0648\u0627\u0644\u0645\u0648\u0635\u0644\u0627\u062a \u0648\u0627\u0644\u062a\u0648\u062c\u064a\u0647 \u0648\u0625\u0639\u062f\u0627\u062f \u0627\u0644\u062e\u062f\u0645\u0629.'],
    'smtpEnhanced4.0': ['\u0641\u0634\u0644 \u0627\u0644\u0634\u0628\u0643\u0629 \u0623\u0648 \u0627\u0644\u062a\u0648\u062c\u064a\u0647', '\u0623\u0628\u0644\u063a \u0639\u0646 \u0645\u0634\u0643\u0644\u0629 \u0627\u062a\u0635\u0627\u0644 \u0623\u0648 \u062a\u0648\u062c\u064a\u0647 \u062f\u0648\u0646 \u062a\u0641\u0627\u0635\u064a\u0644.', '\u062a\u062d\u0642\u0642 \u0645\u0646 MX \u0648\u0639\u0646\u0627\u0648\u064a\u0646 \u0627\u0644\u0648\u062c\u0647\u0629 \u0648\u0625\u0645\u0643\u0627\u0646\u064a\u0629 \u0627\u0644\u0648\u0635\u0648\u0644 \u0648\u0645\u0633\u0627\u0631\u0627\u062a \u0627\u0644\u0628\u0631\u064a\u062f.'],
    'smtpEnhanced4.1': ['\u0645\u0636\u064a\u0641 \u0627\u0644\u0648\u062c\u0647\u0629 \u0644\u0645 \u064a\u0633\u062a\u062c\u0628', '\u0642\u062f \u064a\u0643\u0648\u0646 \u0627\u0644\u0645\u0636\u064a\u0641 \u0645\u062a\u0648\u0642\u0641\u0627 \u0623\u0648 \u0645\u062d\u0645\u0644\u0627 \u0623\u0648 \u0645\u062d\u062c\u0648\u0628\u0627 \u0628\u062c\u062f\u0627\u0631 \u062d\u0645\u0627\u064a\u0629.', '\u062a\u062d\u0642\u0642 \u0645\u0646 \u0645\u0633\u062a\u0645\u0639 SMTP \u0648\u0623\u0647\u062f\u0627\u0641 MX \u0648\u0642\u0648\u0627\u0639\u062f \u062c\u062f\u0627\u0631 \u0627\u0644\u062d\u0645\u0627\u064a\u0629 \u0645\u0639 \u0645\u0633\u0624\u0648\u0644 \u0627\u0644\u0627\u0633\u062a\u0642\u0628\u0627\u0644.'],
    'smtpEnhanced4.2': ['\u0641\u0634\u0644 \u0627\u0644\u0627\u062a\u0635\u0627\u0644 \u0623\u062b\u0646\u0627\u0621 \u0627\u0644\u062a\u0633\u0644\u064a\u0645', '\u062a\u0623\u0633\u0633 \u0627\u0644\u0627\u062a\u0635\u0627\u0644 \u0644\u0643\u0646\u0647 \u0627\u0646\u0642\u0637\u0639 \u0623\u0648 \u0627\u0646\u062a\u0647\u062a \u0645\u0647\u0644\u062a\u0647 \u0642\u0628\u0644 \u0625\u0643\u0645\u0627\u0644 \u0627\u0644\u0645\u0639\u0627\u0645\u0644\u0629.', '\u062a\u062d\u0642\u0642 \u0645\u0646 \u0627\u0633\u062a\u0642\u0631\u0627\u0631 \u0627\u0644\u0634\u0628\u0643\u0629 \u0648\u0645\u0647\u0644 SMTP \u0648\u0623\u062e\u0637\u0627\u0621 TLS \u0648\u062d\u0627\u0644\u0629 \u0627\u0644\u0645\u0633\u062a\u0644\u0645.'],
    'smtpEnhanced4.3': ['\u0627\u0644\u062f\u0644\u064a\u0644 \u0623\u0648 DNS \u063a\u064a\u0631 \u0645\u062a\u0627\u062d', '\u0641\u0634\u0644 \u0628\u062d\u062b \u0641\u064a \u0627\u0644\u062f\u0644\u064a\u0644 \u0623\u0648 DNS \u0644\u0627\u0632\u0645 \u0644\u0644\u062a\u0648\u062c\u064a\u0647.', '\u0627\u0641\u062d\u0635 DNS \u0627\u0644\u0645\u0648\u062b\u0648\u0642 \u0648\u0627\u0644\u0645\u062d\u0644\u0644\u0627\u062a \u0648DNSSEC \u0648\u062a\u0648\u0641\u0631 \u0627\u0644\u062f\u0644\u064a\u0644.'],
    'smtpEnhanced4.4': ['\u0644\u0627 \u064a\u0648\u062c\u062f \u0645\u0633\u0627\u0631 \u0628\u0631\u064a\u062f \u0635\u0627\u0644\u062d', '\u062a\u0639\u0630\u0631 \u062a\u062d\u062f\u064a\u062f \u0627\u0644\u062e\u0627\u062f\u0645 \u0627\u0644\u062a\u0627\u0644\u064a \u0623\u0648 \u0627\u0644\u0645\u0633\u0627\u0631 \u0627\u0644\u0645\u0647\u064a\u0623 \u063a\u064a\u0631 \u0635\u0627\u0644\u062d.', '\u0631\u0627\u062c\u0639 MX \u0648A/AAAA \u0648\u0627\u0644\u0646\u0637\u0627\u0642\u0627\u062a \u0627\u0644\u0645\u0642\u0628\u0648\u0644\u0629 \u0648\u0645\u0633\u0627\u0631\u0627\u062a \u0627\u0644\u0645\u0648\u0635\u0644\u0627\u062a \u0648\u0627\u0644\u0645\u0636\u064a\u0641 \u0627\u0644\u0630\u0643\u064a.'],
    'smtpEnhanced4.5': ['\u0627\u0632\u062f\u062d\u0627\u0645 \u0646\u0638\u0627\u0645 \u0627\u0644\u0628\u0631\u064a\u062f', '\u0627\u0644\u0637\u0648\u0627\u0628\u064a\u0631 \u0623\u0648 \u0642\u062f\u0631\u0629 \u0627\u0644\u062a\u0633\u0644\u064a\u0645 \u062a\u062d\u062a \u0636\u063a\u0637 \u0632\u0627\u0626\u062f.', '\u0642\u0644\u0644 \u0627\u0644\u062a\u0632\u0627\u0645\u0646 \u0648\u0645\u0639\u062f\u0644 \u0627\u0644\u0625\u0631\u0633\u0627\u0644 \u0648\u062f\u0639 \u0627\u0644\u062e\u062f\u0645\u0629 \u062a\u0639\u0627\u0644\u062c \u0627\u0644\u0637\u0648\u0627\u0628\u064a\u0631.'],
    'smtpEnhanced4.6': ['\u062d\u0644\u0642\u0629 \u062a\u0648\u062c\u064a\u0647 \u0628\u0631\u064a\u062f', '\u062a\u0639\u064a\u062f \u0627\u0644\u0642\u0648\u0627\u0639\u062f \u0623\u0648 \u0627\u0644\u0645\u0648\u0635\u0644\u0627\u062a \u0627\u0644\u0631\u0633\u0627\u0644\u0629 \u0639\u0628\u0631 \u0627\u0644\u0623\u0646\u0638\u0645\u0629 \u0646\u0641\u0633\u0647\u0627 \u0645\u0631\u0627\u0631\u0627.', '\u062a\u062a\u0628\u0639 \u0627\u0644\u0642\u0641\u0632\u0627\u062a \u0648\u0627\u062d\u0630\u0641 \u0625\u0639\u0627\u062f\u0629 \u0627\u0644\u062a\u0648\u062c\u064a\u0647 \u0627\u0644\u062f\u0627\u0626\u0631\u064a\u0629 \u0623\u0648 \u0645\u0633\u0627\u0631 \u0627\u0644\u0645\u0648\u0635\u0644 \u0627\u0644\u0645\u062a\u0643\u0631\u0631.'],
    'smtpEnhanced4.7': ['\u0627\u0646\u062a\u0647\u062a \u0645\u062f\u0629 \u0627\u0644\u062a\u0633\u0644\u064a\u0645', '\u0628\u0642\u064a\u062a \u0627\u0644\u0631\u0633\u0627\u0644\u0629 \u062f\u0648\u0646 \u062a\u0633\u0644\u064a\u0645 \u062d\u062a\u0649 \u0627\u0646\u062a\u0647\u062a \u0645\u062f\u0629 \u0628\u0642\u0627\u0626\u0647\u0627 \u0641\u064a \u0627\u0644\u0637\u0627\u0628\u0648\u0631.', '\u0627\u0641\u062d\u0635 \u0627\u0644\u0623\u062e\u0637\u0627\u0621 \u0627\u0644\u0633\u0627\u0628\u0642\u0629 \u0648\u0623\u0635\u0644\u062d \u0627\u0644\u0633\u0628\u0628. \u0627\u0644\u0631\u0633\u0627\u0644\u0629 \u0627\u0644\u0645\u0646\u062a\u0647\u064a\u0629 \u0644\u0627 \u062a\u0639\u0627\u062f \u062a\u0644\u0642\u0627\u0626\u064a\u0627 \u0648\u0642\u062f \u062a\u062a\u0637\u0644\u0628 \u0625\u0631\u0633\u0627\u0644\u0627 \u062c\u062f\u064a\u062f\u0627.'],
    'smtpEnhanced5.0': ['\u0641\u0634\u0644 \u0628\u0631\u0648\u062a\u0648\u0643\u0648\u0644 \u0627\u0644\u0628\u0631\u064a\u062f', '\u0641\u0634\u0644 \u062a\u0628\u0627\u062f\u0644 SMTP \u062f\u0648\u0646 \u062a\u0641\u0627\u0635\u064a\u0644 \u0628\u0631\u0648\u062a\u0648\u0643\u0648\u0644 \u0623\u062f\u0642.', '\u0631\u0627\u062c\u0639 \u062a\u0633\u0644\u0633\u0644 SMTP \u0641\u064a \u0627\u0644\u0639\u0645\u064a\u0644 \u0648\u062a\u0648\u0636\u064a\u062d \u062c\u0647\u0629 \u0627\u0644\u0627\u0633\u062a\u0642\u0628\u0627\u0644.'],
    'smtpEnhanced5.1': ['\u0623\u0645\u0631 \u063a\u064a\u0631 \u0635\u0627\u0644\u062d \u0623\u0648 \u062e\u0627\u0631\u062c \u0627\u0644\u062a\u0631\u062a\u064a\u0628', '\u0627\u0644\u0623\u0645\u0631 \u063a\u064a\u0631 \u0645\u062f\u0639\u0648\u0645 \u0623\u0648 \u0623\u0631\u0633\u0644 \u0641\u064a \u062d\u0627\u0644\u0629 SMTP \u062e\u0627\u0637\u0626\u0629.', '\u062a\u062d\u0642\u0642 \u0645\u0646 \u0627\u0644\u062a\u0633\u0644\u0633\u0644 \u0648\u0625\u0645\u0643\u0627\u0646\u0627\u062a \u0627\u0644\u062e\u0627\u062f\u0645 \u0627\u0644\u0645\u0639\u0644\u0646\u0629.'],
    'smtpEnhanced5.2': ['\u062e\u0637\u0623 \u0635\u064a\u0627\u063a\u0629 SMTP', '\u062a\u0639\u0630\u0631 \u0639\u0644\u0649 \u0627\u0644\u0645\u0633\u062a\u0644\u0645 \u062a\u062d\u0644\u064a\u0644 \u0623\u062d\u062f \u0627\u0644\u0623\u0648\u0627\u0645\u0631.', '\u0635\u062d\u062d \u062a\u0646\u0633\u064a\u0642 \u0627\u0644\u0623\u0645\u0631 \u0648\u062d\u062f\u062b \u0645\u0643\u062a\u0628\u0629 \u0639\u0645\u064a\u0644 SMTP.'],
    'smtpEnhanced5.3': ['\u0639\u062f\u062f \u0627\u0644\u0645\u0633\u062a\u0644\u0645\u064a\u0646 \u0643\u0628\u064a\u0631 \u062c\u062f\u0627', '\u062a\u062a\u062c\u0627\u0648\u0632 \u0627\u0644\u0645\u0639\u0627\u0645\u0644\u0629 \u062d\u062f \u0627\u0644\u0645\u0633\u062a\u0644\u0645\u064a\u0646 \u0644\u062e\u062f\u0645\u0629 \u0627\u0644\u0627\u0633\u062a\u0642\u0628\u0627\u0644.', '\u0642\u0633\u0645 \u0627\u0644\u0642\u0627\u0626\u0645\u0629 \u0648\u0641\u0642\u0627 \u0644\u062d\u062f\u0648\u062f \u0627\u0644\u0645\u0632\u0648\u062f. \u0644\u0627 \u062a\u0639\u0627\u0648\u062f \u0627\u0644\u0625\u0631\u0633\u0627\u0644 \u0625\u0644\u0649 \u0645\u0633\u062a\u0644\u0645\u064a\u0646 \u062a\u0645 \u0642\u0628\u0648\u0644\u0647\u0645 \u0628\u0627\u0644\u0641\u0639\u0644.'],
    'smtpEnhanced5.4': ['\u0648\u0633\u064a\u0637\u0627\u062a SMTP \u063a\u064a\u0631 \u0635\u0627\u0644\u062d\u0629', '\u064a\u062d\u062a\u0648\u064a \u0623\u0645\u0631 \u0645\u0639\u0631\u0648\u0641 \u0639\u0644\u0649 \u0648\u0633\u064a\u0637\u0627\u062a \u062e\u0627\u0637\u0626\u0629 \u0623\u0648 \u063a\u064a\u0631 \u0645\u062f\u0639\u0648\u0645\u0629.', '\u0635\u062d\u062d \u0639\u0646\u0627\u0648\u064a\u0646 \u0627\u0644\u0645\u063a\u0644\u0641 \u0648\u0627\u0633\u062a\u062e\u062f\u0645 \u0627\u0644\u0627\u0645\u062a\u062f\u0627\u062f\u0627\u062a \u0627\u0644\u0645\u062a\u0641\u0627\u0648\u0636 \u0639\u0644\u064a\u0647\u0627 \u0641\u0642\u0637.'],
    'smtpEnhanced5.5': ['\u0639\u062f\u0645 \u062a\u0637\u0627\u0628\u0642 \u0625\u0635\u062f\u0627\u0631 \u0627\u0644\u0628\u0631\u0648\u062a\u0648\u0643\u0648\u0644', '\u0644\u0627 \u062a\u062a\u0641\u0642 \u0627\u0644\u0623\u0646\u0638\u0645\u0629 \u0639\u0644\u0649 \u0645\u064a\u0632\u0627\u062a \u0627\u0644\u0628\u0631\u0648\u062a\u0648\u0643\u0648\u0644 \u0627\u0644\u0645\u0637\u0644\u0648\u0628\u0629.', '\u062d\u062f\u062b \u0627\u0644\u0639\u0645\u064a\u0644 \u0623\u0648 \u0627\u0644\u0628\u0648\u0627\u0628\u0629 \u0648\u062a\u062d\u0642\u0642 \u0645\u0646 \u0627\u0644\u062a\u0648\u0627\u0641\u0642.'],
    'smtpEnhanced6.0': ['\u0645\u0634\u0643\u0644\u0629 \u0641\u064a \u0627\u0644\u0645\u062d\u062a\u0648\u0649 \u0623\u0648 \u0627\u0644\u062a\u0631\u0645\u064a\u0632', '\u0645\u0646\u0639 \u062a\u0645\u062b\u064a\u0644 \u0627\u0644\u0645\u062d\u062a\u0648\u0649 \u0645\u0639\u0627\u0644\u062c\u0629 \u0627\u0644\u0631\u0633\u0627\u0644\u0629.', '\u062a\u062d\u0642\u0642 \u0645\u0646 \u0631\u0624\u0648\u0633 MIME \u0648\u0627\u0644\u062a\u0631\u0645\u064a\u0632 \u0648\u0627\u0644\u0645\u0631\u0641\u0642\u0627\u062a \u0627\u0633\u062a\u0646\u0627\u062f\u0627 \u0644\u0644\u062a\u0634\u062e\u064a\u0635 \u0627\u0644\u0623\u0635\u0644\u064a.'],
    'smtpEnhanced6.1': ['\u0646\u0648\u0639 \u0645\u062d\u062a\u0648\u0649 \u063a\u064a\u0631 \u0645\u062f\u0639\u0648\u0645', '\u0644\u0627 \u064a\u062f\u0639\u0645 \u0646\u0638\u0627\u0645 \u0627\u0644\u0627\u0633\u062a\u0642\u0628\u0627\u0644 \u0646\u0648\u0639 \u0627\u0644\u0645\u062d\u062a\u0648\u0649 \u0623\u0648 \u0627\u0644\u062a\u0631\u0645\u064a\u0632.', '\u0627\u0633\u062a\u062e\u062f\u0645 \u0623\u0646\u0648\u0627\u0639 MIME \u0648\u062a\u0631\u0645\u064a\u0632\u0627 \u0645\u062f\u0639\u0648\u0645\u064a\u0646 \u0623\u0648 \u0631\u0627\u0628\u0637 \u0645\u0644\u0641\u0627\u062a \u0645\u0639\u062a\u0645\u062f\u0627.'],
    'smtpEnhanced6.2': ['\u0627\u0644\u062a\u062d\u0648\u064a\u0644 \u0627\u0644\u0645\u0637\u0644\u0648\u0628 \u0645\u062d\u0638\u0648\u0631', '\u0627\u0644\u062a\u0633\u0644\u064a\u0645 \u064a\u062d\u062a\u0627\u062c \u062a\u062d\u0648\u064a\u0644\u0627 \u062a\u0645\u0646\u0639\u0647 \u0627\u0644\u0633\u064a\u0627\u0633\u0629.', '\u0623\u0631\u0633\u0644 \u0628\u062a\u0646\u0633\u064a\u0642 \u0645\u062f\u0639\u0648\u0645 \u0623\u0648 \u0627\u0637\u0644\u0628 \u0645\u0646 \u0627\u0644\u0645\u0633\u0624\u0648\u0644 \u0645\u0631\u0627\u062c\u0639\u0629 \u0627\u0644\u0633\u064a\u0627\u0633\u0629 \u0627\u0644\u0645\u0639\u0646\u064a\u0629.'],
    'smtpEnhanced6.3': ['\u0627\u0644\u062a\u062d\u0648\u064a\u0644 \u0627\u0644\u0645\u0637\u0644\u0648\u0628 \u063a\u064a\u0631 \u0645\u062a\u0627\u062d', '\u0644\u0627 \u062a\u0633\u062a\u0637\u064a\u0639 \u0627\u0644\u0628\u0648\u0627\u0628\u0629 \u062a\u062d\u0648\u064a\u0644 \u0627\u0644\u0631\u0633\u0627\u0644\u0629 \u0644\u0644\u0642\u0641\u0632\u0629 \u0627\u0644\u062a\u0627\u0644\u064a\u0629.', '\u0623\u0646\u0634\u0626 MIME \u0645\u062a\u0648\u0627\u0641\u0642\u0627 \u0648\u062a\u062d\u0642\u0642 \u0645\u0646 \u0642\u062f\u0631\u0627\u062a \u062a\u0631\u0645\u064a\u0632 \u0627\u0644\u0628\u0648\u0627\u0628\u0629.'],
    'smtpEnhanced6.5': ['\u0641\u0634\u0644 \u062a\u062d\u0648\u064a\u0644 \u0627\u0644\u0631\u0633\u0627\u0644\u0629', '\u062a\u0639\u0630\u0631 \u0625\u0643\u0645\u0627\u0644 \u062a\u062d\u0648\u064a\u0644 \u0645\u062d\u062a\u0648\u0649 \u0636\u0631\u0648\u0631\u064a.', '\u0631\u0627\u062c\u0639 \u0627\u0644\u062a\u0631\u0645\u064a\u0632 \u0648\u0623\u062e\u0637\u0627\u0621 \u0627\u0644\u0628\u0648\u0627\u0628\u0629 \u0627\u0644\u062a\u064a \u062a\u062c\u0631\u064a \u0627\u0644\u062a\u062d\u0648\u064a\u0644.'],
    'smtpEnhanced6.7': ['\u0627\u0644\u0639\u0646\u0648\u0627\u0646 \u0627\u0644\u062f\u0648\u0644\u064a \u063a\u064a\u0631 \u0645\u062f\u0639\u0648\u0645', '\u0627\u0644\u0645\u0633\u0627\u0631 \u0644\u0627 \u064a\u0633\u0645\u062d \u0628\u0639\u0646\u0627\u0648\u064a\u0646 \u0645\u063a\u0644\u0641 \u062a\u062d\u062a\u0648\u064a \u0623\u062d\u0631\u0641\u0627 \u063a\u064a\u0631 ASCII.', '\u0627\u0633\u062a\u062e\u062f\u0645 \u0645\u0633\u0627\u0631\u0627 \u064a\u062f\u0639\u0645 SMTPUTF8 \u0623\u0648 \u0627\u0633\u0645\u0627 \u0645\u0633\u062a\u0639\u0627\u0631\u0627 ASCII \u062d\u0642\u064a\u0642\u064a\u0627 \u064a\u0642\u062f\u0645\u0647 \u0627\u0644\u0645\u0633\u062a\u0644\u0645. \u0644\u0627 \u062a\u062d\u0630\u0641 \u0623\u062d\u0631\u0641 \u0627\u0644\u0639\u0646\u0648\u0627\u0646 \u0628\u0628\u0633\u0627\u0637\u0629.'],
    'smtpEnhanced6.8': ['\u0627\u0633\u062a\u062c\u0627\u0628\u0629 UTF-8 \u063a\u064a\u0631 \u0645\u062a\u0627\u062d\u0629 \u0644\u0647\u0630\u0627 \u0627\u0644\u0639\u0645\u064a\u0644', '\u064a\u062d\u062a\u0627\u062c \u0627\u0644\u062e\u0627\u062f\u0645 \u0625\u0644\u0649 \u0631\u062f UTF-8 \u0644\u0645 \u064a\u062a\u0641\u0627\u0648\u0636 \u0639\u0644\u064a\u0647 \u0627\u0644\u0639\u0645\u064a\u0644.', '\u0627\u0633\u062a\u062e\u062f\u0645 \u0639\u0645\u064a\u0644\u0627 \u064a\u062f\u0639\u0645 SMTPUTF8 \u0648\u0645\u0633\u0627\u0631 \u0628\u0631\u064a\u062f \u0645\u062a\u0648\u0627\u0641\u0642\u0627.'],
    'smtpEnhanced6.9': ['\u0631\u0633\u0627\u0644\u0629 UTF-8 \u0644\u0627 \u062a\u0635\u0644 \u0644\u0643\u0644 \u0627\u0644\u0645\u0633\u062a\u0644\u0645\u064a\u0646', '\u0644\u0627 \u064a\u0645\u0644\u0643 \u0628\u0639\u0636 \u0627\u0644\u0645\u0633\u062a\u0644\u0645\u064a\u0646 \u0645\u0633\u0627\u0631\u0627 \u064a\u062f\u0639\u0645 SMTPUTF8.', '\u062a\u062d\u0642\u0642 \u0645\u0646 \u062f\u0639\u0645 SMTPUTF8 \u0639\u0628\u0631 \u0627\u0644\u0645\u0633\u0627\u0631 \u0643\u0644\u0647 \u0648\u0627\u0633\u062a\u062e\u062f\u0645 \u0623\u0633\u0645\u0627\u0621 \u0645\u0633\u062a\u0639\u0627\u0631\u0629 \u0645\u062a\u0648\u0627\u0641\u0642\u0629 \u0645\u0624\u0643\u062f\u0629 \u0625\u0646 \u062a\u0648\u0641\u0631\u062a.'],
    'smtpEnhanced7.0': ['\u0641\u0634\u0644 \u0623\u0645\u0627\u0646 \u0623\u0648 \u0633\u064a\u0627\u0633\u0629 \u063a\u064a\u0631 \u0645\u062d\u062f\u062f', '\u0645\u0646\u0639 \u0642\u064a\u062f \u0623\u0645\u0646\u064a \u0623\u0648 \u0645\u0634\u0643\u0644\u0629 \u0645\u0635\u0627\u062f\u0642\u0629 \u0623\u0648 \u062a\u0635\u0641\u064a\u0629 \u0627\u0644\u0625\u062c\u0631\u0627\u0621.', '\u0627\u0642\u0631\u0623 \u0627\u0644\u0631\u062f \u0627\u0644\u0643\u0627\u0645\u0644 \u0648\u0627\u0637\u0644\u0628 \u0645\u0646 \u0627\u0644\u0645\u0633\u0624\u0648\u0644 \u0641\u062d\u0635 \u0627\u0644\u0645\u0635\u0627\u062f\u0642\u0629 \u0648\u0642\u0631\u0627\u0631\u0627\u062a \u0627\u0644\u0633\u064a\u0627\u0633\u0629.'],
    'smtpEnhanced7.1': ['\u0627\u0644\u062a\u0633\u0644\u064a\u0645 \u0645\u0642\u064a\u062f \u0628\u0633\u064a\u0627\u0633\u0629', '\u0642\u062f \u062a\u0643\u0648\u0646 \u0627\u0644\u0623\u0633\u0628\u0627\u0628 \u0631\u0641\u0636 \u0627\u0644\u062a\u0631\u062d\u064a\u0644 \u0623\u0648 \u0642\u064a\u0648\u062f \u0627\u0644\u0645\u0633\u062a\u0644\u0645 \u0623\u0648 \u0627\u0644\u062a\u0635\u0641\u064a\u0629 \u0623\u0648 \u063a\u064a\u0627\u0628 \u0627\u0644\u0645\u0635\u0627\u062f\u0642\u0629. \u0627\u0644\u0631\u062f \u0627\u0644\u0645\u0624\u0642\u062a \u0642\u062f \u064a\u0634\u064a\u0631 \u0644\u0642\u0627\u0626\u0645\u0629 \u0631\u0645\u0627\u062f\u064a\u0629.', '\u0631\u0627\u062c\u0639 \u0646\u0642\u0637\u0629 SMTP \u0648\u0627\u0644\u0645\u0635\u0627\u062f\u0642\u0629 \u0648\u0627\u0644\u0623\u0630\u0648\u0646\u0627\u062a \u0648\u0627\u0644\u0633\u0645\u0639\u0629. \u0627\u0633\u0623\u0644 \u0639\u0646 \u0627\u0644\u0633\u064a\u0627\u0633\u0629 \u0627\u0644\u0645\u062d\u062f\u062f\u0629 \u0648\u0644\u0627 \u062a\u0639\u0637\u0644 \u0648\u0633\u0627\u0626\u0644 \u0627\u0644\u062d\u0645\u0627\u064a\u0629 \u0639\u0645\u0648\u0645\u0627.'],
    'smtpEnhanced7.2': ['\u0627\u0644\u0625\u0631\u0633\u0627\u0644 \u0644\u0647\u0630\u0647 \u0627\u0644\u0642\u0627\u0626\u0645\u0629 \u063a\u064a\u0631 \u0645\u0633\u0645\u0648\u062d', '\u0627\u0644\u0645\u0631\u0633\u0644 \u063a\u064a\u0631 \u0645\u062e\u0648\u0644 \u0644\u0627\u0633\u062a\u062e\u062f\u0627\u0645 \u0627\u0644\u0642\u0627\u0626\u0645\u0629 \u0627\u0644\u0628\u0631\u064a\u062f\u064a\u0629.', '\u0627\u0637\u0644\u0628 \u0645\u0648\u0627\u0641\u0642\u0629 \u0645\u0627\u0644\u0643 \u0627\u0644\u0642\u0627\u0626\u0645\u0629 \u0623\u0648 \u0627\u0633\u062a\u062e\u062f\u0645 \u0639\u0646\u0648\u0627\u0646\u0627 \u0645\u0635\u0631\u062d\u0627 \u0628\u0647.'],
    'smtpEnhanced7.3': ['\u062a\u062d\u0648\u064a\u0644 \u0627\u0644\u0631\u0633\u0627\u0644\u0629 \u0627\u0644\u0622\u0645\u0646\u0629 \u063a\u064a\u0631 \u0645\u062a\u0627\u062d', '\u062a\u0639\u062c\u0632 \u0627\u0644\u0628\u0648\u0627\u0628\u0629 \u0639\u0646 \u0625\u062c\u0631\u0627\u0621 \u062a\u062d\u0648\u064a\u0644 \u0622\u0645\u0646 \u0645\u0637\u0644\u0648\u0628.', '\u0627\u0633\u062a\u062e\u062f\u0645 \u062a\u0646\u0633\u064a\u0642 \u0631\u0633\u0627\u0644\u0629 \u0622\u0645\u0646\u0627 \u064a\u062f\u0639\u0645\u0647 \u0627\u0644\u0637\u0631\u0641\u0627\u0646 \u0648\u0627\u0633\u062a\u0634\u0631 \u0627\u0644\u0645\u0633\u0624\u0648\u0644.'],
    'smtpEnhanced7.4': ['\u0645\u064a\u0632\u0629 \u0623\u0645\u0627\u0646 \u063a\u064a\u0631 \u0645\u062f\u0639\u0648\u0645\u0629', '\u0644\u0627 \u064a\u062f\u0639\u0645 \u0646\u0638\u0627\u0645 \u0627\u0644\u0627\u0633\u062a\u0642\u0628\u0627\u0644 \u0645\u064a\u0632\u0629 \u0627\u0644\u0623\u0645\u0627\u0646 \u0627\u0644\u0645\u0637\u0644\u0648\u0628\u0629.', '\u0627\u0633\u062a\u062e\u062f\u0645 \u0637\u0631\u064a\u0642\u0629 \u0645\u0635\u0627\u062f\u0642\u0629 \u0623\u0648 \u0631\u0633\u0627\u0644\u0629 \u0622\u0645\u0646\u0629 \u0645\u062f\u0639\u0648\u0645\u0629 \u062f\u0648\u0646 \u0625\u0636\u0639\u0627\u0641 \u062d\u0645\u0627\u064a\u0629 \u0627\u0644\u0646\u0642\u0644.'],
    'smtpEnhanced7.5': ['\u0641\u0634\u0644 \u0627\u0644\u062a\u062d\u0642\u0642 \u0627\u0644\u062a\u0634\u0641\u064a\u0631\u064a', '\u0645\u0641\u062a\u0627\u062d \u0623\u0648 \u0634\u0647\u0627\u062f\u0629 \u0645\u0637\u0644\u0648\u0628\u0629 \u0645\u0641\u0642\u0648\u062f\u0629 \u0623\u0648 \u063a\u064a\u0631 \u0635\u0627\u0644\u062d\u0629. \u0642\u062f \u064a\u0633\u062a\u062e\u062f\u0645 \u0627\u0644\u0645\u0632\u0648\u062f \u0627\u0644\u0631\u0645\u0632 \u0644\u0641\u062d\u0635 \u0634\u0647\u0627\u062f\u0627\u062a TLS \u0623\u0648 MTA-STS.', '\u062a\u062d\u0642\u0642 \u0645\u0646 \u0627\u0644\u0635\u0644\u0627\u062d\u064a\u0629 \u0648\u0623\u0633\u0645\u0627\u0621 \u0627\u0644\u0645\u0636\u064a\u0641\u064a\u0646 \u0648\u0633\u0644\u0633\u0644\u0629 \u0627\u0644\u062b\u0642\u0629 \u0648\u0633\u064a\u0627\u0633\u0629 \u0623\u0645\u0627\u0646 \u0627\u0644\u0631\u0633\u0627\u0644\u0629 \u0623\u0648 \u0627\u0644\u0646\u0642\u0644.'],
    'smtpEnhanced7.6': ['\u062e\u0648\u0627\u0631\u0632\u0645\u064a\u0629 \u062a\u0634\u0641\u064a\u0631 \u063a\u064a\u0631 \u0645\u062f\u0639\u0648\u0645\u0629', '\u0644\u0627 \u064a\u062f\u0639\u0645 \u0627\u0644\u0637\u0631\u0641\u0627\u0646 \u062e\u0648\u0627\u0631\u0632\u0645\u064a\u0629 \u0645\u0634\u062a\u0631\u0643\u0629 \u0645\u0637\u0644\u0648\u0628\u0629.', '\u062d\u062f\u062b \u0627\u0644\u0623\u0646\u0638\u0645\u0629 \u0648\u0627\u062e\u062a\u0631 \u062e\u0648\u0627\u0631\u0632\u0645\u064a\u0629 \u0622\u0645\u0646\u0629 \u064a\u062f\u0639\u0645\u0647\u0627 \u0627\u0644\u0637\u0631\u0641\u0627\u0646.'],
    'smtpEnhanced7.7': ['\u0641\u0634\u0644 \u0627\u0644\u062a\u062d\u0642\u0642 \u0645\u0646 \u0633\u0644\u0627\u0645\u0629 \u0627\u0644\u0631\u0633\u0627\u0644\u0629', '\u062a\u063a\u064a\u0631 \u0627\u0644\u0645\u062d\u062a\u0648\u0649 \u0623\u0648 \u0641\u0634\u0644 \u0641\u062d\u0635 \u0633\u0644\u0627\u0645\u0629 \u062a\u0634\u0641\u064a\u0631\u064a.', '\u062d\u062f\u062f \u062a\u0639\u062f\u064a\u0644\u0627\u062a \u0627\u0644\u0628\u0648\u0627\u0628\u0627\u062a \u0623\u0648 \u0625\u0639\u0627\u062f\u0629 \u0627\u0644\u062a\u0648\u062c\u064a\u0647 \u0648\u062a\u062d\u0642\u0642 \u0645\u0646 \u0625\u0639\u062f\u0627\u062f \u0627\u0644\u062a\u0648\u0642\u064a\u0639.'],
    'smtpEnhanced7.8': ['\u0631\u0641\u0636 \u0628\u064a\u0627\u0646\u0627\u062a \u0627\u0639\u062a\u0645\u0627\u062f \u0627\u0644\u0645\u0635\u0627\u062f\u0642\u0629', '\u0627\u0633\u062a\u062e\u062f\u0645 AUTH \u0628\u064a\u0627\u0646\u0627\u062a \u0627\u0639\u062a\u0645\u0627\u062f \u063a\u064a\u0631 \u0635\u0627\u0644\u062d\u0629 \u0623\u0648 \u063a\u064a\u0631 \u0643\u0627\u0641\u064a\u0629.', '\u062a\u062d\u0642\u0642 \u0645\u0646 \u0627\u0644\u062d\u0633\u0627\u0628 \u0648OAuth \u0623\u0648 \u0627\u0644\u0637\u0631\u064a\u0642\u0629 \u0627\u0644\u0645\u062f\u0639\u0648\u0645\u0629 \u0648\u0623\u0630\u0648\u0646\u0627\u062a \u0627\u0644\u062a\u0637\u0628\u064a\u0642 \u0648\u0625\u0639\u062f\u0627\u062f\u0627\u062a \u0627\u0644\u062e\u062f\u0645\u0629.'],
    'smtpEnhanced7.9': ['\u0637\u0631\u064a\u0642\u0629 \u0645\u0635\u0627\u062f\u0642\u0629 \u0636\u0639\u064a\u0641\u0629', '\u0627\u0644\u0622\u0644\u064a\u0629 \u0627\u0644\u0645\u062e\u062a\u0627\u0631\u0629 \u0644\u0627 \u062a\u0644\u0628\u064a \u0633\u064a\u0627\u0633\u0629 \u0627\u0644\u0645\u0633\u062a\u0644\u0645.', '\u0627\u0633\u062a\u062e\u062f\u0645 \u0637\u0631\u064a\u0642\u0629 \u0623\u0642\u0648\u0649 \u064a\u0639\u0644\u0646\u0647\u0627 \u0627\u0644\u062e\u0627\u062f\u0645 \u0648\u0623\u0628\u0642 TLS \u0645\u0641\u0639\u0644\u0627.'],
    'smtpEnhanced7.10': ['\u064a\u0644\u0632\u0645 \u0627\u062a\u0635\u0627\u0644 \u0645\u0634\u0641\u0631', '\u062a\u062a\u0637\u0644\u0628 \u0622\u0644\u064a\u0629 \u0627\u0644\u0645\u0635\u0627\u062f\u0642\u0629 \u0637\u0628\u0642\u0629 \u062e\u0635\u0648\u0635\u064a\u0629 \u0623\u0642\u0648\u0649.', '\u0623\u0646\u0634\u0626 TLS \u0642\u0628\u0644 \u0627\u0644\u0645\u0635\u0627\u062f\u0642\u0629 \u0623\u0648 \u0627\u0633\u062a\u062e\u062f\u0645 \u0622\u0644\u064a\u0629 \u0623\u0642\u0648\u0649 \u0645\u062f\u0639\u0648\u0645\u0629.'],
    'smtpEnhanced7.11': ['\u0627\u0644\u062a\u0634\u0641\u064a\u0631 \u0625\u0644\u0632\u0627\u0645\u064a \u0644\u0644\u0645\u0635\u0627\u062f\u0642\u0629', '\u0644\u0627 \u064a\u0645\u0643\u0646 \u0627\u0633\u062a\u062e\u062f\u0627\u0645 \u0627\u0644\u0637\u0631\u064a\u0642\u0629 \u0639\u0644\u0649 \u0627\u062a\u0635\u0627\u0644 \u063a\u064a\u0631 \u0645\u0634\u0641\u0631.', '\u0627\u0636\u0628\u0637 STARTTLS \u0623\u0648 \u0646\u0642\u0637\u0629 TLS \u0627\u0644\u0645\u0648\u062b\u0642\u0629 \u0642\u0628\u0644 \u0627\u0644\u0645\u0635\u0627\u062f\u0642\u0629.'],
    'smtpEnhanced7.12': ['\u0627\u0646\u062a\u0642\u0627\u0644 \u0627\u0644\u062d\u0633\u0627\u0628 \u0644\u0644\u0645\u0635\u0627\u062f\u0642\u0629 \u0645\u0637\u0644\u0648\u0628', '\u064a\u062c\u0628 \u0646\u0642\u0644 \u0627\u0644\u062d\u0633\u0627\u0628 \u0642\u0628\u0644 \u0627\u0633\u062a\u062e\u062f\u0627\u0645 \u0622\u0644\u064a\u0629 \u0627\u0644\u0645\u0635\u0627\u062f\u0642\u0629 \u0627\u0644\u0645\u062e\u062a\u0627\u0631\u0629.', '\u0627\u062a\u0628\u0639 \u0625\u062c\u0631\u0627\u0621 \u0627\u0646\u062a\u0642\u0627\u0644 \u0627\u0644\u062d\u0633\u0627\u0628 \u0627\u0644\u0645\u0648\u062b\u0642 \u0644\u062f\u0649 \u0627\u0644\u0645\u0632\u0648\u062f \u0639\u0628\u0631 \u0627\u062a\u0635\u0627\u0644 \u0622\u0645\u0646.'],
    'smtpEnhanced7.13': ['\u062d\u0633\u0627\u0628 \u0645\u0639\u0637\u0644 \u0623\u0648 \u0645\u0633\u062a\u0644\u0645 \u0645\u0642\u064a\u062f', '\u0627\u0644\u0645\u0639\u0646\u0649 \u0627\u0644\u0642\u064a\u0627\u0633\u064a \u062d\u0633\u0627\u0628 \u0645\u0639\u0637\u0644. \u064a\u0633\u062a\u062e\u062f\u0645 Exchange Online \u0627\u0644\u0631\u0645\u0632 \u0623\u064a\u0636\u0627 \u0644\u0645\u062c\u0644\u062f \u0639\u0627\u0645 \u064a\u0642\u0628\u0644 \u0645\u0631\u0633\u0644\u064a\u0646 \u062f\u0627\u062e\u0644\u064a\u064a\u0646 \u0645\u0648\u062b\u0642\u064a\u0646 \u0641\u0642\u0637.', '\u0631\u0627\u062c\u0639 \u0627\u0644\u0645\u0632\u0648\u062f \u0648\u0627\u0644\u0631\u062f \u0627\u0644\u0643\u0627\u0645\u0644 \u0648\u0627\u0637\u0644\u0628 \u0645\u0646 \u0645\u0633\u0624\u0648\u0644 \u0627\u0644\u062d\u0633\u0627\u0628 \u0623\u0648 \u0645\u0627\u0644\u0643 \u0627\u0644\u0645\u062c\u0644\u062f \u0645\u0631\u0627\u062c\u0639\u0629 \u0627\u0644\u0642\u064a\u062f.'],
    'smtpEnhanced7.20': ['\u0644\u0627 \u064a\u0648\u062c\u062f \u062a\u0648\u0642\u064a\u0639 DKIM \u0646\u0627\u062c\u062d', '\u0644\u0627 \u064a\u0648\u062c\u062f \u0641\u064a \u0627\u0644\u0631\u0633\u0627\u0644\u0629 \u062a\u0648\u0642\u064a\u0639 DKIM \u064a\u0633\u062a\u0637\u064a\u0639 \u0627\u0644\u0645\u0633\u062a\u0644\u0645 \u0627\u0644\u062a\u062d\u0642\u0642 \u0645\u0646\u0647.', '\u0641\u0639\u0644 DKIM \u0641\u064a \u062e\u062f\u0645\u0629 \u0627\u0644\u0625\u0631\u0633\u0627\u0644 \u0627\u0644\u0641\u0639\u0644\u064a\u0629 \u0648\u0627\u0646\u0634\u0631 \u0627\u0644\u0645\u062d\u062f\u062f\u0627\u062a \u0627\u0644\u0635\u062d\u064a\u062d\u0629 \u0648\u0627\u0641\u062d\u0635 \u062a\u0639\u062f\u064a\u0644\u0627\u062a \u0627\u0644\u0631\u0633\u0627\u0644\u0629 \u0628\u0639\u062f \u0627\u0644\u062a\u0648\u0642\u064a\u0639.'],
    'smtpEnhanced7.21': ['\u0644\u0627 \u064a\u0648\u062c\u062f \u062a\u0648\u0642\u064a\u0639 DKIM \u0645\u0642\u0628\u0648\u0644', '\u0646\u062c\u062d \u062a\u0648\u0642\u064a\u0639 DKIM \u0644\u0643\u0646\u0647 \u0644\u0627 \u064a\u062d\u0642\u0642 \u0633\u064a\u0627\u0633\u0629 \u0627\u0644\u0645\u0633\u062a\u0644\u0645.', '\u062a\u062d\u0642\u0642 \u0645\u0646 \u0646\u0637\u0627\u0642 \u0627\u0644\u062a\u0648\u0642\u064a\u0639 \u0648\u0627\u0644\u062e\u0648\u0627\u0631\u0632\u0645\u064a\u0629 \u0648\u0642\u0648\u0629 \u0627\u0644\u0645\u0641\u062a\u0627\u062d \u0648\u0645\u062a\u0637\u0644\u0628\u0627\u062a \u0627\u0644\u0627\u0633\u062a\u0642\u0628\u0627\u0644.'],
    'smtpEnhanced7.22': ['\u0646\u0637\u0627\u0642 DKIM \u0644\u0627 \u064a\u0637\u0627\u0628\u0642 \u0627\u0644\u0645\u0624\u0644\u0641', '\u062a\u0648\u0642\u064a\u0639 \u0635\u0627\u0644\u062d \u0644\u0627 \u064a\u0637\u0627\u0628\u0642 \u0646\u0637\u0627\u0642 From \u0643\u0645\u0627 \u0647\u0648 \u0645\u0637\u0644\u0648\u0628.', '\u0627\u0636\u0628\u0637 \u062e\u062f\u0645\u0629 \u0627\u0644\u0625\u0631\u0633\u0627\u0644 \u0644\u0644\u062a\u0648\u0642\u064a\u0639 \u0628\u0646\u0637\u0627\u0642 \u0645\u062a\u0648\u0627\u0641\u0642 \u0645\u0639 \u0639\u0646\u0648\u0627\u0646 From \u0627\u0644\u0638\u0627\u0647\u0631.'],
    'smtpEnhanced7.23': ['\u0641\u0634\u0644 \u0627\u0644\u062a\u062d\u0642\u0642 \u0645\u0646 SPF', '\u0639\u0646\u0648\u0627\u0646 IP \u0627\u0644\u0641\u0639\u0644\u064a \u0644\u0644\u0625\u0631\u0633\u0627\u0644 \u063a\u064a\u0631 \u0645\u0635\u0631\u062d \u0628\u0647 \u0641\u064a SPF \u0644\u0646\u0637\u0627\u0642 \u0645\u0631\u0633\u0644 \u0627\u0644\u0645\u063a\u0644\u0641.', '\u0631\u0627\u062c\u0639 MAIL FROM \u0648\u062e\u062f\u0645\u0629 \u0627\u0644\u0625\u0631\u0633\u0627\u0644. \u0627\u0646\u0634\u0631 \u0633\u062c\u0644 SPF \u0648\u0627\u062d\u062f\u0627 \u0635\u0627\u0644\u062d\u0627 \u064a\u0633\u0645\u062d \u0628\u0627\u0644\u062e\u062f\u0645\u0629 \u0636\u0645\u0646 \u062d\u062f \u0627\u0633\u062a\u0639\u0644\u0627\u0645\u0627\u062a DNS.'],
    'smtpEnhanced7.24': ['\u062e\u0637\u0623 \u062a\u0642\u064a\u064a\u0645 SPF', '\u0645\u0646\u0639\u062a \u0623\u062e\u0637\u0627\u0621 DNS \u0623\u0648 \u062a\u0639\u062f\u062f \u0633\u062c\u0644\u0627\u062a SPF \u0623\u0648 \u0627\u0644\u0635\u064a\u0627\u063a\u0629 \u0623\u0648 \u0643\u062b\u0631\u0629 \u0627\u0644\u0627\u0633\u062a\u0639\u0644\u0627\u0645\u0627\u062a \u0627\u0644\u062a\u0642\u064a\u064a\u0645.', '\u0623\u0635\u0644\u062d DNS \u0623\u0648 SPF \u0648\u0627\u0641\u062d\u0635 include \u0648redirect\u060c \u0648\u0627\u062d\u062a\u0641\u0638 \u0628\u0633\u062c\u0644 \u0648\u0627\u062d\u062f \u0648\u0628\u062d\u062f \u0623\u0642\u0635\u0649 \u0639\u0634\u0631\u0629 \u0639\u0646\u0627\u0635\u0631 \u062a\u0633\u062a\u0639\u0644\u0645 DNS.'],
    'smtpEnhanced7.25': ['\u0641\u0634\u0644 \u0627\u0644\u062a\u062d\u0642\u0642 \u0645\u0646 DNS \u0627\u0644\u0639\u0643\u0633\u064a', '\u0639\u0646\u0648\u0627\u0646 IP \u0627\u0644\u0645\u0631\u0633\u0644 \u064a\u0641\u062a\u0642\u0631 \u0625\u0644\u0649 PTR \u0645\u0642\u0628\u0648\u0644 \u0623\u0648 DNS \u0623\u0645\u0627\u0645\u064a \u0645\u0637\u0627\u0628\u0642.', '\u0627\u0637\u0644\u0628 \u0645\u0646 \u0645\u0627\u0644\u0643 IP \u0625\u0639\u062f\u0627\u062f PTR \u0648A/AAAA \u0645\u062a\u0637\u0627\u0628\u0642\u0629 \u062d\u0633\u0628 \u0645\u062a\u0637\u0644\u0628\u0627\u062a \u0627\u0644\u0645\u0632\u0648\u062f.'],
    'smtpEnhanced7.26': ['\u0641\u0634\u0644\u062a \u0641\u062d\u0648\u0635 \u0645\u0635\u0627\u062f\u0642\u0629 \u0627\u0644\u0631\u0633\u0627\u0644\u0629', '\u0641\u0634\u0644\u062a \u0639\u062f\u0629 \u0641\u062d\u0648\u0635\u060c \u063a\u0627\u0644\u0628\u0627 SPF \u0623\u0648 DKIM \u0623\u0648 DMARC. \u0627\u0644\u0631\u0645\u0632 \u0648\u062d\u062f\u0647 \u0644\u0627 \u064a\u062d\u062f\u062f \u0623\u064a\u0647\u0627.', '\u0631\u0627\u062c\u0639 Authentication-Results \u0648\u0631\u062f \u0627\u0644\u0645\u0633\u062a\u0644\u0645. \u0635\u062d\u062d SPF \u0648DKIM \u062b\u0645 \u062a\u062d\u0642\u0642 \u0645\u0646 \u062a\u0648\u0627\u0641\u0642\u0647\u0645\u0627 \u0645\u0639 From \u0644\u0623\u062c\u0644 DMARC.'],
    'smtpEnhanced7.27': ['\u0646\u0637\u0627\u0642 \u0627\u0644\u0645\u0631\u0633\u0644 \u064a\u0646\u0634\u0631 MX \u0641\u0627\u0631\u063a\u0627', '\u0646\u0637\u0627\u0642 \u0627\u0644\u0645\u0631\u0633\u0644 \u0644\u0627 \u064a\u0642\u0628\u0644 \u0627\u0644\u0645\u0631\u062a\u062c\u0639\u0627\u062a \u0648\u064a\u0631\u0641\u0636 \u0627\u0644\u0645\u0633\u062a\u0644\u0645 \u0647\u0630\u0627 \u0627\u0644\u0646\u0648\u0639 \u0645\u0646 \u0627\u0644\u0645\u0631\u0633\u0644\u064a\u0646.', '\u0627\u0633\u062a\u062e\u062f\u0645 \u0646\u0637\u0627\u0642 \u0645\u063a\u0644\u0641 \u0645\u0648\u062b\u0642\u0627 \u064a\u0633\u062a\u0637\u064a\u0639 \u0627\u0633\u062a\u0642\u0628\u0627\u0644 \u0627\u0644\u0631\u0633\u0627\u0626\u0644 \u0627\u0644\u0645\u0631\u062a\u062f\u0629 \u0627\u0644\u0644\u0627\u0632\u0645\u0629.'],
    'smtpEnhanced7.28': ['\u0627\u0634\u062a\u0628\u0627\u0647 \u062a\u062f\u0641\u0642 \u0631\u0633\u0627\u0626\u0644 \u0645\u0633\u064a\u0621', '\u064a\u0639\u062a\u0628\u0631 \u0627\u0644\u0645\u0633\u062a\u0644\u0645 \u0627\u0644\u062d\u0631\u0643\u0629 \u062c\u0632\u0621\u0627 \u0645\u0646 \u0633\u064a\u0644 \u0631\u0633\u0627\u0626\u0644 \u0645\u0633\u064a\u0621.', '\u0623\u0648\u0642\u0641 \u0627\u0644\u0625\u0631\u0633\u0627\u0644 \u063a\u064a\u0631 \u0627\u0644\u0645\u0642\u0635\u0648\u062f \u0648\u0627\u0641\u062d\u0635 \u0623\u0645\u0627\u0646 \u0627\u0644\u062d\u0633\u0627\u0628 \u0648\u0642\u0644\u0644 \u0627\u0644\u062d\u062c\u0645 \u0648\u0627\u062a\u0628\u0639 \u0645\u0639\u0627\u0644\u062c\u0629 \u0627\u0644\u0645\u0633\u062a\u0644\u0645.'],
    'smtpEnhanced7.29': ['\u0641\u0634\u0644 \u0627\u0644\u062a\u062d\u0642\u0642 \u0645\u0646 ARC', '\u062a\u0639\u0630\u0631 \u0627\u0644\u062a\u062d\u0642\u0642 \u0645\u0646 \u0633\u0644\u0633\u0644\u0629 \u0627\u0644\u0627\u0633\u062a\u0644\u0627\u0645 \u0627\u0644\u0645\u0648\u062b\u0642\u0629 \u0644\u0644\u0631\u0633\u0627\u0644\u0629.', '\u0631\u0627\u062c\u0639 \u062a\u0648\u0627\u0642\u064a\u0639 ARC \u0648\u062a\u0631\u062a\u064a\u0628 \u0627\u0644\u0623\u062e\u062a\u0627\u0645 \u0648\u062a\u0639\u062f\u064a\u0644\u0627\u062a \u0628\u0648\u0627\u0628\u0627\u062a \u0625\u0639\u0627\u062f\u0629 \u0627\u0644\u062a\u0648\u062c\u064a\u0647.'],
    'smtpEnhanced7.30': ['\u062f\u0639\u0645 TLS \u0627\u0644\u0645\u0637\u0644\u0648\u0628 \u063a\u064a\u0631 \u0645\u062a\u0627\u062d', '\u062a\u062d\u062a\u0627\u062c \u0627\u0644\u0631\u0633\u0627\u0644\u0629 REQUIRETLS \u0648\u0644\u0627 \u062a\u062f\u0639\u0645\u0647 \u0627\u0644\u0642\u0641\u0632\u0629 \u0627\u0644\u062a\u0627\u0644\u064a\u0629.', '\u0627\u0633\u062a\u062e\u062f\u0645 \u0645\u0633\u0627\u0631\u0627 \u064a\u062f\u0639\u0645 REQUIRETLS \u0628\u0627\u0644\u0643\u0627\u0645\u0644 \u0648\u0627\u0637\u0644\u0628 \u0645\u0646 \u0627\u0644\u0645\u0633\u0624\u0648\u0644\u064a\u0646 \u062d\u0644 \u0639\u062f\u0645 \u0627\u0644\u062a\u0648\u0627\u0641\u0642.'],
    'smtpProvider4.4.316': ['\u0631\u0641\u0636 \u0627\u0644\u0627\u062a\u0635\u0627\u0644 \u0627\u0644\u0628\u0639\u064a\u062f', '\u062a\u0639\u0630\u0631 \u0639\u0644\u0649 Exchange Online \u0627\u0644\u0627\u062a\u0635\u0627\u0644 \u0628\u062e\u062f\u0645\u0629 SMTP \u0627\u0644\u0648\u062c\u0647\u0629.', '\u0627\u0637\u0644\u0628 \u0641\u062d\u0635 \u0627\u0644\u0645\u0633\u062a\u0645\u0639 \u0648\u062c\u062f\u0627\u0631 \u0627\u0644\u062d\u0645\u0627\u064a\u0629 \u0648\u0623\u0647\u062f\u0627\u0641 MX \u0648\u062a\u0648\u0641\u0631 \u0627\u0644\u062e\u062f\u0645\u0629.'],
