    'smtpEnhanced2.1': ['\u092e\u0947\u0932\u092c\u0949\u0915\u094d\u0938 \u0905\u0915\u094d\u0937\u092e \u0939\u0948', '\u092e\u0947\u0932\u092c\u0949\u0915\u094d\u0938 \u092e\u094c\u091c\u0942\u0926 \u0939\u0948 \u0932\u0947\u0915\u093f\u0928 \u0938\u0902\u0926\u0947\u0936 \u0938\u094d\u0935\u0940\u0915\u093e\u0930 \u0928\u0939\u0940\u0902 \u0915\u0930\u0924\u093e\u0964', '\u0916\u093e\u0924\u0947 \u0915\u0940 \u0938\u094d\u0925\u093f\u0924\u093f, \u0932\u093e\u0907\u0938\u0947\u0902\u0938 \u0914\u0930 \u092e\u0947\u0932\u092c\u0949\u0915\u094d\u0938 \u0909\u092a\u0932\u092c\u094d\u0927\u0924\u093e \u091c\u093e\u0901\u091a\u0928\u0947 \u0915\u094b \u0915\u0939\u0947\u0902\u0964'],
