    'smtpEnhanced2.3': ['\u092e\u0947\u0932\u092c\u0949\u0915\u094d\u0938 \u0915\u0940 \u0938\u0902\u0926\u0947\u0936 \u0906\u0915\u093e\u0930 \u0938\u0940\u092e\u093e \u092a\u093e\u0930 \u0939\u0941\u0908', '\u0938\u0902\u0926\u0947\u0936 \u0907\u0938 \u092e\u0947\u0932\u092c\u0949\u0915\u094d\u0938 \u0915\u0947 \u0906\u0915\u093e\u0930 \u092a\u094d\u0930\u0924\u093f\u092c\u0902\u0927 \u0938\u0947 \u092c\u0921\u093c\u093e \u0939\u0948\u0964', 'MIME \u090f\u0928\u094d\u0915\u094b\u0921\u093f\u0902\u0917 \u0915\u0940 \u0905\u0924\u093f\u0930\u093f\u0915\u094d\u0924 \u092e\u093e\u0924\u094d\u0930\u093e \u0927\u094d\u092f\u093e\u0928 \u092e\u0947\u0902 \u0930\u0916\u0915\u0930 \u0938\u0902\u0926\u0947\u0936 \u0914\u0930 \u0938\u0902\u0932\u0917\u094d\u0928\u0915 \u0918\u091f\u093e\u090f\u0901 \u092f\u093e \u0938\u094d\u0935\u0940\u0915\u0943\u0924 \u092b\u093c\u093e\u0907\u0932 \u0932\u093f\u0902\u0915 \u0909\u092a\u092f\u094b\u0917 \u0915\u0930\u0947\u0902\u0964'],
