    'smtpEnhanced3.0': ['\u092e\u0947\u0932 \u092a\u094d\u0930\u0923\u093e\u0932\u0940 \u092e\u0947\u0902 \u0935\u093f\u092b\u0932\u0924\u093e', '\u0917\u0902\u0924\u0935\u094d\u092f \u0938\u0947\u0935\u093e \u0928\u0947 \u0938\u093e\u092e\u093e\u0928\u094d\u092f \u092a\u094d\u0930\u0923\u093e\u0932\u0940 \u0938\u092e\u0938\u094d\u092f\u093e \u092c\u0924\u093e\u0908\u0964', '\u092a\u094d\u0930\u093e\u092a\u094d\u0924\u0915\u0930\u094d\u0924\u093e \u0915\u0947 \u0935\u094d\u092f\u0935\u0938\u094d\u0925\u093e\u092a\u0915 \u0938\u0947 \u0938\u0947\u0935\u093e, \u0915\u0924\u093e\u0930\u0947\u0902 \u0914\u0930 \u0938\u0930\u094d\u0935\u0930 \u0928\u093f\u0926\u093e\u0928 \u091c\u093e\u0901\u091a\u0928\u0947 \u0915\u094b \u0915\u0939\u0947\u0902\u0964'],
    'smtpEnhanced3.1': ['\u092e\u0947\u0932 \u092a\u094d\u0930\u0923\u093e\u0932\u0940 \u0915\u093e \u0938\u0902\u0917\u094d\u0930\u0939\u0923 \u0938\u092e\u093e\u092a\u094d\u0924', '\u0938\u093e\u091d\u093e \u0938\u0930\u094d\u0935\u0930 \u0938\u0902\u0917\u094d\u0930\u0939\u0923 \u0916\u0924\u094d\u092e \u0939\u0941\u0906 \u0939\u0948, \u0915\u0947\u0935\u0932 \u090f\u0915 \u092e\u0947\u0932\u092c\u0949\u0915\u094d\u0938 \u0915\u093e \u0915\u094b\u091f\u093e \u0928\u0939\u0940\u0902\u0964', '\u092a\u094d\u0930\u093e\u092a\u094d\u0924\u0915\u0930\u094d\u0924\u093e \u0915\u0947 \u0935\u094d\u092f\u0935\u0938\u094d\u0925\u093e\u092a\u0915 \u0915\u094b \u0938\u0930\u094d\u0935\u0930 \u0915\u094d\u0937\u092e\u0924\u093e \u092c\u0939\u093e\u0932 \u0915\u0930\u0928\u0940 \u0939\u094b\u0917\u0940\u0964 \u092c\u0922\u093c\u0924\u0947 \u0905\u0902\u0924\u0930\u093e\u0932 \u092a\u0930 \u092a\u094d\u0930\u092f\u093e\u0938 \u0939\u094b\u0928\u0947 \u0926\u0947\u0902\u0964'],
    'smtpEnhanced3.2': ['\u092e\u0947\u0932 \u092a\u094d\u0930\u0923\u093e\u0932\u0940 \u0938\u0902\u0926\u0947\u0936 \u0938\u094d\u0935\u0940\u0915\u093e\u0930 \u0928\u0939\u0940\u0902 \u0915\u0930 \u0930\u0939\u0940', '\u0938\u0947\u0935\u093e \u0930\u0916\u0930\u0916\u093e\u0935, \u092c\u0902\u0926 \u0939\u094b\u0928\u0947, \u0905\u0927\u093f\u0915 \u092d\u093e\u0930 \u092f\u093e \u0905\u0928\u094d\u092f \u0915\u093e\u0930\u0923 \u0938\u0947 \u092e\u0947\u0932 \u0928\u0939\u0940\u0902 \u0932\u0947 \u0930\u0939\u0940\u0964', '\u0938\u0947\u0935\u093e \u0914\u0930 \u0915\u0928\u0947\u0915\u094d\u0936\u0928 \u0938\u0940\u092e\u093e\u090f\u0901 \u091c\u093e\u0901\u091a\u0947\u0902\u0964 \u0938\u094d\u0925\u093e\u092f\u0940 \u092a\u094d\u0930\u0924\u093f\u0915\u094d\u0930\u093f\u092f\u093e \u092e\u0947\u0902 \u0928\u092f\u093e \u0938\u0902\u0926\u0947\u0936 \u092d\u0947\u091c\u0928\u0947 \u0938\u0947 \u092a\u0939\u0932\u0947 \u0915\u093e\u0930\u0923 \u0920\u0940\u0915 \u0915\u0930\u0947\u0902\u0964'],
    'smtpEnhanced3.3': ['\u0906\u0935\u0936\u094d\u092f\u0915 \u092e\u0947\u0932 \u0938\u0941\u0935\u093f\u0927\u093e \u0909\u092a\u0932\u092c\u094d\u0927 \u0928\u0939\u0940\u0902', '\u0917\u0902\u0924\u0935\u094d\u092f \u092f\u093e \u0917\u0947\u091f\u0935\u0947 \u0905\u0928\u0941\u0930\u094b\u0927\u093f\u0924 \u0938\u0941\u0935\u093f\u0927\u093e \u0915\u093e \u0938\u092e\u0930\u094d\u0925\u0928 \u0928\u0939\u0940\u0902 \u0915\u0930\u0924\u093e\u0964', '\u0938\u092e\u0930\u094d\u0925\u093f\u0924 \u0938\u0941\u0935\u093f\u0927\u093e\u090f\u0901 \u0909\u092a\u092f\u094b\u0917 \u0915\u0930\u0947\u0902 \u092f\u093e \u0935\u094d\u092f\u0935\u0938\u094d\u0925\u093e\u092a\u0915 \u0938\u0947 \u0917\u0947\u091f\u0935\u0947 \u0938\u0947\u091f\u093f\u0902\u0917 \u0938\u0941\u0927\u093e\u0930\u0928\u0947 \u0915\u094b \u0915\u0939\u0947\u0902\u0964'],
    'smtpEnhanced3.4': ['\u092a\u094d\u0930\u0923\u093e\u0932\u0940 \u0915\u0940 \u0938\u0902\u0926\u0947\u0936 \u0906\u0915\u093e\u0930 \u0938\u0940\u092e\u093e \u092a\u093e\u0930 \u0939\u0941\u0908', '\u0938\u0902\u0926\u0947\u0936 \u092a\u094d\u0930\u093e\u092a\u094d\u0924\u0915\u0930\u094d\u0924\u093e \u0938\u0930\u094d\u0935\u0930 \u0915\u0940 \u0905\u0927\u093f\u0915\u0924\u092e \u0906\u0915\u093e\u0930 \u0938\u0940\u092e\u093e \u0938\u0947 \u092c\u0921\u093c\u093e \u0939\u0948\u0964', '\u090f\u0928\u094d\u0915\u094b\u0921\u093f\u0902\u0917 \u0915\u0947 \u092c\u093e\u0926 \u0906\u0915\u093e\u0930 \u0918\u091f\u093e\u090f\u0901 \u092f\u093e \u0938\u094d\u0935\u0940\u0915\u0943\u0924 \u092b\u093c\u093e\u0907\u0932 \u0932\u093f\u0902\u0915 \u0909\u092a\u092f\u094b\u0917 \u0915\u0930\u0947\u0902\u0964 \u092a\u0942\u0930\u0947 \u0935\u093f\u0924\u0930\u0923 \u092e\u093e\u0930\u094d\u0917 \u0915\u0940 \u0938\u0940\u092e\u093e\u090f\u0901 \u091c\u093e\u0901\u091a\u0947\u0902\u0964'],
    'smtpEnhanced3.5': ['\u092e\u0947\u0932 \u092a\u094d\u0930\u0923\u093e\u0932\u0940 \u0915\u0940 \u0938\u0947\u091f\u093f\u0902\u0917 \u0917\u0932\u0924', '\u092a\u094d\u0930\u093e\u092a\u094d\u0924\u0915\u0930\u094d\u0924\u093e \u092f\u093e \u092e\u0927\u094d\u092f\u0935\u0930\u094d\u0924\u0940 \u092a\u094d\u0930\u0923\u093e\u0932\u0940 \u0917\u0932\u0924 \u0915\u0949\u0928\u094d\u092b\u093c\u093f\u0917\u0930 \u0915\u0940 \u0917\u0908 \u0939\u0948\u0964', '\u0935\u094d\u092f\u0935\u0938\u094d\u0925\u093e\u092a\u0915 \u0938\u0947 \u0938\u094d\u0935\u0940\u0915\u0943\u0924 \u0921\u094b\u092e\u0947\u0928, \u0915\u0928\u0947\u0915\u094d\u091f\u0930, \u0930\u0942\u091f\u093f\u0902\u0917 \u0914\u0930 \u0938\u0947\u0935\u093e \u0938\u0947\u091f\u093f\u0902\u0917 \u091c\u093e\u0901\u091a\u0928\u0947 \u0915\u094b \u0915\u0939\u0947\u0902\u0964'],
