    'smtpEnhanced4.1': ['\u0917\u0902\u0924\u0935\u094d\u092f \u0939\u094b\u0938\u094d\u091f \u0928\u0947 \u0909\u0924\u094d\u0924\u0930 \u0928\u0939\u0940\u0902 \u0926\u093f\u092f\u093e', '\u0939\u094b\u0938\u094d\u091f \u092c\u0902\u0926, \u0905\u0927\u093f\u0915 \u092d\u093e\u0930 \u092e\u0947\u0902 \u092f\u093e \u092b\u093c\u093e\u092f\u0930\u0935\u0949\u0932 \u0938\u0947 \u0905\u0935\u0930\u0941\u0926\u094d\u0927 \u0939\u094b \u0938\u0915\u0924\u093e \u0939\u0948\u0964', '\u092a\u094d\u0930\u093e\u092a\u094d\u0924\u0915\u0930\u094d\u0924\u093e \u0935\u094d\u092f\u0935\u0938\u094d\u0925\u093e\u092a\u0915 \u0915\u0947 \u0938\u093e\u0925 SMTP \u0932\u093f\u0938\u0928\u0930, MX \u0932\u0915\u094d\u0937\u094d\u092f \u0914\u0930 \u092b\u093c\u093e\u092f\u0930\u0935\u0949\u0932 \u0928\u093f\u092f\u092e \u091c\u093e\u0901\u091a\u0947\u0902\u0964'],
    'smtpEnhanced4.2': ['\u0935\u093f\u0924\u0930\u0923 \u0915\u0947 \u0926\u094c\u0930\u093e\u0928 \u0915\u0928\u0947\u0915\u094d\u0936\u0928 \u0935\u093f\u092b\u0932', '\u0938\u094d\u0925\u093e\u092a\u093f\u0924 \u0915\u0928\u0947\u0915\u094d\u0936\u0928 \u0932\u0947\u0928\u0926\u0947\u0928 \u092a\u0942\u0930\u093e \u0939\u094b\u0928\u0947 \u0938\u0947 \u092a\u0939\u0932\u0947 \u091f\u0942\u091f \u0917\u092f\u093e \u092f\u093e \u0938\u092e\u092f \u0938\u0940\u092e\u093e \u0938\u092e\u093e\u092a\u094d\u0924 \u0939\u0941\u0908\u0964', '\u0928\u0947\u091f\u0935\u0930\u094d\u0915 \u0938\u094d\u0925\u093f\u0930\u0924\u093e, SMTP \u0938\u092e\u092f \u0938\u0940\u092e\u093e\u090f\u0901, TLS \u0935\u093f\u092b\u0932\u0924\u093e\u090f\u0901 \u0914\u0930 \u092a\u094d\u0930\u093e\u092a\u094d\u0924\u0915\u0930\u094d\u0924\u093e \u0938\u0947\u0935\u093e \u0915\u0940 \u0938\u094d\u0925\u093f\u0924\u093f \u091c\u093e\u0901\u091a\u0947\u0902\u0964'],
    'smtpEnhanced4.3': ['\u0928\u093f\u0930\u094d\u0926\u0947\u0936\u093f\u0915\u093e \u092f\u093e DNS \u0905\u0928\u0941\u092a\u0932\u092c\u094d\u0927', '\u0930\u0942\u091f\u093f\u0902\u0917 \u0915\u0947 \u0932\u093f\u090f \u0906\u0935\u0936\u094d\u092f\u0915 \u0928\u093f\u0930\u094d\u0926\u0947\u0936\u093f\u0915\u093e \u092f\u093e DNS \u0916\u094b\u091c \u0935\u093f\u092b\u0932 \u0939\u0941\u0908\u0964', '\u0905\u0927\u093f\u0915\u0943\u0924 DNS, \u0930\u093f\u091c\u093c\u0949\u0932\u094d\u0935\u0930, DNSSEC \u0914\u0930 \u0928\u093f\u0930\u094d\u0926\u0947\u0936\u093f\u0915\u093e \u0915\u0940 \u0909\u092a\u0932\u092c\u094d\u0927\u0924\u093e \u091c\u093e\u0901\u091a\u0947\u0902\u0964'],
    'smtpEnhanced4.4': ['\u0909\u092a\u092f\u094b\u0917 \u092f\u094b\u0917\u094d\u092f \u092e\u0947\u0932 \u092e\u093e\u0930\u094d\u0917 \u0928\u0939\u0940\u0902', '\u0905\u0917\u0932\u093e \u0938\u0930\u094d\u0935\u0930 \u0924\u092f \u0928\u0939\u0940\u0902 \u0939\u094b \u0938\u0915\u093e \u092f\u093e \u0915\u0949\u0928\u094d\u092b\u093c\u093f\u0917\u0930 \u0915\u093f\u092f\u093e \u092e\u093e\u0930\u094d\u0917 \u0917\u0932\u0924 \u0939\u0948\u0964', 'MX, A/AAAA, \u0938\u094d\u0935\u0940\u0915\u0943\u0924 \u0921\u094b\u092e\u0947\u0928, \u0915\u0928\u0947\u0915\u094d\u091f\u0930 \u092e\u093e\u0930\u094d\u0917 \u0914\u0930 \u0938\u094d\u092e\u093e\u0930\u094d\u091f \u0939\u094b\u0938\u094d\u091f \u0938\u0947\u091f\u093f\u0902\u0917 \u091c\u093e\u0901\u091a\u0947\u0902\u0964'],
    'smtpEnhanced4.5': ['\u092e\u0947\u0932 \u092a\u094d\u0930\u0923\u093e\u0932\u0940 \u092e\u0947\u0902 \u092d\u0940\u0921\u093c', '\u0915\u0924\u093e\u0930\u094b\u0902 \u092f\u093e \u0935\u093f\u0924\u0930\u0923 \u0915\u094d\u0937\u092e\u0924\u093e \u092a\u0930 \u0905\u0927\u093f\u0915 \u092d\u093e\u0930 \u0939\u0948\u0964', '\u0938\u092e\u0935\u0930\u094d\u0924\u0940 \u0915\u0928\u0947\u0915\u094d\u0936\u0928 \u0914\u0930 \u092d\u0947\u091c\u0928\u0947 \u0915\u0940 \u0926\u0930 \u0918\u091f\u093e\u090f\u0901 \u0924\u0925\u093e \u0938\u0947\u0935\u093e \u0915\u094b \u0915\u0924\u093e\u0930\u0947\u0902 \u0938\u0902\u0938\u093e\u0927\u093f\u0924 \u0915\u0930\u0928\u0947 \u0926\u0947\u0902\u0964'],
    'smtpEnhanced4.6': ['\u092e\u0947\u0932 \u0930\u0942\u091f\u093f\u0902\u0917 \u092e\u0947\u0902 \u091a\u0915\u094d\u0930', '\u0905\u0917\u094d\u0930\u0947\u0937\u0923 \u092f\u093e \u0915\u0928\u0947\u0915\u094d\u091f\u0930 \u092c\u093e\u0930-\u092c\u093e\u0930 \u0938\u0902\u0926\u0947\u0936 \u0915\u094b \u0909\u0928\u094d\u0939\u0940\u0902 \u092a\u094d\u0930\u0923\u093e\u0932\u093f\u092f\u094b\u0902 \u0938\u0947 \u0917\u0941\u091c\u093e\u0930\u0924\u0947 \u0939\u0948\u0902\u0964', '\u0938\u0902\u0926\u0947\u0936 \u0915\u0947 \u091a\u0930\u0923 \u091f\u094d\u0930\u0947\u0938 \u0915\u0930\u0947\u0902 \u0914\u0930 \u091a\u0915\u094d\u0930\u0940\u092f \u0905\u0917\u094d\u0930\u0947\u0937\u0923 \u092f\u093e \u0915\u0928\u0947\u0915\u094d\u091f\u0930 \u092e\u093e\u0930\u094d\u0917 \u0939\u091f\u093e\u090f\u0901\u0964'],
    'smtpEnhanced4.7': ['\u0935\u093f\u0924\u0930\u0923 \u0915\u0940 \u0905\u0935\u0927\u093f \u0938\u092e\u093e\u092a\u094d\u0924', '\u0915\u0924\u093e\u0930 \u092e\u0947\u0902 \u0930\u0939\u0928\u0947 \u0915\u0940 \u0905\u0935\u0927\u093f \u092a\u0942\u0930\u0940 \u0939\u094b\u0928\u0947 \u0924\u0915 \u0938\u0902\u0926\u0947\u0936 \u0935\u093f\u0924\u0930\u093f\u0924 \u0928\u0939\u0940\u0902 \u0939\u0941\u0906\u0964', '\u092a\u0939\u0932\u0940 \u0924\u094d\u0930\u0941\u091f\u093f\u092f\u093e\u0901 \u091c\u093e\u0901\u091a\u0915\u0930 \u0915\u093e\u0930\u0923 \u0920\u0940\u0915 \u0915\u0930\u0947\u0902\u0964 \u0905\u0935\u0927\u093f \u0938\u092e\u093e\u092a\u094d\u0924 \u0938\u0902\u0926\u0947\u0936 \u0915\u0947 \u0938\u094d\u0935\u091a\u093e\u0932\u093f\u0924 \u092a\u094d\u0930\u092f\u093e\u0938 \u092c\u0902\u0926 \u0939\u094b \u091c\u093e\u0924\u0947 \u0939\u0948\u0902 \u0914\u0930 \u0928\u092f\u093e \u0938\u0902\u0926\u0947\u0936 \u092d\u0947\u091c\u0928\u093e \u092a\u0921\u093c \u0938\u0915\u0924\u093e \u0939\u0948\u0964'],
    'smtpEnhanced5.0': ['\u092e\u0947\u0932 \u092a\u094d\u0930\u094b\u091f\u094b\u0915\u0949\u0932 \u0935\u093f\u092b\u0932\u0924\u093e', 'SMTP \u0938\u0902\u0935\u093e\u0926 \u0935\u093f\u092b\u0932 \u0939\u0941\u0906, \u0932\u0947\u0915\u093f\u0928 \u0938\u091f\u0940\u0915 \u092a\u094d\u0930\u094b\u091f\u094b\u0915\u0949\u0932 \u0935\u093f\u0935\u0930\u0923 \u0928\u0939\u0940\u0902 \u0926\u093f\u092f\u093e \u0917\u092f\u093e\u0964', '\u0915\u094d\u0932\u093e\u0907\u0902\u091f \u0915\u093e SMTP \u0915\u094d\u0930\u092e \u0914\u0930 \u092a\u094d\u0930\u093e\u092a\u094d\u0924\u0915\u0930\u094d\u0924\u093e \u0915\u093e \u0938\u094d\u092a\u0937\u094d\u091f\u0940\u0915\u0930\u0923 \u0926\u0947\u0916\u0947\u0902\u0964'],
    'smtpEnhanced5.1': ['\u0905\u092e\u093e\u0928\u094d\u092f \u092f\u093e \u0917\u0932\u0924 \u0915\u094d\u0930\u092e \u0915\u093e \u0915\u092e\u093e\u0902\u0921', '\u0915\u092e\u093e\u0902\u0921 \u0905\u0938\u092e\u0930\u094d\u0925\u093f\u0924 \u0939\u0948 \u092f\u093e \u0917\u0932\u0924 SMTP \u0905\u0935\u0938\u094d\u0925\u093e \u092e\u0947\u0902 \u092d\u0947\u091c\u093e \u0917\u092f\u093e\u0964', '\u0915\u092e\u093e\u0902\u0921 \u0915\u094d\u0930\u092e \u0914\u0930 \u0938\u0930\u094d\u0935\u0930 \u0915\u0940 \u0918\u094b\u0937\u093f\u0924 \u0915\u094d\u0937\u092e\u0924\u093e\u090f\u0901 \u091c\u093e\u0901\u091a\u0947\u0902\u0964'],
    'smtpEnhanced5.2': ['SMTP \u092a\u094d\u0930\u093e\u0930\u0942\u092a \u0924\u094d\u0930\u0941\u091f\u093f', '\u092a\u094d\u0930\u093e\u092a\u094d\u0924\u0915\u0930\u094d\u0924\u093e \u0915\u093f\u0938\u0940 \u0915\u092e\u093e\u0902\u0921 \u0915\u094b \u0938\u092e\u091d \u0928\u0939\u0940\u0902 \u0938\u0915\u093e\u0964', '\u0915\u092e\u093e\u0902\u0921 \u092a\u094d\u0930\u093e\u0930\u0942\u092a \u0938\u0941\u0927\u093e\u0930\u0947\u0902 \u0914\u0930 SMTP \u0915\u094d\u0932\u093e\u0907\u0902\u091f \u0932\u093e\u0907\u092c\u094d\u0930\u0947\u0930\u0940 \u0905\u0926\u094d\u092f\u0924\u0928 \u0915\u0930\u0947\u0902\u0964'],
    'smtpEnhanced5.3': ['\u092c\u0939\u0941\u0924 \u0905\u0927\u093f\u0915 \u092a\u094d\u0930\u093e\u092a\u094d\u0924\u0915\u0930\u094d\u0924\u093e', '\u0932\u0947\u0928\u0926\u0947\u0928 \u092a\u094d\u0930\u093e\u092a\u094d\u0924\u0915\u0930\u094d\u0924\u093e \u0938\u0947\u0935\u093e \u0915\u0940 \u0938\u0902\u0916\u094d\u092f\u093e \u0938\u0940\u092e\u093e \u092a\u093e\u0930 \u0915\u0930\u0924\u093e \u0939\u0948\u0964', '\u092a\u094d\u0930\u0926\u093e\u0924\u093e \u0915\u0940 \u092a\u094d\u0930\u0915\u093e\u0936\u093f\u0924 \u0938\u0940\u092e\u093e\u0913\u0902 \u0915\u0947 \u0905\u0928\u0941\u0938\u093e\u0930 \u0938\u0942\u091a\u0940 \u092c\u093e\u0901\u091f\u0947\u0902\u0964 \u092a\u0939\u0932\u0947 \u0938\u0947 \u0938\u094d\u0935\u0940\u0915\u0943\u0924 \u092a\u094d\u0930\u093e\u092a\u094d\u0924\u0915\u0930\u094d\u0924\u093e\u0913\u0902 \u0915\u094b \u0926\u094b\u092c\u093e\u0930\u093e \u0928 \u092d\u0947\u091c\u0947\u0902\u0964'],
    'smtpEnhanced5.4': ['SMTP \u0924\u0930\u094d\u0915 \u0905\u092e\u093e\u0928\u094d\u092f \u0939\u0948\u0902', '\u092a\u0939\u091a\u093e\u0928\u0947 \u0917\u090f \u0915\u092e\u093e\u0902\u0921 \u092e\u0947\u0902 \u0917\u0932\u0924 \u092f\u093e \u0905\u0938\u092e\u0930\u094d\u0925\u093f\u0924 \u0924\u0930\u094d\u0915 \u0939\u0948\u0902\u0964', '\u090f\u0928\u0935\u0947\u0932\u092a \u092a\u0924\u0947 \u0938\u0941\u0927\u093e\u0930\u0947\u0902 \u0914\u0930 \u0915\u0947\u0935\u0932 \u0938\u0939\u092e\u0924 \u090f\u0915\u094d\u0938\u091f\u0947\u0902\u0936\u0928 \u0909\u092a\u092f\u094b\u0917 \u0915\u0930\u0947\u0902\u0964'],
    'smtpEnhanced5.5': ['\u092a\u094d\u0930\u094b\u091f\u094b\u0915\u0949\u0932 \u0938\u0902\u0938\u094d\u0915\u0930\u0923 \u092e\u0947\u0932 \u0928\u0939\u0940\u0902 \u0916\u093e\u0924\u0947', '\u092a\u094d\u0930\u0923\u093e\u0932\u093f\u092f\u093e\u0901 \u0906\u0935\u0936\u094d\u092f\u0915 \u092a\u094d\u0930\u094b\u091f\u094b\u0915\u0949\u0932 \u0938\u0941\u0935\u093f\u0927\u093e\u0913\u0902 \u092a\u0930 \u0938\u0939\u092e\u0924 \u0928\u0939\u0940\u0902 \u0939\u094b \u0938\u0915\u0924\u0940\u0902\u0964', '\u0915\u094d\u0932\u093e\u0907\u0902\u091f \u092f\u093e \u0917\u0947\u091f\u0935\u0947 \u0905\u0926\u094d\u092f\u0924\u0928 \u0915\u0930\u0947\u0902 \u0914\u0930 \u0905\u0928\u0941\u0915\u0942\u0932\u0924\u093e \u091c\u093e\u0901\u091a\u0947\u0902\u0964'],
    'smtpEnhanced6.0': ['\u0938\u093e\u092e\u0917\u094d\u0930\u0940 \u092f\u093e \u090f\u0928\u094d\u0915\u094b\u0921\u093f\u0902\u0917 \u0938\u092e\u0938\u094d\u092f\u093e', '\u0938\u093e\u092e\u0917\u094d\u0930\u0940 \u0915\u0947 \u092a\u094d\u0930\u093e\u0930\u0942\u092a \u0915\u0947 \u0915\u093e\u0930\u0923 \u0938\u0902\u0926\u0947\u0936 \u0938\u0902\u0938\u093e\u0927\u093f\u0924 \u0928\u0939\u0940\u0902 \u0939\u0941\u0906\u0964', '\u092e\u0942\u0932 \u0928\u093f\u0926\u093e\u0928 \u0915\u0947 \u0905\u0928\u0941\u0938\u093e\u0930 MIME \u0939\u0947\u0921\u0930, \u090f\u0928\u094d\u0915\u094b\u0921\u093f\u0902\u0917 \u0914\u0930 \u0938\u0902\u0932\u0917\u094d\u0928\u0915 \u091c\u093e\u0901\u091a\u0947\u0902\u0964'],
    'smtpEnhanced6.1': ['\u0938\u093e\u092e\u0917\u094d\u0930\u0940 \u0915\u093e \u092a\u094d\u0930\u0915\u093e\u0930 \u0938\u092e\u0930\u094d\u0925\u093f\u0924 \u0928\u0939\u0940\u0902', '\u092a\u094d\u0930\u093e\u092a\u094d\u0924\u0915\u0930\u094d\u0924\u093e \u092a\u094d\u0930\u0923\u093e\u0932\u0940 \u0938\u093e\u092e\u0917\u094d\u0930\u0940 \u0915\u0947 \u092a\u094d\u0930\u0915\u093e\u0930 \u092f\u093e \u090f\u0928\u094d\u0915\u094b\u0921\u093f\u0902\u0917 \u0915\u093e \u0938\u092e\u0930\u094d\u0925\u0928 \u0928\u0939\u0940\u0902 \u0915\u0930\u0924\u0940\u0964', '\u0938\u092e\u0930\u094d\u0925\u093f\u0924 MIME \u092a\u094d\u0930\u0915\u093e\u0930 \u0914\u0930 \u090f\u0928\u094d\u0915\u094b\u0921\u093f\u0902\u0917 \u092f\u093e \u0938\u094d\u0935\u0940\u0915\u0943\u0924 \u092b\u093c\u093e\u0907\u0932 \u0932\u093f\u0902\u0915 \u0909\u092a\u092f\u094b\u0917 \u0915\u0930\u0947\u0902\u0964'],
    'smtpEnhanced6.2': ['\u0906\u0935\u0936\u094d\u092f\u0915 \u0930\u0942\u092a\u093e\u0902\u0924\u0930\u0923 \u0915\u0940 \u0905\u0928\u0941\u092e\u0924\u093f \u0928\u0939\u0940\u0902', '\u0935\u093f\u0924\u0930\u0923 \u0915\u0947 \u0932\u093f\u090f \u0906\u0935\u0936\u094d\u092f\u0915 \u0930\u0942\u092a\u093e\u0902\u0924\u0930\u0923 \u0928\u0940\u0924\u093f \u0938\u0947 \u0928\u093f\u0937\u093f\u0926\u094d\u0927 \u0939\u0948\u0964', '\u0938\u092e\u0930\u094d\u0925\u093f\u0924 \u092a\u094d\u0930\u093e\u0930\u0942\u092a \u092e\u0947\u0902 \u0938\u0902\u0926\u0947\u0936 \u092d\u0947\u091c\u0947\u0902 \u092f\u093e \u0935\u094d\u092f\u0935\u0938\u094d\u0925\u093e\u092a\u0915 \u0938\u0947 \u0938\u0902\u092c\u0902\u0927\u093f\u0924 \u0928\u0940\u0924\u093f \u0915\u0940 \u0938\u092e\u0940\u0915\u094d\u0937\u093e \u0915\u0930\u093e\u090f\u0901\u0964'],
    'smtpEnhanced6.3': ['\u0906\u0935\u0936\u094d\u092f\u0915 \u0930\u0942\u092a\u093e\u0902\u0924\u0930\u0923 \u0909\u092a\u0932\u092c\u094d\u0927 \u0928\u0939\u0940\u0902', '\u0917\u0947\u091f\u0935\u0947 \u0905\u0917\u0932\u0947 \u091a\u0930\u0923 \u0915\u0947 \u0932\u093f\u090f \u0938\u0902\u0926\u0947\u0936 \u0930\u0942\u092a\u093e\u0902\u0924\u0930\u093f\u0924 \u0928\u0939\u0940\u0902 \u0915\u0930 \u0938\u0915\u0924\u093e\u0964', '\u0905\u0928\u0941\u0915\u0942\u0932 MIME \u0938\u0902\u0926\u0947\u0936 \u092c\u0928\u093e\u090f\u0901 \u0914\u0930 \u0917\u0947\u091f\u0935\u0947 \u0915\u0940 \u090f\u0928\u094d\u0915\u094b\u0921\u093f\u0902\u0917 \u0915\u094d\u0937\u092e\u0924\u093e\u090f\u0901 \u091c\u093e\u0901\u091a\u0947\u0902\u0964'],
    'smtpEnhanced6.5': ['\u0938\u0902\u0926\u0947\u0936 \u0930\u0942\u092a\u093e\u0902\u0924\u0930\u0923 \u0935\u093f\u092b\u0932 \u0939\u0941\u0906', '\u0906\u0935\u0936\u094d\u092f\u0915 \u0938\u093e\u092e\u0917\u094d\u0930\u0940 \u0930\u0942\u092a\u093e\u0902\u0924\u0930\u0923 \u092a\u0942\u0930\u093e \u0928\u0939\u0940\u0902 \u0939\u094b \u0938\u0915\u093e\u0964', '\u090f\u0928\u094d\u0915\u094b\u0921\u093f\u0902\u0917 \u0914\u0930 \u0930\u0942\u092a\u093e\u0902\u0924\u0930\u0923 \u0915\u0930\u0928\u0947 \u0935\u093e\u0932\u0947 \u0917\u0947\u091f\u0935\u0947 \u0915\u0940 \u0924\u094d\u0930\u0941\u091f\u093f\u092f\u093e\u0901 \u0926\u0947\u0916\u0947\u0902\u0964'],
    'smtpEnhanced6.7': ['\u0905\u0902\u0924\u0930\u0930\u093e\u0937\u094d\u091f\u094d\u0930\u0940\u092f \u092a\u0924\u093e \u0938\u092e\u0930\u094d\u0925\u093f\u0924 \u0928\u0939\u0940\u0902', '\u092e\u093e\u0930\u094d\u0917 \u092e\u0947\u0902 \u0917\u0948\u0930-ASCII \u090f\u0928\u0935\u0947\u0932\u092a \u092a\u0924\u0947 \u0915\u0940 \u0905\u0928\u0941\u092e\u0924\u093f \u0928\u0939\u0940\u0902 \u0939\u0948\u0964', 'SMTPUTF8 \u092e\u093e\u0930\u094d\u0917 \u092f\u093e \u092a\u094d\u0930\u093e\u092a\u094d\u0924\u0915\u0930\u094d\u0924\u093e \u0926\u094d\u0935\u093e\u0930\u093e \u0926\u093f\u092f\u093e \u0905\u0938\u0932\u0940 ASCII \u0909\u092a\u0928\u093e\u092e \u0909\u092a\u092f\u094b\u0917 \u0915\u0930\u0947\u0902\u0964 \u092a\u0924\u0947 \u0938\u0947 \u092e\u0928\u092e\u093e\u0928\u0947 \u0935\u0930\u094d\u0923 \u0928 \u0939\u091f\u093e\u090f\u0901\u0964'],
    'smtpEnhanced6.8': ['\u0907\u0938 \u0915\u094d\u0932\u093e\u0907\u0902\u091f \u0915\u0947 \u0932\u093f\u090f UTF-8 \u0909\u0924\u094d\u0924\u0930 \u0909\u092a\u0932\u092c\u094d\u0927 \u0928\u0939\u0940\u0902', '\u0938\u0930\u094d\u0935\u0930 \u0915\u094b UTF-8 \u0909\u0924\u094d\u0924\u0930 \u0926\u0947\u0928\u093e \u0939\u0948 \u0932\u0947\u0915\u093f\u0928 \u0915\u094d\u0932\u093e\u0907\u0902\u091f \u0928\u0947 \u0907\u0938\u0947 \u0938\u0939\u092e\u0924 \u0928\u0939\u0940\u0902 \u0915\u093f\u092f\u093e\u0964', 'SMTPUTF8 \u0938\u092e\u0930\u094d\u0925\u093f\u0924 \u0915\u094d\u0932\u093e\u0907\u0902\u091f \u0914\u0930 \u0905\u0928\u0941\u0915\u0942\u0932 \u092e\u0947\u0932 \u092e\u093e\u0930\u094d\u0917 \u0909\u092a\u092f\u094b\u0917 \u0915\u0930\u0947\u0902\u0964'],
    'smtpEnhanced6.9': ['UTF-8 \u0938\u0902\u0926\u0947\u0936 \u0938\u092d\u0940 \u092a\u094d\u0930\u093e\u092a\u094d\u0924\u0915\u0930\u094d\u0924\u093e\u0913\u0902 \u0924\u0915 \u0928\u0939\u0940\u0902 \u092a\u0939\u0941\u0901\u091a \u0938\u0915\u0924\u093e', '\u090f\u0915 \u092f\u093e \u0905\u0927\u093f\u0915 \u092a\u094d\u0930\u093e\u092a\u094d\u0924\u0915\u0930\u094d\u0924\u093e\u0913\u0902 \u0915\u0947 \u092e\u093e\u0930\u094d\u0917 \u092e\u0947\u0902 SMTPUTF8 \u0938\u092e\u0930\u094d\u0925\u0928 \u0928\u0939\u0940\u0902 \u0939\u0948\u0964', '\u092a\u0942\u0930\u0947 \u092e\u093e\u0930\u094d\u0917 \u092e\u0947\u0902 SMTPUTF8 \u0938\u092e\u0930\u094d\u0925\u0928 \u091c\u093e\u0901\u091a\u0947\u0902 \u0914\u0930 \u0909\u092a\u0932\u092c\u094d\u0927 \u0939\u094b\u0928\u0947 \u092a\u0930 \u0938\u0924\u094d\u092f\u093e\u092a\u093f\u0924 \u0905\u0928\u0941\u0915\u0942\u0932 \u0909\u092a\u0928\u093e\u092e \u0909\u092a\u092f\u094b\u0917 \u0915\u0930\u0947\u0902\u0964'],
    'smtpEnhanced7.0': ['\u0905\u0928\u093f\u0930\u094d\u0926\u093f\u0937\u094d\u091f \u0938\u0941\u0930\u0915\u094d\u0937\u093e \u092f\u093e \u0928\u0940\u0924\u093f \u0935\u093f\u092b\u0932\u0924\u093e', '\u0938\u0941\u0930\u0915\u094d\u0937\u093e \u092a\u094d\u0930\u0924\u093f\u092c\u0902\u0927, \u092a\u094d\u0930\u092e\u093e\u0923\u0940\u0915\u0930\u0923 \u0938\u092e\u0938\u094d\u092f\u093e \u092f\u093e \u092b\u093c\u093f\u0932\u094d\u091f\u0930 \u0928\u0947 \u0915\u093e\u0930\u094d\u0930\u0935\u093e\u0908 \u0930\u094b\u0915\u0940\u0964', '\u092a\u0942\u0930\u0940 \u092a\u094d\u0930\u0924\u093f\u0915\u094d\u0930\u093f\u092f\u093e \u092a\u0922\u093c\u0947\u0902 \u0914\u0930 \u0935\u094d\u092f\u0935\u0938\u094d\u0925\u093e\u092a\u0915 \u0938\u0947 \u092a\u094d\u0930\u092e\u093e\u0923\u0940\u0915\u0930\u0923 \u0924\u0925\u093e \u0928\u0940\u0924\u093f \u0928\u093f\u0930\u094d\u0923\u092f \u091c\u093e\u0901\u091a\u0928\u0947 \u0915\u094b \u0915\u0939\u0947\u0902\u0964'],
    'smtpEnhanced7.1': ['\u0928\u0940\u0924\u093f \u0928\u0947 \u0935\u093f\u0924\u0930\u0923 \u092a\u094d\u0930\u0924\u093f\u092c\u0902\u0927\u093f\u0924 \u0915\u093f\u092f\u093e', '\u0930\u093f\u0932\u0947 \u0928\u093f\u0937\u0947\u0927, \u092a\u094d\u0930\u093e\u092a\u094d\u0924\u0915\u0930\u094d\u0924\u093e \u092a\u094d\u0930\u0924\u093f\u092c\u0902\u0927, \u092b\u093c\u093f\u0932\u094d\u091f\u0930\u093f\u0902\u0917 \u092f\u093e \u092a\u094d\u0930\u092e\u093e\u0923\u0940\u0915\u0930\u0923 \u0915\u0940 \u0915\u092e\u0940 \u0938\u0902\u092d\u0935 \u0939\u0948\u0964 \u0905\u0938\u094d\u0925\u093e\u092f\u0940 \u0909\u0924\u094d\u0924\u0930 \u0917\u094d\u0930\u0947\u0932\u093f\u0938\u094d\u091f\u093f\u0902\u0917 \u092d\u0940 \u0939\u094b \u0938\u0915\u0924\u093e \u0939\u0948\u0964', 'SMTP \u090f\u0902\u0921\u092a\u0949\u0907\u0902\u091f, \u092a\u094d\u0930\u092e\u093e\u0923\u0940\u0915\u0930\u0923, \u0905\u0927\u093f\u0915\u093e\u0930 \u0914\u0930 \u092a\u094d\u0930\u0924\u093f\u0937\u094d\u0920\u093e \u091c\u093e\u0901\u091a\u0947\u0902\u0964 \u0935\u093f\u0936\u093f\u0937\u094d\u091f \u0928\u0940\u0924\u093f \u092a\u0942\u091b\u0947\u0902, \u0938\u0941\u0930\u0915\u094d\u0937\u093e \u0909\u092a\u093e\u092f \u0935\u094d\u092f\u093e\u092a\u0915 \u0930\u0942\u092a \u0938\u0947 \u092c\u0902\u0926 \u0928 \u0915\u0930\u0947\u0902\u0964'],
    'smtpEnhanced7.2': ['\u0907\u0938 \u0938\u0942\u091a\u0940 \u092e\u0947\u0902 \u092d\u0947\u091c\u0928\u0947 \u0915\u0940 \u0905\u0928\u0941\u092e\u0924\u093f \u0928\u0939\u0940\u0902', '\u092a\u094d\u0930\u0947\u0937\u0915 \u0935\u093f\u0924\u0930\u0923 \u0938\u0942\u091a\u0940 \u0909\u092a\u092f\u094b\u0917 \u0915\u0930\u0928\u0947 \u0915\u0947 \u0932\u093f\u090f \u0905\u0927\u093f\u0915\u0943\u0924 \u0928\u0939\u0940\u0902 \u0939\u0948\u0964', '\u0938\u0942\u091a\u0940 \u092e\u093e\u0932\u093f\u0915 \u0915\u0940 \u0905\u0928\u0941\u092e\u0924\u093f \u0932\u0947\u0902 \u092f\u093e \u0938\u094d\u0935\u0940\u0915\u0943\u0924 \u092a\u0924\u093e \u0909\u092a\u092f\u094b\u0917 \u0915\u0930\u0947\u0902\u0964'],
    'smtpEnhanced7.3': ['\u0938\u0941\u0930\u0915\u094d\u0937\u093f\u0924 \u0938\u0902\u0926\u0947\u0936 \u0930\u0942\u092a\u093e\u0902\u0924\u0930\u0923 \u0909\u092a\u0932\u092c\u094d\u0927 \u0928\u0939\u0940\u0902', '\u0917\u0947\u091f\u0935\u0947 \u0906\u0935\u0936\u094d\u092f\u0915 \u0938\u0941\u0930\u0915\u094d\u0937\u093f\u0924 \u0930\u0942\u092a\u093e\u0902\u0924\u0930\u0923 \u0928\u0939\u0940\u0902 \u0915\u0930 \u0938\u0915\u0924\u093e\u0964', '\u0926\u094b\u0928\u094b\u0902 \u092a\u0915\u094d\u0937\u094b\u0902 \u092e\u0947\u0902 \u0938\u092e\u0930\u094d\u0925\u093f\u0924 \u0938\u0941\u0930\u0915\u094d\u0937\u093f\u0924 \u092a\u094d\u0930\u093e\u0930\u0942\u092a \u0909\u092a\u092f\u094b\u0917 \u0915\u0930\u0947\u0902 \u0914\u0930 \u0935\u094d\u092f\u0935\u0938\u094d\u0925\u093e\u092a\u0915 \u0938\u0947 \u0938\u0902\u092a\u0930\u094d\u0915 \u0915\u0930\u0947\u0902\u0964'],
    'smtpEnhanced7.4': ['\u0938\u0941\u0930\u0915\u094d\u0937\u093e \u0938\u0941\u0935\u093f\u0927\u093e \u0938\u092e\u0930\u094d\u0925\u093f\u0924 \u0928\u0939\u0940\u0902', '\u092a\u094d\u0930\u093e\u092a\u094d\u0924\u0915\u0930\u094d\u0924\u093e \u092a\u094d\u0930\u0923\u093e\u0932\u0940 \u0905\u0928\u0941\u0930\u094b\u0927\u093f\u0924 \u0938\u0941\u0930\u0915\u094d\u0937\u093e \u0938\u0941\u0935\u093f\u0927\u093e \u0915\u093e \u0938\u092e\u0930\u094d\u0925\u0928 \u0928\u0939\u0940\u0902 \u0915\u0930\u0924\u0940\u0964', '\u092a\u0930\u093f\u0935\u0939\u0928 \u0938\u0941\u0930\u0915\u094d\u0937\u093e \u0915\u092e\u091c\u094b\u0930 \u0915\u093f\u090f \u092c\u093f\u0928\u093e \u0938\u092e\u0930\u094d\u0925\u093f\u0924 \u092a\u094d\u0930\u092e\u093e\u0923\u0940\u0915\u0930\u0923 \u092f\u093e \u0938\u0941\u0930\u0915\u094d\u0937\u093f\u0924 \u0938\u0902\u0926\u0947\u0936 \u0935\u093f\u0927\u093f \u0909\u092a\u092f\u094b\u0917 \u0915\u0930\u0947\u0902\u0964'],
    'smtpEnhanced7.5': ['\u0915\u094d\u0930\u093f\u092a\u094d\u091f\u094b\u0917\u094d\u0930\u093e\u092b\u093c\u093f\u0915 \u0938\u0924\u094d\u092f\u093e\u092a\u0928 \u0935\u093f\u092b\u0932', '\u0906\u0935\u0936\u094d\u092f\u0915 \u0915\u0941\u0902\u091c\u0940 \u092f\u093e \u092a\u094d\u0930\u092e\u093e\u0923\u092a\u0924\u094d\u0930 \u0905\u0928\u0941\u092a\u0938\u094d\u0925\u093f\u0924 \u092f\u093e \u0905\u092e\u093e\u0928\u094d\u092f \u0939\u0948\u0964 \u092a\u094d\u0930\u0926\u093e\u0924\u093e TLS \u092f\u093e MTA-STS \u092a\u094d\u0930\u092e\u093e\u0923\u092a\u0924\u094d\u0930 \u091c\u093e\u0901\u091a \u0915\u0947 \u0932\u093f\u090f \u092d\u0940 \u092f\u0939 \u0915\u094b\u0921 \u0926\u0947 \u0938\u0915\u0924\u093e \u0939\u0948\u0964', '\u0938\u092e\u093e\u092a\u094d\u0924\u093f, \u0939\u094b\u0938\u094d\u091f \u0928\u093e\u092e, \u092d\u0930\u094b\u0938\u0947 \u0915\u0940 \u0936\u0943\u0902\u0916\u0932\u093e \u0914\u0930 \u0938\u0902\u092c\u0902\u0927\u093f\u0924 \u0938\u0902\u0926\u0947\u0936 \u092f\u093e \u092a\u0930\u093f\u0935\u0939\u0928 \u0938\u0941\u0930\u0915\u094d\u0937\u093e \u0928\u0940\u0924\u093f \u091c\u093e\u0901\u091a\u0947\u0902\u0964'],
    'smtpEnhanced7.6': ['\u0915\u094d\u0930\u093f\u092a\u094d\u091f\u094b\u0917\u094d\u0930\u093e\u092b\u093c\u093f\u0915 \u090f\u0932\u094d\u0917\u094b\u0930\u093f\u0926\u092e \u0938\u092e\u0930\u094d\u0925\u093f\u0924 \u0928\u0939\u0940\u0902', '\u092a\u094d\u0930\u0947\u0937\u0915 \u0914\u0930 \u092a\u094d\u0930\u093e\u092a\u094d\u0924\u0915\u0930\u094d\u0924\u093e \u092e\u0947\u0902 \u0906\u0935\u0936\u094d\u092f\u0915 \u0938\u093e\u091d\u093e \u090f\u0932\u094d\u0917\u094b\u0930\u093f\u0926\u092e \u0909\u092a\u0932\u092c\u094d\u0927 \u0928\u0939\u0940\u0902 \u0939\u0948\u0964', '\u092a\u094d\u0930\u0923\u093e\u0932\u093f\u092f\u093e\u0901 \u0905\u0926\u094d\u092f\u0924\u0928 \u0915\u0930\u0947\u0902 \u0914\u0930 \u0926\u094b\u0928\u094b\u0902 \u092e\u0947\u0902 \u0938\u092e\u0930\u094d\u0925\u093f\u0924 \u0938\u0941\u0930\u0915\u094d\u0937\u093f\u0924 \u090f\u0932\u094d\u0917\u094b\u0930\u093f\u0926\u092e \u091a\u0941\u0928\u0947\u0902\u0964'],
    'smtpEnhanced7.7': ['\u0938\u0902\u0926\u0947\u0936 \u0915\u0940 \u0905\u0916\u0902\u0921\u0924\u093e \u091c\u093e\u0901\u091a \u0935\u093f\u092b\u0932', '\u0938\u093e\u092e\u0917\u094d\u0930\u0940 \u092c\u0926\u0932\u0940 \u0917\u0908 \u092f\u093e \u0915\u094d\u0930\u093f\u092a\u094d\u091f\u094b\u0917\u094d\u0930\u093e\u092b\u093c\u093f\u0915 \u0905\u0916\u0902\u0921\u0924\u093e \u0938\u0924\u094d\u092f\u093e\u092a\u0928 \u0935\u093f\u092b\u0932 \u0939\u0941\u0906\u0964', '\u0917\u0947\u091f\u0935\u0947 \u092f\u093e \u0905\u0917\u094d\u0930\u0947\u0937\u0923 \u0915\u0947 \u092c\u0926\u0932\u093e\u0935 \u0916\u094b\u091c\u0947\u0902 \u0914\u0930 \u0939\u0938\u094d\u0924\u093e\u0915\u094d\u0937\u0930 \u0938\u0947\u091f\u093f\u0902\u0917 \u091c\u093e\u0901\u091a\u0947\u0902\u0964'],
    'smtpEnhanced7.8': ['\u092a\u094d\u0930\u092e\u093e\u0923\u0940\u0915\u0930\u0923 \u0915\u094d\u0930\u0947\u0921\u0947\u0902\u0936\u093f\u092f\u0932 \u0905\u0938\u094d\u0935\u0940\u0915\u093e\u0930', 'AUTH \u092e\u0947\u0902 \u0905\u092e\u093e\u0928\u094d\u092f \u092f\u093e \u0905\u092a\u0930\u094d\u092f\u093e\u092a\u094d\u0924 \u0915\u094d\u0930\u0947\u0921\u0947\u0902\u0936\u093f\u092f\u0932 \u0909\u092a\u092f\u094b\u0917 \u0939\u0941\u090f\u0964', '\u0916\u093e\u0924\u093e, OAuth \u092f\u093e \u0938\u092e\u0930\u094d\u0925\u093f\u0924 \u0935\u093f\u0927\u093f, \u0910\u092a \u0905\u0928\u0941\u092e\u0924\u093f\u092f\u093e\u0901 \u0914\u0930 \u0938\u0947\u0935\u093e \u0938\u0947\u091f\u093f\u0902\u0917 \u091c\u093e\u0901\u091a\u0947\u0902\u0964'],
    'smtpEnhanced7.9': ['\u092a\u094d\u0930\u092e\u093e\u0923\u0940\u0915\u0930\u0923 \u0924\u0930\u0940\u0915\u093e \u0915\u092e\u091c\u094b\u0930 \u0939\u0948', '\u091a\u0941\u0928\u0940 \u0917\u0908 \u0935\u093f\u0927\u093f \u092a\u094d\u0930\u093e\u092a\u094d\u0924\u0915\u0930\u094d\u0924\u093e \u0915\u0940 \u0928\u0940\u0924\u093f \u092a\u0942\u0930\u0940 \u0928\u0939\u0940\u0902 \u0915\u0930\u0924\u0940\u0964', '\u0938\u0930\u094d\u0935\u0930 \u0915\u0940 \u0918\u094b\u0937\u093f\u0924 \u0905\u0927\u093f\u0915 \u092e\u091c\u092c\u0942\u0924 \u0935\u093f\u0927\u093f \u0909\u092a\u092f\u094b\u0917 \u0915\u0930\u0947\u0902 \u0914\u0930 TLS \u091a\u093e\u0932\u0942 \u0930\u0916\u0947\u0902\u0964'],
    'smtpEnhanced7.10': ['\u090f\u0928\u094d\u0915\u094d\u0930\u093f\u092a\u094d\u091f \u0915\u093f\u092f\u093e \u0915\u0928\u0947\u0915\u094d\u0936\u0928 \u0906\u0935\u0936\u094d\u092f\u0915', '\u092a\u094d\u0930\u092e\u093e\u0923\u0940\u0915\u0930\u0923 \u0935\u093f\u0927\u093f \u0915\u094b \u0905\u0927\u093f\u0915 \u092e\u091c\u092c\u0942\u0924 \u0917\u094b\u092a\u0928\u0940\u092f\u0924\u093e \u0938\u094d\u0924\u0930 \u091a\u093e\u0939\u093f\u090f\u0964', '\u0938\u093e\u0907\u0928-\u0907\u0928 \u0938\u0947 \u092a\u0939\u0932\u0947 TLS \u0938\u094d\u0925\u093e\u092a\u093f\u0924 \u0915\u0930\u0947\u0902 \u092f\u093e \u0905\u0927\u093f\u0915 \u092e\u091c\u092c\u0942\u0924 \u0938\u092e\u0930\u094d\u0925\u093f\u0924 \u0935\u093f\u0927\u093f \u0909\u092a\u092f\u094b\u0917 \u0915\u0930\u0947\u0902\u0964'],
    'smtpEnhanced7.11': ['\u092a\u094d\u0930\u092e\u093e\u0923\u0940\u0915\u0930\u0923 \u0915\u0947 \u0932\u093f\u090f \u090f\u0928\u094d\u0915\u094d\u0930\u093f\u092a\u094d\u0936\u0928 \u0905\u0928\u093f\u0935\u093e\u0930\u094d\u092f', '\u092f\u0939 \u0935\u093f\u0927\u093f \u0905\u0928\u090f\u0928\u094d\u0915\u094d\u0930\u093f\u092a\u094d\u091f\u0947\u0921 \u0915\u0928\u0947\u0915\u094d\u0936\u0928 \u092a\u0930 \u0909\u092a\u092f\u094b\u0917 \u0928\u0939\u0940\u0902 \u0915\u0940 \u091c\u093e \u0938\u0915\u0924\u0940\u0964', '\u0938\u093e\u0907\u0928-\u0907\u0928 \u0938\u0947 \u092a\u0939\u0932\u0947 STARTTLS \u092f\u093e \u0926\u0938\u094d\u0924\u093e\u0935\u0947\u091c\u093c \u092e\u0947\u0902 \u0926\u093f\u092f\u093e TLS \u090f\u0902\u0921\u092a\u0949\u0907\u0902\u091f \u0938\u0947\u091f \u0915\u0930\u0947\u0902\u0964'],
    'smtpEnhanced7.12': ['\u0916\u093e\u0924\u0947 \u0915\u093e \u092a\u094d\u0930\u092e\u093e\u0923\u0940\u0915\u0930\u0923 \u092a\u0930\u093f\u0935\u0930\u094d\u0924\u0928 \u0906\u0935\u0936\u094d\u092f\u0915', '\u091a\u0941\u0928\u0940 \u0935\u093f\u0927\u093f \u0909\u092a\u092f\u094b\u0917 \u0915\u0930\u0928\u0947 \u0938\u0947 \u092a\u0939\u0932\u0947 \u0916\u093e\u0924\u0947 \u0915\u093e \u092a\u0930\u093f\u0935\u0930\u094d\u0924\u0928 \u0906\u0935\u0936\u094d\u092f\u0915 \u0939\u0948\u0964', '\u0938\u0941\u0930\u0915\u094d\u0937\u093f\u0924 \u0915\u0928\u0947\u0915\u094d\u0936\u0928 \u092a\u0930 \u092a\u094d\u0930\u0926\u093e\u0924\u093e \u0915\u0940 \u0926\u0938\u094d\u0924\u093e\u0935\u0947\u091c\u093c\u0940\u0915\u0943\u0924 \u092a\u0930\u093f\u0935\u0930\u094d\u0924\u0928 \u092a\u094d\u0930\u0915\u094d\u0930\u093f\u092f\u093e \u0905\u092a\u0928\u093e\u090f\u0901\u0964'],
    'smtpEnhanced7.13': ['\u0916\u093e\u0924\u093e \u0905\u0915\u094d\u0937\u092e \u092f\u093e \u092a\u094d\u0930\u093e\u092a\u094d\u0924\u0915\u0930\u094d\u0924\u093e \u092a\u094d\u0930\u0924\u093f\u092c\u0902\u0927\u093f\u0924', '\u092e\u093e\u0928\u0915 \u0905\u0930\u094d\u0925 \u0905\u0915\u094d\u0937\u092e \u0916\u093e\u0924\u093e \u0939\u0948\u0964 Exchange Online \u0906\u0902\u0924\u0930\u093f\u0915 \u092a\u094d\u0930\u092e\u093e\u0923\u093f\u0924 \u092a\u094d\u0930\u0947\u0937\u0915\u094b\u0902 \u0924\u0915 \u0938\u0940\u092e\u093f\u0924 \u0938\u093e\u0930\u094d\u0935\u091c\u0928\u093f\u0915 \u092b\u093c\u094b\u0932\u094d\u0921\u0930 \u0915\u0947 \u0932\u093f\u090f \u092d\u0940 \u092f\u0939 \u0915\u094b\u0921 \u0926\u0947\u0924\u093e \u0939\u0948\u0964', '\u092a\u094d\u0930\u0926\u093e\u0924\u093e \u0914\u0930 \u092a\u0942\u0930\u0940 \u092a\u094d\u0930\u0924\u093f\u0915\u094d\u0930\u093f\u092f\u093e \u091c\u093e\u0901\u091a\u0947\u0902\u0964 \u0916\u093e\u0924\u0947 \u0915\u0947 \u0935\u094d\u092f\u0935\u0938\u094d\u0925\u093e\u092a\u0915 \u092f\u093e \u092b\u093c\u094b\u0932\u094d\u0921\u0930 \u092e\u093e\u0932\u093f\u0915 \u0938\u0947 \u092a\u094d\u0930\u0924\u093f\u092c\u0902\u0927 \u0915\u0940 \u0938\u092e\u0940\u0915\u094d\u0937\u093e \u0915\u0930\u093e\u090f\u0901\u0964'],
    'smtpEnhanced7.20': ['\u0915\u094b\u0908 \u0938\u092b\u0932 DKIM \u0939\u0938\u094d\u0924\u093e\u0915\u094d\u0937\u0930 \u0928\u0939\u0940\u0902', '\u0938\u0902\u0926\u0947\u0936 \u092e\u0947\u0902 \u0910\u0938\u093e DKIM \u0939\u0938\u094d\u0924\u093e\u0915\u094d\u0937\u0930 \u0928\u0939\u0940\u0902 \u0939\u0948 \u091c\u093f\u0938\u0947 \u092a\u094d\u0930\u093e\u092a\u094d\u0924\u0915\u0930\u094d\u0924\u093e \u0938\u0924\u094d\u092f\u093e\u092a\u093f\u0924 \u0915\u0930 \u0938\u0915\u0947\u0964', '\u0935\u093e\u0938\u094d\u0924\u0935\u093f\u0915 \u092d\u0947\u091c\u0928\u0947 \u0935\u093e\u0932\u0940 \u0938\u0947\u0935\u093e \u092e\u0947\u0902 DKIM \u091a\u093e\u0932\u0942 \u0915\u0930\u0947\u0902, \u0938\u0939\u0940 \u091a\u092f\u0928\u0915\u0930\u094d\u0924\u093e \u092a\u094d\u0930\u0915\u093e\u0936\u093f\u0924 \u0915\u0930\u0947\u0902 \u0914\u0930 \u0939\u0938\u094d\u0924\u093e\u0915\u094d\u0937\u0930 \u0915\u0947 \u092c\u093e\u0926 \u0938\u0902\u0926\u0947\u0936 \u092c\u0926\u0932\u093e\u0935 \u091c\u093e\u0901\u091a\u0947\u0902\u0964'],
    'smtpEnhanced7.21': ['\u0915\u094b\u0908 \u0938\u094d\u0935\u0940\u0915\u093e\u0930\u094d\u092f DKIM \u0939\u0938\u094d\u0924\u093e\u0915\u094d\u0937\u0930 \u0928\u0939\u0940\u0902', 'DKIM \u0939\u0938\u094d\u0924\u093e\u0915\u094d\u0937\u0930 \u0938\u0924\u094d\u092f\u093e\u092a\u093f\u0924 \u0939\u0941\u0906 \u0932\u0947\u0915\u093f\u0928 \u092a\u094d\u0930\u093e\u092a\u094d\u0924\u0915\u0930\u094d\u0924\u093e \u0928\u0940\u0924\u093f \u092a\u0942\u0930\u0940 \u0928\u0939\u0940\u0902 \u0915\u0930\u0924\u093e\u0964', '\u0939\u0938\u094d\u0924\u093e\u0915\u094d\u0937\u0930 \u0921\u094b\u092e\u0947\u0928, \u090f\u0932\u094d\u0917\u094b\u0930\u093f\u0926\u092e, \u0915\u0941\u0902\u091c\u0940 \u0915\u0940 \u092e\u091c\u092c\u0942\u0924\u0940 \u0914\u0930 \u092a\u094d\u0930\u093e\u092a\u094d\u0924\u0915\u0930\u094d\u0924\u093e \u0915\u0940 \u0906\u0935\u0936\u094d\u092f\u0915\u0924\u093e\u090f\u0901 \u091c\u093e\u0901\u091a\u0947\u0902\u0964'],
    'smtpEnhanced7.22': ['DKIM \u0921\u094b\u092e\u0947\u0928 \u0932\u0947\u0916\u0915 \u0938\u0947 \u092e\u0947\u0932 \u0928\u0939\u0940\u0902 \u0916\u093e\u0924\u093e', '\u0935\u0948\u0927 \u0939\u0938\u094d\u0924\u093e\u0915\u094d\u0937\u0930 \u0915\u093e \u0921\u094b\u092e\u0947\u0928 \u0906\u0935\u0936\u094d\u092f\u0915 From \u0921\u094b\u092e\u0947\u0928 \u0938\u0947 \u092e\u0947\u0932 \u0928\u0939\u0940\u0902 \u0916\u093e\u0924\u093e\u0964', '\u092d\u0947\u091c\u0928\u0947 \u0935\u093e\u0932\u0940 \u0938\u0947\u0935\u093e \u0915\u094b \u0926\u093f\u0916\u093e\u0908 \u0926\u0947\u0928\u0947 \u0935\u093e\u0932\u0947 From \u092a\u0924\u0947 \u0915\u0947 \u0905\u0928\u0941\u0930\u0942\u092a \u0921\u094b\u092e\u0947\u0928 \u0938\u0947 \u0939\u0938\u094d\u0924\u093e\u0915\u094d\u0937\u0930 \u0915\u0930\u0928\u0947 \u0915\u0947 \u0932\u093f\u090f \u0938\u0947\u091f \u0915\u0930\u0947\u0902\u0964'],
    'smtpEnhanced7.23': ['SPF \u0938\u0924\u094d\u092f\u093e\u092a\u0928 \u0935\u093f\u092b\u0932 \u0939\u0941\u0906', '\u0935\u093e\u0938\u094d\u0924\u0935\u093f\u0915 \u092d\u0947\u091c\u0928\u0947 \u0935\u093e\u0932\u093e IP \u090f\u0928\u0935\u0947\u0932\u092a \u092a\u094d\u0930\u0947\u0937\u0915 \u0921\u094b\u092e\u0947\u0928 \u0915\u0940 SPF \u0928\u0940\u0924\u093f \u092e\u0947\u0902 \u0905\u0927\u093f\u0915\u0943\u0924 \u0928\u0939\u0940\u0902 \u0939\u0948\u0964', 'MAIL FROM \u0914\u0930 \u092d\u0947\u091c\u0928\u0947 \u0935\u093e\u0932\u0940 \u0938\u0947\u0935\u093e \u091c\u093e\u0901\u091a\u0947\u0902\u0964 DNS \u0916\u094b\u091c \u0938\u0940\u092e\u093e \u0915\u0947 \u092d\u0940\u0924\u0930 \u0938\u0947\u0935\u093e \u0915\u094b \u0905\u0928\u0941\u092e\u0924\u093f \u0926\u0947\u0928\u0947 \u0935\u093e\u0932\u093e \u090f\u0915 \u0935\u0948\u0927 SPF \u0930\u093f\u0915\u0949\u0930\u094d\u0921 \u092a\u094d\u0930\u0915\u093e\u0936\u093f\u0924 \u0915\u0930\u0947\u0902\u0964'],
    'smtpEnhanced7.24': ['SPF \u092e\u0942\u0932\u094d\u092f\u093e\u0902\u0915\u0928 \u0924\u094d\u0930\u0941\u091f\u093f', 'DNS \u0924\u094d\u0930\u0941\u091f\u093f, \u0915\u0908 SPF \u0930\u093f\u0915\u0949\u0930\u094d\u0921, \u0917\u0932\u0924 \u092a\u094d\u0930\u093e\u0930\u0942\u092a \u092f\u093e \u092c\u0939\u0941\u0924 \u0905\u0927\u093f\u0915 \u0916\u094b\u091c\u094b\u0902 \u0928\u0947 \u092e\u0942\u0932\u094d\u092f\u093e\u0902\u0915\u0928 \u0930\u094b\u0915\u093e\u0964', 'DNS \u092f\u093e SPF \u0938\u0941\u0927\u093e\u0930\u0947\u0902, include \u0914\u0930 redirect \u091c\u093e\u0901\u091a\u0947\u0902, \u090f\u0915 \u0939\u0940 \u0930\u093f\u0915\u0949\u0930\u094d\u0921 \u0930\u0916\u0947\u0902 \u0914\u0930 DNS \u0916\u094b\u091c\u0928\u0947 \u0935\u093e\u0932\u0947 \u0905\u0927\u093f\u0915\u0924\u092e \u0926\u0938 \u092a\u0926\u094b\u0902 \u0915\u0940 \u0938\u0940\u092e\u093e \u092e\u093e\u0928\u0947\u0902\u0964'],
    'smtpEnhanced7.25': ['\u0930\u093f\u0935\u0930\u094d\u0938 DNS \u0938\u0924\u094d\u092f\u093e\u092a\u0928 \u0935\u093f\u092b\u0932', '\u092d\u0947\u091c\u0928\u0947 \u0935\u093e\u0932\u0947 IP \u0915\u093e \u0938\u094d\u0935\u0940\u0915\u093e\u0930\u094d\u092f PTR \u092f\u093e \u0909\u0938\u0938\u0947 \u092e\u0947\u0932 \u0916\u093e\u0924\u093e \u092b\u093c\u0949\u0930\u0935\u0930\u094d\u0921 DNS \u0928\u0939\u0940\u0902 \u0939\u0948\u0964', 'IP \u092e\u093e\u0932\u093f\u0915 \u0938\u0947 \u092a\u094d\u0930\u0926\u093e\u0924\u093e \u0915\u0940 \u0906\u0935\u0936\u094d\u092f\u0915\u0924\u093e \u0905\u0928\u0941\u0938\u093e\u0930 PTR \u0914\u0930 \u092e\u0947\u0932 \u0916\u093e\u0924\u0947 A/AAAA \u0938\u0947\u091f \u0915\u0930\u0928\u0947 \u0915\u094b \u0915\u0939\u0947\u0902\u0964'],
